/* 平成21年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h21.committeeSessions.push(...[{"id":"h21-20090309-3","meetingId":"h21-c-budget","date":"2009年3月9日","dateIso":"2009-03-09","committee":"予算特別委員会","time":"午前１０時０２分～午後６時２３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を157件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２１年度品川区一般会計予算","agenda":"平成２１年度品川区一般会計予算","exchanges":[{"speaker":"原委員","kind":"質問・要望","question":"先にページ数を申し上げますと、９７ページ、次に１１４ページ、１１５ページ、１１６ページ、１１７ページのところで、具体的には大崎駅周辺ならびに、大分高層ビルが建ってきておりまして、五反田駅周辺のところから質問させていただきたいと思います。ですから、いろいろなことがあるでしょうけれども、実際に区のほうに、ざっくり全体でどのぐらい入れたか。よろしくお願いします。","respondent":"青木都市開発課長","answer":"大崎五丁目等、これから区の投資があるだろうというご指摘ですけれども、現在、大崎五丁目に限らず、品川区では、大崎駅周辺地域だけではなくて、五反田駅周辺まで視野を広げまして、今後のまちのあり方について、地元の方々ともお話し合いを進めながら考えていこうということで。","voiceIndex":4,"id":"exchange-001"},{"speaker":"原委員","kind":"質問","question":"ただ、こういう時節柄ですので、今後、数年単位で、ではそれがそのままでいいのか、どうなのかということを考えますと、実際に入れたものはまだ不確定ですよということですとか、そういう形ではなくて、実際に、それに対する数字がないとしたら、投下するものに対する保全措置がとられているのかどうか、その辺のところまでちょっと突っこんで考えて。","respondent":"青木都市開発課長","answer":"これが今、再開発事業等に関してでございまして、それから品川区独自に国庫補助などを導入して公共施設の整備をやっているものがございまして、こちらに関しては約１.５８という数字がありまして、１の投資に対して１.５８倍の経済効果が見込まれるというような試算があります。","voiceIndex":6,"id":"exchange-002"},{"speaker":"原委員","kind":"意見","question":"数字的には、非常にいい数字だと思います。今度は逆に、ではそれが入ったからいいのかといいますと、やはり品川区は区民に対して何をやっていくのか。いろいろな施設関係等、等があるかどうかというのを、ちょっとお聞かせいただければと思います。","respondent":"青木都市開発課長","answer":"大崎駅周辺で言えば、目黒川というものがありますので、これを環境資源として生かしまして、まず目黒川を環境浄化していく、あわせて、親水広場とか、水と緑のネットワークの中での位置づけをしまして、人々が憩えるような施設もあわせて整備していているという形で、ソフト。","voiceIndex":8,"id":"exchange-003"},{"speaker":"原委員","kind":"質問・要望","question":"実際に、そういった形で産業界だけではなくて、いろいろな大学等との連携をやっておられると思いますので、これは要望として、そういった面で、一層お願いをしていければと思います。よろしくお願いします。","respondent":"市川教育次長","answer":"御殿山小学校の改築につきましては、基本的な考え方につきましては、これまで所管の委員会のほうにも報告をさせていただいているところですけれども、北品川五丁目の再開発事業の進捗状況を見極めた上で改築をするという基本的な考え方を示してまいりました。","voiceIndex":10,"id":"exchange-004"},{"speaker":"原委員","kind":"質問","question":"そうしましたら、その中で、特に注意というか、お願いをしたいことは、やはり再開発エリア、日影の問題なんですね。この辺は、民間の場合には、最近はトラブルは出てこないんです、もうご存じのように。ところが学校ということになりますと、それはちょっとまた観点が違うものですから、その辺について、一言いただければと思います。","respondent":"青木都市開発課長","answer":"これは、引き続き詳細に検討しながら、計画を進めいきたいと考えています。","voiceIndex":12,"id":"exchange-005"},{"speaker":"浅野委員","kind":"質問","question":"私のほうからは、８２ページの使用料及び手数料、総務手数料の住民基本台帳証明手数料、関連しまして、１２０ページの都支出金と委託金、総務費委託金の住民基本台帳人口調査費、１３６ページ、諸収入、雑入の広告料収入、これについてお伺いしたいと思います。地域的に多い、少ないとかいう傾向があるのか、どうか、お伺いしたいと思います。","respondent":"上川内戸籍住民課長","answer":"サービスコーナーですが、武蔵小山はまだ１年ちょっとということもありますので、そのまま比較はできませんが、サービスコーナーで見ますと、大井サービスコーナー対武蔵小山サービスコーナーは８対２ということになっております。","voiceIndex":15,"id":"exchange-006"},{"speaker":"浅野委員","kind":"提案","question":"地域的にも、やはりいろいろな環境等で違いがあるかと思うんです。ほかの自治体をあまり出したくないんですけれども、振込確認後に送付するとか、また、代引きでやって、７５０円かかってしまうとか、そういうところもあるわけです。さらに、利便性を考えたこういう取り組みも、品川区としては、今後も必要ではないかと考えますが、ご所見をお伺いします。","respondent":"原情報システム課長","answer":"そういった意味では、品川区といたしましては、そういった動向に十分に注意しながら、拡大を検討してまいりたいと考えているところです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"浅野委員","kind":"質問・要望","question":"ぜひとも、動向を見ながら、住民サービスの拡大に努めていただきたいと思います。これは、以前にもちょっと質問させていただきましたけれども、保健所、保健センター、今回、統合されるという方針ですけれども、こちらのほうの電子申請も二つに分かれているという状況ですが、間違いなく４月１日時点では、１カ所だけに、二つを一つに統合して申請できるように、これは確認を含めて、要望しておきます。","respondent":"上川内戸籍住民課長","answer":"なりすましとか、カードの偽造がやはり多うございまして、それを防ぐために、自治体ごとにカードをつくっているので、書いてあることは同じなんですけれども、カードの表面の模様とか仕様が違うので、全国共通になるとわかりにくいという声もありましたので。","voiceIndex":19,"id":"exchange-008"},{"speaker":"浅野委員","kind":"質問","question":"これにつきましては、公明党がもう１０年間がかりで取り組んできた政策でございまして、いよいよ実現化する、３年以内に実現化されるという運びとなったと感じております。ちょっと時間がなくなりましたので、少しピッチを上げていきたいと思います。新しいものについては、政策分としてやっているわけですけれども、この内訳についても、その政策と経常の違いを、簡単にお願いします。","respondent":"中川原広報広聴課長","answer":"しながわガイドの内訳ですが、これは、数年に一遍、全戸配布を行うものです。そのほか、毎年、転入者用に印刷しているということで、平成２１年度は全戸配布分と、その配布までの転入者分、両方を予算要求しているものです。","voiceIndex":21,"id":"exchange-009"},{"speaker":"浅野委員","kind":"意見","question":"前回、しながわガイドは約１５０ページ立てで、８ページが広告だったと思うんです。何回か議会にも出ておりますけれども、裏表紙は１件当たり１０２万円だったわけです。１号、３号、５号、たしか６号だったと思うんですけれども、そのような区別があるのは、やはり見え方かなと思います。広告料収入については、今回、新しいしながわガイドを出すために何か考えられたことがあれば、お願いします。","respondent":"中川原広報広聴課長","answer":"今回、特別に考えていることとしましては、南東京ケーブルテレビが、今までの広告を変えまして、もう少し事業内容等を詳しくしたものを充実させたいと言っておりますので、そういった意味では、従来の広告とは少し変わった広告の注文を取っていきたいと考えているところです。","voiceIndex":23,"id":"exchange-010"},{"speaker":"浅野委員","kind":"質問・要望","question":"しながわガイドは、これだけのものが各戸配布されるということなので、かなり収益の大きな柱になるかと思いますけれども、これについては、やはりこれからもどんどん進めていくような形をとっていただきたいと思います。いろいろ工夫をこらして、増収というんでしょうか、そういうような計画はあるのか、ないのか。","respondent":"中川原広報広聴課長","answer":"ホームページリニューアルを終わりまして、１年間様子を見ましたら、かなり広告の希望者が多いものですから、見やすさというのはあるんですけれども、ああいった形で事業者に広告を入れていただくことで、私どものホームページの運営経費に充てするという考えから。","voiceIndex":25,"id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"広告につきましては、ページによって見る人も違うということを考えて、例えば住宅のページには不動産関係の広告を出すという手法も、いろいろな業界で行われていますので、ぜひとも、この点についても検討をいただければと思います。そしてまた、区から送付する封筒なんかに広告を掲載するというところもあります。ここら辺についてのお考えがあれば、お伺いします。","respondent":"中川原広報広聴課長","answer":"封筒等につきましては、戸籍住民課でもやった経験もありますし、今後、広告料の収入ということで、検討してまいりたいと考えています。","voiceIndex":27,"id":"exchange-012"},{"speaker":"浅野委員","kind":"質問","question":"庁舎のロビーなどに設置されているテレビモニターが２台ありますけれども、こちらのほうに広告を流すという件はどうでしょうか。","respondent":"中川原広報広聴課長","answer":"さまざまなものについて、広告について、今後、検討していきたいと考えています。","voiceIndex":29,"id":"exchange-013"},{"speaker":"菊地委員","kind":"質問","question":"１１４ページにあります、都補助金の特別養護老人ホームの整備費に関連してお聞きしたいと思います。３７０万円余というのは、八潮に増設する特別養護老人ホームの出来高３％分ということなんですが、区として、特別養護老人ホームに対する考え方なんかは、この間、出されておりますので、目標をどのように持っているのかという点を、お聞きしたいと思います。この辺もお聞かせ願いたいと思います。","respondent":"冨岡高齢福祉課長","answer":"特別養護老人ホームの建設の目標ですが、これにつきましては、現在、長期基本計画を策定しておりまして、計画内に建設をするということで計画化していることですので、具体的には、実施計画の中で具体的に上げていくところです。したがいまして、当然、建設をするです。","voiceIndex":32,"id":"exchange-014"},{"speaker":"菊地委員","kind":"質問・要望","question":"１号被保険者が６万８,０００人ぐらいでしょうかね。その辺を考え合わせれば、きっちりと年次計画というものを早急につくるべきだと思うんです。５００名の待機者は、ほんとうにあす、あさって困っているわけですから、その辺をきっちり考えて年次計画をつくるべきではないかと思います。ちょっと基準のところをもう少し明確に、先ほども申し上げたように、はっきりさせていただきたいと思います。","respondent":"冨岡高齢福祉課長、木下福祉高齢事業部長","answer":"明確な基準というのはございませんけれども、例えば、広さですが、大体３,０００m2の広さは必要だと理解をしております。特別養護老人ホーム整備の今後の考え方というお尋ねかと思いますけれども、高齢福祉課長のほうからも申し上げましたように、現在、八潮南中学校の特別養護老人ホームは予定しておりますけれども、それ以降の部分について。","voiceIndex":34,"id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"平成２０年から２２年の間でしょうか、３年間は、整備率が１.０未満の自治体には、１ベッド当たり従来の１.５倍の加算がされて、６５４万円の補助金が投入されるとなっていますよね。八潮の８０ベッドを入れても１.０未満ですから、非常に低い整備率だと思いますけれども、この制度があるうちに整備方針を明確に示すべきだと、固めるべきだというふうに思いますけれども、その辺はいかがでしょうか。","respondent":"木下福祉高齢事業部長","answer":"そのようなことも含めまして、今後、諸条件を見極めながら考えていこうというのが区の考え方です。","voiceIndex":37,"id":"exchange-016"},{"speaker":"菊地委員","kind":"質問","question":"本来、やっぱりそこをしっかりと見据えて計画を持つということが必要ですし、今、部長の答弁もあったように、加算のところでは、その後どうなるかはわかりませんけれども、少なくとも３年間しかこれを使えないわけですから、やっぱりここでしっかりとした方針、目標を出すべきではないかと思うんです。","respondent":"木下福祉高齢事業部長","answer":"そういう点では、八潮の特別養護老人ホームの整備をすることによって、その部分については、より磐石なものになるだろうと考えています。その後のことにつきましては、この辺の整備をまずは優先をさせていただきたいと考えています。","voiceIndex":39,"id":"exchange-017"},{"speaker":"菊地委員","kind":"質問","question":"真に必要な方というのは、以前からそういうご答弁をなさいますけれども、真に必要な方が入れているから、特別養護老人ホームは整備はしないんだとずっと言い続けてきている。真に必要な方が入れていなかったという現状を見ての上ではないんですか。そうでなければ、増設の必要はないわけですから、おかしいでしょ、今の答弁は。","respondent":"木下福祉高齢事業部長","answer":"そういう意味では、現時点での入所調整の一定の対応の部分と、今後の高齢者人口の増の部分で政策については考えているです。","voiceIndex":41,"id":"exchange-018"},{"speaker":"菊地委員","kind":"質問","question":"３,０００m2ぐらいの土地が必要だと言っているんですけれども、小さな規模であれば、十分に特別養護老人ホームをつくる土地を探すことは可能だと思います。特別養護老人ホームが必要だと判断された皆さん方というのは、収入でも、介護の面でも大変な状況にあるわけですから、やはりきっちり目標を持った流れをつくり出すべきだということを言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-019"},{"speaker":"稲川委員","kind":"質問","question":"５２ページ、軽自動車税についてお伺いしたいんですが、５３ページに調定額と書いてございまして、本年度が１億円と書いてあって、調定額が１億２６０万円と書いてあるんですが、本年度のこの予算がここに来るのではないかと、僕は勝手に解釈をしているんですが、その辺を教えてください。","respondent":"武内税務課長","answer":"年度当初では、１億２６０万円ほどの金額の課税をする予定で、その後、収入率として９４.５４％を見込みまして、１年間で入るのが９,７００万円という金額を計上させていただいているです。","voiceIndex":45,"id":"exchange-020"},{"speaker":"稲川委員","kind":"質問","question":"毎回、たばこ税についてお伺いをしているんですが、先ほども説明にございましたように、マイナス６.１％ということで、今後、どんどん世の中の事情で、だんだん吸わなくなってくるとは思うんですが、たばこ税のあり方について、品川区としてどうお考えなのか。今回、３０億円を切っている状況の中で、どんどん減少傾向にあるのではないかと、私は思っているんですが、その辺、説明をお願いします。","respondent":"武内税務課長","answer":"たばこにつきましては、個人の嗜好品ということで、好きな方は幾らの値段でも吸うと聞いていますし、値段が上がると、こういう機会にやめようということもありまして、そういった意味では、税のあり方を国のほうで検討しますと、たばこ税率が上がるということが。","voiceIndex":47,"id":"exchange-021"},{"speaker":"稲川委員","kind":"質問・要望","question":"先ほど言ったように、去年の７月からタスポが導入されて、私もこの間、質問したんですが、品川区のほうもあちこちに周知をするということが、たしか答弁で返ってきたんですが、今回、減ったのは、ある程度タスポが導入されたからというとらえ方でいいのか。実を言うと、今回６.１％だったけれども、例えば５年後にはマイナス１０％ぐらいになるのではないか、その見通しがわかれば教えていただきたいんです。","respondent":"武内税務課長","answer":"健康志向ということで、たばこ離れということも、当然、影響してきますし、また社会のルールということで、喫煙できる場所がかなり制限されていくという状況が、今後生れますので、今後５年間、どういう数字になるかという部分については、マイナスになっていくと考えております。","voiceIndex":49,"id":"exchange-022"},{"speaker":"稲川委員","kind":"質問","question":"次にいきます。１１８ページの都補助金の中の密集住宅市街地整備促進事業についてなんですが、この中味についてお伺いしたいのです。","respondent":"吉川住環境整備担当課長","answer":"都補助金の２分の１の内容について、お答えいたします。２分の１というのは、補助金の対象経費の２分の１で、これは国の補助金がつかないもの、密集事業の中で、国の事業なんですが、都が加算して独自に行っている事業です。","voiceIndex":51,"id":"exchange-023"},{"speaker":"稲川委員","kind":"質問・要望","question":"次にいきます、１３８ページのリサイクル資源売払収入についてなんですが、これは、実際に役所の中で出たリサイクル品を売り払ったという解釈でよろしいんですか。それから、何を売り払ったのか、そしてその内訳と、例えばダンボールは年間どのぐらい出るのかとか、そういった部分、詳細を教えていただきたいんですが。","respondent":"秋山資源循環推進課長","answer":"内訳といたしましては、古紙が大体７,２００万円ほど、それからアルミ缶、鉄缶が２,５００万円程度、その他が１３０万円ということで、１億２,８００万円の売払収入が上がっているというものです。","voiceIndex":53,"id":"exchange-024"},{"speaker":"稲川委員","kind":"質問・要望","question":"ちょっと勉強不足で、１回、お伺いしたいんですが、普通に資源回収をして、ペットボトルとかを、工場かどこかに持って行って売り払っているという話なんですが、それはどこに載っているのか、教えていただきたいんですが。","respondent":"秋山資源循環推進課長","answer":"プラスチック製の容器包装のことだと思うんですけれども、それにつきましては、売払の収入ではなくて、処分代がかかりますので、歳出のほうで計上させていただいているものです。","voiceIndex":55,"id":"exchange-025"},{"speaker":"井桁委員","kind":"質問","question":"武蔵小山の支援センターだったり、大崎のものづくりの計画も進んでいる中で、産業の支援ということで、現在ある天王洲と、西大井のほうにそれぞれ、平成１７年、１５年と開設をされておりますが、この現状と、応募倍率、そして、利用の規定、入居対象者ということについて、ちょっとお伺いしたいと思います。","respondent":"金子産業振興課長","answer":"創業支援施設というものですから、少なくとも私どもとしましては、品川区、今後とも、住商工のバランスをよく発展させていきたいという考えから、製造業の創業を支援するという趣旨で、この施設を設けておりますが、製造業だけではなかなか入り切れない部分がありますので。","voiceIndex":58,"id":"exchange-026"},{"speaker":"井桁委員","kind":"質問","question":"ここでひとつお伺いしたいのが、やはり出て行った後にどうなっているのか。皆さんが巣立っていくと言ったほうが、この場合はいいかと思うんですけれども、どういった形で巣立っていくケースが多いのかということ。その後どうなっていっているのかといった現状の把握は、現在されていらっしゃいますでしょうか。","respondent":"金子産業振興課長","answer":"退去された後の動向というお話だと思うんですけれども、私どもは、天王洲のほうにオフィススペースが１０、それから、西大井のほうにオフィススペースが５と、ブースが１０あります。オフィススペースのほうは、残念ながら、なかなか拡大の方向で出ていかれる方が少ない。","voiceIndex":60,"id":"exchange-027"},{"speaker":"井桁委員","kind":"質問・要望","question":"先ほども申しましたが、区で行っている施設ということもありますので、ここから巣立って、品川区で活躍していっていただきたいなと思っているんですが、そういったフォローであったり、初めて始めるであったりとか、次の事業拡大といった意味で始める方が多いんでしょうけれども、その中で広げていく、区の施設から入って行って、そこから区で活躍していただきたいといった思いも強くありますので、ぜひ。","respondent":"金子産業振興課長","answer":"委員ご指摘のとおり、いつまでも品川区で、なおかつ発展していっていただければこの上ないことなんですけれども、なかなかそういう縛りをかけることも難しいところがありますけれども、委員のご趣旨を踏まえまして、今後とも、私どもとしては。","voiceIndex":62,"id":"exchange-028"},{"speaker":"井桁委員","kind":"質問","question":"創業支援施設というのは、品川区のほうでは、どんどん建てていくのかなと考えていますので、今後も、より使いやすい施設、そして、そういった支援をぜひお願いしたいと考えています。この質問は以上です。その中で、やはりこういった水辺に対するとか、全体的なまちづくりに対する景観への考え方と、今後の方向性をお伺いできればと考えています。","respondent":"梶都市計画課長","answer":"ただし、その中では、一般的なことが中心となってまいりますので、品川区に関しましては、ご案内のとおり、今のように天王洲関連の臨海地区、水辺の周辺地区、あるいは新しく開発ができている地区、あるいは商店街等の活発なにぎわいの地区、そういった点がありますので。","voiceIndex":64,"id":"exchange-029"},{"speaker":"井桁委員","kind":"質問","question":"先ほど、ご答弁の中にあった、景観行政団体、現在は東京都ということなんですけれども、２３区の中では江東区、世田谷区、新宿区、これが引き継いでいるということで、現在、都との協議中ということなんですけれども、お答えできる範囲で、その辺の進捗状況と、景観というのは、今後、きめ細やかな対応が必要になってくると思いますので、そういったきめ細やかなことをやるための条例で。","respondent":"梶都市計画課長","answer":"東京都との協議という形ですけれども、今現在も、品川区の景観に関する考え方ですとか、あるいは昨年１０月、１１月に基本的な考え方のパブリックコメントを行いましたけれども、そういった点を踏まえまして、景観計画の素案的なものを、東京都のほうと打ち合わせをしています。","voiceIndex":66,"id":"exchange-030"},{"speaker":"井桁委員","kind":"質問・要望","question":"景観の計画についてなんですけれども、今回、その助成の事業の中で出ました看板の撤去であったりとか、この助成の中にもありますように、それはかなり値段のかかるものだったりするんですが、これは都の事業なんですが、今後、この条例を品川区のほうで策定された場合に、こういった看板の撤去とか、そういったものも、今後、出てくるのでしょうか。","respondent":"松代管理工事課長","answer":"そういった意味では、当然のことながら、東京都が持っております屋外広告物条例を、品川区の屋外広告物条例という形に変えまして、よりよい形のまちづくり、景観づくりはどういったものかといったことを、今後、地域の皆様といろいろと検討してまいりたいと考えているところです。","voiceIndex":68,"id":"exchange-031"},{"speaker":"井桁委員","kind":"質問","question":"都の条例で、今度、区に移管したときに、お金といいますか、そういったものの負担は、今後、お考えでしょうか。","respondent":"松代管理工事課長","answer":"今までは、許可したものを、規制をかけて撤去していただくということで、促進を図るために東京都、品川区で負担をするものですけれども、今後の品川区の中で看板をどうしていくかというのは、まさにこれからの地域づくり、景観づくりの中で。","voiceIndex":70,"id":"exchange-032"},{"speaker":"山元委員","kind":"質問・要望","question":"１２０ページの都支出金の中に民生費委託金というところがあります。その中に、生活安定応援事業委託金、３,５００万円が計上されております。平成２１年度の当初予算案のところを見ますと、これは新規事業ということになっておりまして、低所得者対象の生活相談と書いてあります。ここのところを、理解がちょっとできていないものですから、もうちょっと詳しく教えていただきたいと思います。","respondent":"志村生活福祉課長","answer":"昨年は、平成２０年６月に補正の議決をいただきまして、執行したところでございまして、今年につきましては、平年度化ということで、１２カ月実施をしていこうという内容です。","voiceIndex":73,"id":"exchange-033"},{"speaker":"山元委員","kind":"質問・要望","question":"今、就職チャレンジ支援事業とか、生活サポートとか、いろいろ教えていただきましたけれども、何か受けるための条件とか、また、対象がどういうことなのか、もう少し詳細に教えていただきたいと思いますけれども、よろしくお願いいたします。","respondent":"志村生活福祉課長","answer":"この辺の要件を、私どものほうの相談、面接をする中で確認をしていきながら、先ほど申し上げた、いろいろなサポート事業が出てまいりますので、これについて個別の説明をさせていただいているという内容です。","voiceIndex":75,"id":"exchange-034"},{"speaker":"山元委員","kind":"質問","question":"我が品川区もスタートするということで、実際にいろいろな貸付事業が始まるわけですけれども、いろいろな項目にある程度目標といいますか、助成を受けられる人数の枠というんですか、そういうものはあるんでしょうか。","respondent":"志村生活福祉課長","answer":"ですので、いろいろお聞きする中で判断していくべきものだと考えています。","voiceIndex":77,"id":"exchange-035"},{"speaker":"山元委員","kind":"質問・要望","question":"すみません、大きな間違いをしていましたが、昨年の８月からスタートしているということで、今までの実績といいますか、実際にどういうことがあるのか教えていただきたいと思います。","respondent":"志村生活福祉課長","answer":"主なるものは、先ほど申し上げたとおり、生活のサポート事業といいますか、立て直しに当たって、いろいろ正規雇用に向けての取り組み、この辺のことで、具体的な内容は、個々千差万別です。","voiceIndex":79,"id":"exchange-036"},{"speaker":"山元委員","kind":"質問","question":"貸付事業ということなので、やっぱり返済はしなければいけないんですよね、いかがでしょうか。","respondent":"志村生活福祉課長","answer":"この学校のトレーニングが、実は６カ月かかります。","voiceIndex":81,"id":"exchange-037"},{"speaker":"山元委員","kind":"質問","question":"すみません、しつこくて申しわけないんですが、返済するその期間といいますか、年数はあるんでしょうか。それとも、いつでもいいということなんでしょうか。","respondent":"志村生活福祉課長","answer":"額にもよりますけれども、一応１０年が基本です。ですから、その利率につきましては、直近の利率を算定してと聞いております。","voiceIndex":83,"id":"exchange-038"},{"speaker":"渡部委員","kind":"質問","question":"歳入の１２６ページ寄附金の部分で、指定寄附金の充当事業、しながわお休み石設置事業というところと、１３６ページの広告料収入について、２点お伺いしていきます。今後、これをどのように進めていくのか。たしか寄附は一口５万円だったかと思うんですが、１基設置するためにかかるコストはどのぐらいなのか、まず、先にお休み石のところから伺っていきます。","respondent":"永尾高齢事業課長","answer":"しながわお休み石ですが、開始が平成８年４月です。現在は、２３２基設置しております。設置の場合のコストですけれども、設置する場所によっても工事費等が違いますけれども、お休み石自体の金額というのは約３０万円程度かかっております。","voiceIndex":87,"id":"exchange-039"},{"speaker":"渡部委員","kind":"質問・要望","question":"次ですが、先ほど、ほかの委員からもありましたが、広告料収入で伺いたいのが、今回、予算１,０００万円ある中で、広報「しながわ」等とありますが、実際にどの媒体が幾らということが、どういう媒体で広告を募っているのか、わかればいろいろ教えていただきたい。ほかにいわゆる広告収入という部分で、何か、今後考えていくのかがあれば、方向性を踏まえて教えてください。","respondent":"中川原広報広聴課長、日下部企画財政課長","answer":"ホームページにつきましては、この間、リニューアルを終えまして、制限なしで受け付けていまして、現在は、１バナー広告２万円のところ、毎月４０社お申込いただいているところで、先ほど申しましたように。品川区におきましても、例えば水族館とか、きゅりあんとか、いろいろ候補になるところがありますので、検討した経緯はあるんですが、なかなかそれが思うような形では進んでいないという現状です。","voiceIndex":89,"id":"exchange-040"},{"speaker":"渡部委員","kind":"質問","question":"検討したということで、確かに水族館ですとか、きゅりあんとか、先ほどほかの委員からもありましたが、大崎駅界隈の開発ですとか、人が集まるところ、目に触れるところ、公共サービスを邪魔しない程度で何かまたそういう活用があるのであれば、今後ぜひ、こういう時代ですから、ネーミングライツ等を新たな財源確保という観点から検討していただければと思いますが、いかがでしょうか。","respondent":"日下部企画財政課長","answer":"ネーミングライツ、区の独自財源の確保といった点では非常に重要な課題だと、我々も思っていますし、そういった意味では、今後ともその辺の可能性については、できる限り追求をしてまいりたいと考えております。","voiceIndex":92,"id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問","question":"私からは、６ページの特別区財政調整交付金と、８８ページからの国庫支出金、１０６ページからの都支出金の中で、公立、私立保育園の経費について、お伺いいたします。この中に入っているものは何なのかということ。それから、私立保育園の経費のところ、開設負担金というのが、国庫支出金と都支出金の中にあったんですが、この辺に一体どういう中味が含まれているのか、おおもとのところを教えてください。","respondent":"日下部企画財政課長","answer":"財政調整交付金の関係ですけれども、保育園に係わる経費、運営費、人件費も含めて、これが算定対象として中に算定をされているというものです。","voiceIndex":96,"id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問","question":"国庫支出金と都支出金の中にも、私立保育園の部分があったんですが、この部分に算定されるのは一体どういう中味なのか、教えてください。","respondent":"小林保育課長","answer":"お手元の説明書の８９ページの国庫支出金のところに児童保育費というところがあります、これが一番大きい私立保育園に対する経費かと思います。","voiceIndex":98,"id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"平成２０年度４月１日現在で、公立保育園が４０園あるわけですが、在園児数が３,６４６人となっていますが、ここの職員のところで財政調整交付金基準の職員数と、実人員のところを教えていただきたいと思います。総数で、できましたら、職種別のところで、わかったらその部分も教えてください。","respondent":"榎本人事課長","answer":"保育園の財政調整交付金算定人員なんですけれども、平成２０年４月１日で算定した形で、保育園につきましては７７８名で、職員数は６７１名というものです。","voiceIndex":100,"id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問","question":"職種別がわかるかどうか、再度、お伺いをしたいのと、保育園の場合、モデル園というか、基準の保育園、例えば１００名で、０歳をやっているとか、基準の保育園のところの職員の配置の基準がありましたら、そこも総数と、職種別にわかったら、その辺も教えてください。","respondent":"榎本人事課長","answer":"今の財政調整交付金算定人員７７８名の職種別の部分は入っておりません。総数で財政調整交付金としてカウントしているというものです。","voiceIndex":102,"id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問","question":"財調のモデル園の職員の総数と、職種別にわかったらということを２点目にお伺いしました。","respondent":"日下部企画財政課長","answer":"標準算定というふうに申しておりますけれども、そこにおける人員の配置の一つの事例といいますか、考え方といたしましては、１園、児童１００人入所という前提でありますけれども、保育士１５名、調理２名、用務１名という形で算定の一つの基準が出ているというものです。","voiceIndex":104,"id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"職種別のところで、看護師とか、調理員とか、保育士１５名は施設長が含まれているのかどうか。財調の基準という考え方は、都基準と一致するのか、しないのかというところと、品川区の基準があるんだったら、その辺の違いを教えてください。","respondent":"小林保育課長","answer":"今、ご説明させていただきました参考としての配置例に対して、旧都基準との相違は、ですけれども、おおむね同じような考え方で標準算定されているものと思われます。旧都基準というものが、現在、既に存在していない関係上、定かに照合することはできません。","voiceIndex":106,"id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問","question":"財政の基準がおおむね旧都基準と同じということなんですけれども、先日、東京都に行って聞いてきましたところ、都の財調の部分において、今までどおり事業をしている者に対しては、そのままお金が行っているという話だったんです。そういったところにおいては、看護師とか、栄養士の部分は入るんではないかなと思うんですが、いかがでしょうか。","respondent":"小林保育課長","answer":"それは品川区の行政判断による態勢のとり方ですから、それをもって調理員がいないのが、人数が少ないのはおかしいという議論にはならない。区としての判断の結果と考えています。","voiceIndex":108,"id":"exchange-048"},{"speaker":"飯沼委員","kind":"意見","question":"この６年間の保育園の児童数なんですけれども、保育課の資料だと、平成１４年から２０年までの間に、定数増で２８７人増えています。それから、弾力化で１６１名増えているんですね。そして、子どもが４４８人増えています。職員を増やさずに、こういった配置でしているというあたり、どう考えていらっしゃるのか、ここがきっと品川区の工夫とおっしゃるんだと思うんですが、ここの考え方を聞かせてください。","respondent":"小林保育課長","answer":"現在、直近で、４月１日の想定しております定数は５９１名、前回、ご答弁申し上げたよりも若干増えてありますが、それは定数の増、あるいは新規の需用に対応した増です。私ども保育課、決して必要な人数をけちっているつもりはございません。","voiceIndex":110,"id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問・要望","question":"４４８名増えている中で、都の基準より１０７名少ない。平成１４年から２０年にかけて、プラス１１名なんですね。ちょっとお伺いしたいと思いますけれども、この間、時間がなくて非正規のところが伺えなかったんですけれども、正規職員が大変減らされていて、一方、非正規職員が増えている。こういった保育の質、私は、この職員の問題で明らかに低下をしていると思うんですけれども、いかがでしょうか。","respondent":"小林保育課長","answer":"保育士は、仮に必要なときにみずからの専門性において、職員間の連携を密にして対応していく、そういった気持ち、意欲を持って対応しているところでございまして、決して保育士に技術がないので、子どもに十分対応できていないというふうには、保育課長として考えておりません。","voiceIndex":112,"id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問・要望","question":"非常勤職員を、正規職員換算すると１５０人分だと。前に、７時間だった方が３時間に削られてしまったんですよね。最後なんですけれども、私立保育園の運営費助成の見直し案が出ているんですけれども、都基準をきっちり守ってほしいなと思うところでは、ぜひ保育水準を守っていただきたい。それから、十分な話し合いをお願いしたいという声も届いていますので、この点、お答えください。","respondent":"小林保育課長","answer":"私立保育園は、区立保育園と同様に認可保育園として、この間、品川区の子どもを育ててきていただいております。その状況に応じて、しかしながら時代の背景をしっかりととらえた上で、将来を見据えたご協議、ご相談を、今後も続けてまいりたいと思います。","voiceIndex":114,"id":"exchange-051"},{"speaker":"渡辺委員","kind":"質問","question":"私は、１１１ページの児童センター運営費、１２１ページ、オリンピックムーブメント事業、１３９ページ、里山再生活動参加費（早川町）のことを伺いたいと思います。当然ながら、児童福祉法による児童福祉施設である児童センターという位置づけが基本だと思うんですが、おおまかで構わないんですが、児童センター事業の品川区の独自な部分、そして国と都の財源の割合を、最初に伺いたいと思います。","respondent":"諸岡児童課長","answer":"基本的な事業といたしましては、０歳から１８歳まで、年代を通した健全育成ということで、乳幼児、それから小学生、中高生に至るまでの全面的な事業が展開されております。","voiceIndex":117,"id":"exchange-052"},{"speaker":"渡辺委員","kind":"質問","question":"あわせて伺います。先ほど伺った財源のほうの割合ということを簡単にお答えいただければと思います。あわせて、人員構成、スタッフの話ということで、まず各拠点である児童センターごとに、館長をはじめとした区の職員がいらっしゃる。それから、委託先等のこれまでの経緯だとか、変更がある、そして経緯と影響等を伺えればと思います。","respondent":"諸岡児童課長","answer":"小規模施設におきましては、キッズ館事業ということで、一部委託した児童センターもあります。この委託館につきましては、事業者につきましては、事業者の都合と、また契約の変更等に応じて、年度によって事業者の変更が生じております。","voiceIndex":119,"id":"exchange-053"},{"speaker":"渡辺委員","kind":"質問","question":"今、少数館を中心に委託先の変更の経緯、いろいろな変更点があるかと思いますが、その辺のところを、ちょっと詳しく伺えればと思います。こういった委託先の変更が生じる場合、決定する経緯とか、決め方、あるいは、今現在で把握されている影響点等ありましたら、お願いします。","respondent":"諸岡児童課長","answer":"委託先の変更につきましては、事業者のほうから、事業縮小に伴っておろさせてほしいような申し出がある場合もあります。基本的にはこちらのほうで受託要件、仕様書を定めまして、職員についての資格と要件等を定めまして、入札により業者を選定しております。","voiceIndex":121,"id":"exchange-054"},{"speaker":"渡辺委員","kind":"質問・要望","question":"改めて伺いたいと思います。児童センターという中で、遊びに来る、あるいはいろいろな形で来る子どもを中心とした視点で、ちょっと再確認なんですが、ここで言う子どもというのを、まず小中学生に絞って考えますと、よく道で「どこへ行くの」と聞いたときに、「児童センター」と。帰り道でも、やっぱり児童センターということは、よくやりとりであります。","respondent":"諸岡児童課長","answer":"特に乳幼児親子のお母さん方の育児不安に伴う相談事業でありますとか、中高生のバンド、ミュージカルでありますとか、あるいは、創作活動等の活発な活動が展開されておりまして、その辺が品川区としてもその辺が大きな特徴であると考えています。","voiceIndex":123,"id":"exchange-055"},{"speaker":"渡辺委員","kind":"質問・要望","question":"今、ご答弁がありましたように、幅広い世代の方が。そういう中で、段階的にさらに今後を考えたときに、利用者の声も踏まえた中で、児童センターという名称も含めたイメージ、今後、どのように展開されていくのか、１点伺いたい。その辺の把握と、今後の対応の２点、伺いたい。それと児童センターという拠点の今後の全体の、長期的な考え方を伺えればと思います。","respondent":"諸岡児童課長","answer":"児童福祉法の改正が平成２１年４月に予定されておりますけれども、特にその中でも、乳幼児への対応、育児不安、それから核家族化に伴う育児の孤立化に伴う対応も、児童センターで極力図っていくようなこと。","voiceIndex":125,"id":"exchange-056"},{"speaker":"渡辺委員","kind":"提案","question":"最後に、児童センターに対しまして、要望、提案をさせていただきたいと思います。大人が２００円、子どもが１００円。考え方としたら、市の独自財源によって文化施設という位置づけで、平成１３年に進められたという経緯を伺ったのも、ちょっと魅力的だったので、こういった意味で、児童センターの総合的な拠点へ、品川区では現在、どのような考えをお持ちか伺えればと思います。","respondent":"諸岡児童課長","answer":"児童センターの衛生面の話ですが、確かに、一時、老朽化して、見た目がきれいとは思えない部分もございました。しかし、この３年間、耐震改修工事に合わせまして、できる限り児童センターをきれいにしていこうと、児童センターの美化作戦ということで、３年間努めてまいりました。","voiceIndex":127,"id":"exchange-057"},{"speaker":"渡辺委員","kind":"質問","question":"１２１ページでオリンピックムーブメント事業について、伺いたいと思います。１０月に開催箇所選定に向けて、東京都も相当、力を入れる年度になるかと思いますが、概要を伺えればと思います。品川区におけるオリンピックムーブメントについての概要を、お願いします。","respondent":"久保田行財政改革担当課長","answer":"内容につきましては、できるだけ多くの子どもたちや地域の方にトップアスリートの高度な技術に触れていただきたい、また、スポーツの振興という意味も込めまして、アスリートドームスポーツというようなスポーツ学校の文化フェスティバルみたいなものを予定しています。","voiceIndex":129,"id":"exchange-058"},{"speaker":"渡辺委員","kind":"質問・要望","question":"立地で言うとやっぱり羽田や品川駅等のターミナルがある、そういったメリットも考えますと、あるいはよく言う、ふだんの地域スポーツへの波及効果、この辺から、オリンピックムーブメント、品川区として、１０月のぎりぎりまでこだわりを持って取り組んでいただきたいという要望とあわせて、ご見解を伺いたいと思います。","respondent":"久保田行財政改革担当課長","answer":"オリンピックムーブメント事業につきましては、東京都からの受託事業ということですので、単発でやらざるを得ないというところがあるんですけれども、地域スポーツの振興といった面では、こういうトップアスリートに触れる機会というのは貴重な機会ですので、トップアスリートは。","voiceIndex":131,"id":"exchange-059"},{"speaker":"武内委員","kind":"質問","question":"私は、４点お伺いします。８６ページの長期優良住宅建築等計画認定申請手数料、それから、１０８ページの私立幼稚園等園児保護者補助金、１１４ページの医療保健政策包括補助金、１２０ページの生活安定応援事業委託金を、お伺いしたいと思います。それから、医療保健政策包括補助金については、ここに感染症対策費ほか２事業とありますが、この２事業について、お伺いします。","respondent":"片田建築課長、小林保育課長、山岡健康課長、志村生活福祉課長","answer":"公布されてから６カ月以内の施行ということで、６月４日の予定で考えられているところです。これが議決されましたときには、特定財源の通知がありますので、その段階で、品川区におきましても、来年度以降、その助成内容について。ここに記載されています感染症対策費ほか２事業ですが、一つが飼い主のいない猫対策事業です。もう一つが、予防接種支援事業です。そんなこともありまして、ホームページに主なるものを載せているものですので、今後、いろいろご相談をいただく中で。","voiceIndex":134,"id":"exchange-060"},{"speaker":"武内委員","kind":"質問・要望","question":"品川区ですべて委託されているので、六つ、七つある事業全部受けてやっているのかどうか、もう１回、確認をしたいと思います。それから、最初の長期優良住宅につきましては、わかりました。そうしますと、今回、新聞等でも、大分取り上げられましたけれども、２３区で初めてＨｉｂワクチンということでやりますけれども、これについて、この補助金が使えるのかどうか、確認をさせていただきたいと思います。","respondent":"志村生活福祉課長、片田建築課長、山岡健康課長","answer":"この役割分担ですけれども、私どもは、先ほど申し上げたように、相談の窓口です。この事業そのものの実施主体は東京都が一手に行っているものです。職員の対応の状況のお話がございました。先ほどのお尋ねのＨｉｂワクチンについてですが、これはまだはっきりしておりませんので、断定的にお答えするわけにはいきませんけれども。","voiceIndex":139,"id":"exchange-061"},{"speaker":"武内委員","kind":"質問・要望","question":"生活安定応援事業については、できればホームページに詳しく載せてあげてもらいたいんです。これは要望します。それから、Ｈｉｂワクチンにつきましては、待つのではなくて、せっかくこういうおたふく、水疱瘡ということで、品川区はやっているわけですから、積極的に東京都から予算を取るような形でやってもらいたい、これはぜひ要望します。","respondent":"片田建築課長、山岡健康課長","answer":"特に別途の長期優良住宅の認定基準については、まだ国土交通省のほうで基準を公にしてはございませんけれども、幾つかの審査項目の中で劣化対策、あるいは耐震性とか、可変性、バリアフリー性とか。Ｈｉｂワクチンの供給量についてですが、メーカー側とも情報交換をしながら、一定の供給量を確保できるように努力してまいりたいと考えております。よろしくお願いします。","voiceIndex":143,"id":"exchange-062"},{"speaker":"川西委員","kind":"質問・要望","question":"使用料でもう一つお伺いしたいんですが、シルバーセンターの使用料、地域のシルバーセンターによって、大幅に１桁から３桁まで使用回数が違っております。これは、地域事情とか、使い勝手がいい、悪いとかいろいろあるかと思いますが、その辺についてお伺いいたします。","respondent":"堀越生涯学習課長、永尾高齢事業課長","answer":"それからもう１点、今後のグラウンドの整備の件ですが、区内の大規模な土地を確保という課題がありますが、平成２１年度計画をしております荏原平塚中学校の跡地のグラウンドの計画ですとか、そのような限られた資源を有効に活用して。南品川、旗の台シルバーセンターにつきましては、平成２１年度は工事に入る関係で、その分も配慮して積算しています。","voiceIndex":147,"id":"exchange-063"},{"speaker":"川西委員","kind":"質問・要望","question":"そうしますと、今後、公園等のスポーツ施設で、平塚はわかりましたが、それ以外に、区としてどういうスポーツ施設を拡充、整備していきたいか。来年すぐのことではないんですけれども、それを伺ったわけなので、展望をお知らせいただきたい。シルバーセンターで伺ったのは、地域によって、１桁から３桁まで使用回数がこんなに違うのは、どういう事情によるものか伺いたい。","respondent":"堀越生涯学習課長、永尾高齢事業課長","answer":"ソフトの面でも、何とかより有効に使っていただけるような仕組みを考えていきたいと考えているところです。シルバーセンターにつきましては、例えば平塚橋などについては、複合の施設があるので、そちらのほうに流れたりというような関係で、近隣に集会所等があると、そちらに流れる傾向があると考えています。","voiceIndex":150,"id":"exchange-064"},{"speaker":"川西委員","kind":"質問・要望","question":"シルバーセンターは、なぜこんなに地域によって使用回数にばらつきがあるのか。シルバーセンターは、やっぱり施設の有効活用ということで、もっと利用してもらいたいという気持ちがあるから伺っております。以前、副区長に、城南中学校の隣地は、所有している民間会社が譲ってくれたら、少年野球場にしたいと思っているという話を伺ったんですけれども、これはどうなったんでしょうか。","respondent":"永尾高齢事業課長、濱野区長","answer":"シルバーセンターの件ですが、まず、部屋の数等も、各シルバーセンターによってばらつきがあるのと、それから最近の傾向ですけれども、使用料免除の方が増えているという傾向にありまして、こちらの予算書のほうに載っているのは。もし、そこに広大な敷地を購入するのだとすれば、区内で非常に需用の高い運動の施設として使わせてほしいという声が、ほかの地域から起きますね、ということで申し上げたものです。","voiceIndex":153,"id":"exchange-065"},{"speaker":"川西委員","kind":"質問・要望","question":"使用料の３番目ですけれども、自転車の駐輪場の使用料のことです。この現金収入について、どのように会計管理室に入ってくるのか伺います。これは大変結構なことだと思うんですが、そういう点について、区から、シルバー人材センターを使ってほしいということを依頼されているのかどうかということを、伺います。それから、最後に使用料の件、もう一つ伺いますが、区民住宅の使用料についてです。","respondent":"諸石交通安全担当課長、齋藤住宅課長","answer":"自転車駐車場使用料の関係です。料金につきましては、まずその日にどのぐらいの収入があったか、翌日に区のほうに報告が上がってまいります。これは一番いい数字です。強制退去をした件数ですが、昨年度は１件。自主的に退去された方が３件ほどいらっしゃいます。次に、あいてからリフォームをする期間は大体２カ月、３カ月ぐらいかかっております。","voiceIndex":156,"id":"exchange-066"},{"speaker":"川西委員","kind":"質問・要望","question":"区民住宅は、よくわかりました。行政というのは、何でそんなに違いがあるのか、住宅課長が把握していらしたら教えていただきたい。半年も、１年もあいているんです。私は、２月の末に町会の総会がありまして、南品川四丁目というところにもあるんですが、４３m2なんですが、これでどうしてこんなにあいているんでしょうと、自治会長がおっしゃるんです。その辺、一言、二言で結構ですから。","respondent":"齋藤住宅課長","answer":"東京都のほうは、あいているわけではないんだと、計画的にあかしているんだというような言い方をしておりまして、募集期間に合わせてあかしているんだという言い方をしておりますので、なかなか難しゅうあります。","voiceIndex":159,"id":"exchange-067"},{"speaker":"川西委員","kind":"質問・要望","question":"この件については、まだ意見もありますが、次に移ります。７９ページです、公共溝渠のことですが、補正予算では、財産売払収入ということで入っておりましたが、当初予算になりますと、科目存置の１,０００円。これはどういう故なのか。やる気があるのか、ないのかということをお答えいただきたいと思います。","respondent":"阿部経理課長","answer":"科目存置ですけれども、この売払の希望の方はいらっしゃいますけれども、決定までにかなり時間がかかるということと、今現在、平成２１年度について、売り払うと確定しているものは、まだ１件もございませんので、今回は、科目存置という形になっております。","voiceIndex":161,"id":"exchange-068"},{"speaker":"川西委員","kind":"質問・要望","question":"まちづくりの点から、できるだけ解決できるものはしていただきたいというのが要望です。それから最後に、１４２ページの城南小学校の用地買収の経緯と、今後の使用目途についてお答えください。","respondent":"田村庶務課長","answer":"それと合わせて購入しようです。将来展望は、昭和３０年前半でございましたので、将来的に建替え等があったときに、今、接道部分が少ないので建替えできないということなので、それも見込んで、購入したものです。","voiceIndex":163,"id":"exchange-069"},{"speaker":"藤原委員","kind":"質問","question":"１１４ページ、広域観光まちづくり支援事業補助金、１２０ページ、オリンピックムーブメント委託金、それから、統合型地域スポーツクラブ設置委託金について、お伺いします。オリンピックムーブメント事業から伺いますが、この事業の目的は、２０１６年に東京にオリンピックを誘致するということのためにあるんでしょうか。それから、統合型地域スポーツクラブに関しては、この事業の内容を教えてください。","respondent":"久保田行財政改革担当課長、堀越生涯学習課長、金子産業振興課長","answer":"品川区につきましては、当然、オリンピックの招致といった部分では、そういう考えはあるんですけれども、オリンピックの招致に加えまして。いろいろな内容の検討ですとか、スポーツクラブに対しての普及啓発を図るイベントですとか、そのようなことを主な内容としているものです。平成２１年度の主な内容としましては、品川区側の分ですけれども、歩行者用観光案内の標識の設置であるとか、あるいは、観光マップの作成。","voiceIndex":166,"id":"exchange-070"},{"speaker":"藤原委員","kind":"質問","question":"オリンピックですが、もし２０１６年にきたら、２兆６,０００億円の経済効果もあるということで、私は、すごく期待をしております。でも、今、行財政改革担当課長の答弁を伺って、地域のスポーツ振興等の目的もあるんだということで、だから、どんなことをしてでもオリンピックに来てほしいという気持ちが全然、お役人にもないなと、すごく感じておりました。","respondent":"堀越生涯学習課長、金子産業振興課長","answer":"今、いろいろな地域スポーツの推進事業ということで、スポーツ教室等も開催していただいております。これをさらに拡充をさせていきたいと考えているのが、地域スポーツクラブの設立の目的です。今回、広域観光まちづくり支援事業を、私どもに話がありましたのは、やはり東京都としても、観光について非常に力を入れているということと、羽田空港の国際化をにらんで、大田区、品川区のあたりの地域。","voiceIndex":170,"id":"exchange-071"},{"speaker":"藤原委員","kind":"質問・要望","question":"スポーツクラブと広域の観光については、自分でもずっと追っていきたいと思っていますので、よろしくお願いします。それから、オリンピックは、自分で一方的にお話ししてしまいましたけれども、担当課長は、多分、そうではないんだというお気持ちもあると思うので、時間がありますので、熱い思いといいますか、反論があるなら、ぜひちゃんと言っていただきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"それに、やはり地域に一番身近な基礎自治体といたしましては、オリンピック招致といった部分も当然ですけれども、地域スポーツの振興といった面で非常に効果があるというところもありますので、私どもは、東京都のオリンピックムーブメントに協力をしていきたいと考えています。","voiceIndex":173,"id":"exchange-072"},{"speaker":"山内委員","kind":"質問・要望","question":"私からは、１１４ページの都補助金、土木費補助金、１１６ページになりますけれども、４節住宅・建築物耐震化補助金について、お尋ねをします。考え方をお尋ねさせていただきたいんですが、住宅・建築物耐震化支援事業、そして耐震シェルター等設置助成とありますけれども、この二つの考え方を伺いたいんです。","respondent":"片田建築課長","answer":"シェルターについては、あくまでも高齢者、あるいは低所得の方を対象に、本来の建替え、あるいは改修ができるまでの、ある意味ではつなぎといいましょうか、そういう中での位置づけで、すぐに工事はできませんという方を対象に考えていきたいと考えております。","voiceIndex":176,"id":"exchange-073"},{"speaker":"山内委員","kind":"質問","question":"今、つなぎでシェルターをと、建築課長から答弁いただきましたけれども、つなぎでシェルターを設置するんだったら、普通はそこで耐震化を考えると思うんです。そのつなぎという意味はどういうことなんでしょうか。","respondent":"片田建築課長","answer":"今回のシェルターにつきましては、居ながら、できるだけ１部屋を補強する、あるいは、さらに願わくばそれを強化するということも可能ですけれども、やはり短い期間で簡単にできないかと。特に高齢者、あるいは低所得の方は、建替えとか、改修というのはなかなか難しい。","voiceIndex":178,"id":"exchange-074"},{"speaker":"山内委員","kind":"質問","question":"最終的には、耐震化というものを目指しているわけですよね。ではそれは結局、今住んでいらっしゃる方にとって、いわゆる二重投資になりかねないのではないかなと思うんですけれども、その辺はどうお考えなんでしょうか。","respondent":"片田建築課長","answer":"特に診断についても、１カ月からその程度の期間はどうしてもかかってしまいます。特にシェルターについては、診断とか、そういうことを求めるものではございません。基本的には、昭和５６年以前の建物、それを対象にしていきたいと考えているところです。","voiceIndex":180,"id":"exchange-075"},{"speaker":"山内委員","kind":"質問","question":"そうした場合に、あくまでも耐震化に向けたことが目的の一環ということで考えるならば、やはり今後も、耐震化に向けたお声がけというか、シェルターを設置された方に対しての働きかけというものもしていかなければいけないと、まちづくり事業部の中では考えていらっしゃるということで、いいんですかね。","respondent":"片田建築課長","answer":"そういう意味では、木造住宅の寿命が意外に短いんです。そういう中で、やはり本来の建替えの中で耐震化率を上げるのが基本と考えていますので、その間にシェルターのメニューもありますよということで、引き続き、耐震化に向けた働きかけをしていきたいと考えております。","voiceIndex":182,"id":"exchange-076"},{"speaker":"山内委員","kind":"質問","question":"わかりました。木造住宅の耐震診断をするときに、やっぱり行政のほうから補助が、たしか６万円でしたか、出ますよね。そういった場合はその助成金を併用というか、診断をする際の助成、それからシェルターを設置するときの助成は併用して使える制度と考えていいんでしょうか。","respondent":"片田建築課長","answer":"助成金との併用のご質問ですけれども、基本的には、シェルターの場合は、診断をしなくても、６５歳以上、高齢者、あるいは２００万円以下の低所得の方であれば、３０万円を限度として支援しましょうと。この場合は、診断までを要件としてはございません。","voiceIndex":184,"id":"exchange-077"},{"speaker":"井上委員","kind":"提案","question":"私からは、歳入で、７２ページ民生使用料、シルバーセンター使用料、補助金のほうで１１２ページの都補助金、やさしいまちづくり計画推進費、９４ページの国庫補助金の衛生費補助金、在宅難病患者訪問介護員派遣費、それから、歳出で議会費について、伺います。最初に議会費です。実施に向けて質問をいたします。１点。最後に実施設計、契約、工事着工のスケジュールを伺います。","respondent":"桑村区議会事務局長","answer":"そういう意味では、夏の期間になるか、それとも冬の期間になるか、どちらかしかやりようがございませんので、今、おっしゃったように、一定の設計の部分で時間がかかると考えておりますので、年末年始の期間を踏まえた実施の時期になろうかと考えているものです。","voiceIndex":187,"id":"exchange-078"},{"speaker":"井上委員","kind":"質問・要望","question":"そこは広く市民が利用する場所であるということを、まず押さえるべきだと思います。議員の席と傍聴席の工事ということではなく、傍聴席の一連の工事ですので、将来的に、そういう時代がきてつくるということになって、コストの面や税金のむだ使いということにならないように、前向きに検討をしていただきたい、区の適切な判断を求めておきたいと思います。２点目です。相談の結果をお知らせください。","respondent":"伊勢総務課長","answer":"その後、傍聴人に資料云々ということがありますけれども、基本的にはまずは、議会の内部で十分にご議論いただきたいと思います。それで結論が出た中で、また我々とどういう形がいいのかということをご相談させていただきたいと思います。","voiceIndex":189,"id":"exchange-079"},{"speaker":"井上委員","kind":"提案","question":"ということは、以前と変わりない状況だと、判断いたしました。次は、シルバーセンターの使用料について伺います。これも、今、品川区の中では、利用する施設がないという声も聞くんですけれども、一方で使われていない施設もたくさんあるのではないかということで、２００５年の予算特別委員会で生活ネットワークは、シルバーセンターの目的外使用をもっと ＰＲしてはどうかという提案をいたしました。","respondent":"永尾高齢事業課長","answer":"地域の方からのお問い合わせの際には、こちらのほうでも、シルバーセンターのご利用をＰＲなどするような対応をとっているところです。","voiceIndex":191,"id":"exchange-080"},{"speaker":"井上委員","kind":"提案","question":"ですから、そこの部分を、目的外使用は、対象者が６０歳以上ではないということをきちんと明記をしてほしいということ。ですから、まだまだ改善をされる余地がたくさんあるかと思います。次に、やさしいまちづくりですけれども、やさしいまちづくり推進の費用のところで、主に駅舎のエレベーターの補助なのかなと思いますけれども、ほかに充当している事業があれば、お伺いします。","respondent":"冨岡高齢福祉課長","answer":"都の補助金のやさしいまちづくりの計画推進費ですが、委員、ご指摘のように、この部分につきましては、平成２１年度予定をしております青物横丁のエレベーター設置の補助金、２基分です。","voiceIndex":193,"id":"exchange-081"},{"speaker":"井上委員","kind":"質問","question":"ここの部分では、それだけということなので、ちょっと款が別になってしまうので、また社会福祉協議会への点字誘導ブロックの敷設などが、こういったやさしいまちづくり計画推進のところで、利用ができないのかなと思ったんですが、そういったところは、これは使えないんでしょうか。","respondent":"冨岡高齢福祉課長","answer":"社会福祉協議会では、その経費については計上しておりません。その意味では、実施できないです。","voiceIndex":195,"id":"exchange-082"},{"speaker":"井上委員","kind":"質問・要望","question":"これは、款別のほうでまた質問をさせていただきたいと思います。次は、国庫補助のほうの在宅難病患者訪問介護員派遣について、お伺いいたします。これについて、昨年度も、決算特別委員会のところで触れさせていただいたんですが、この補助金に対する利用想定人数というのは何人と計画をされているのかということ。それから、この方たちが訪問介護を受ける仕組みがどのようになっているのか、教えてください。","respondent":"高橋障害者福祉課長","answer":"この在宅難病患者訪問介護員制度ですが、東京都の難治性疾患の克服事業の中の１２３項目、または慢性関節リューマチの方で、なおかつ介護保険、身体障害者福祉法の施策の対象にならない方が対象です。したがいまして、私どもで予定しているのは、２人が対象の予定です。","voiceIndex":197,"id":"exchange-083"},{"speaker":"井上委員","kind":"質問","question":"そうしたときに、そのコーディネートがうまくいっていなくて、苦情をどこに言ったらいいのか、区に言うのか、その施設に言うのかということも不明ということで、その場合に、まずは本人が保健所に申請をするということで、保健所と障害者福祉課の連携というか、そこら辺が、利用する方がはっきりとわからないということもあると思うんですが、そういった連携の状況がどのようになっているんでしょうか。","respondent":"高橋障害者福祉課長","answer":"その辺につきましては、保健師の状況の把握の中で、サービスの提供が具体的な形になっていくかと思います。","voiceIndex":199,"id":"exchange-084"},{"speaker":"井上委員","kind":"質問","question":"そうしますと、派遣事業者は、どういった方になるんでしょうか。ご自分がつらいときに派遣していただけるのか、それが多分家事援助になるんじゃないかなと思うんですけれども、その辺のルールというのはあるんでしょうか。","respondent":"高橋障害者福祉課長","answer":"医療の部分につきましては、担当の保健師に、その辺のところについては、どうしたらいいのかということでご相談をしていく中で、サービスの提供が具体的な内容になってくるかと思います。","voiceIndex":201,"id":"exchange-085"},{"speaker":"井上委員","kind":"確認","question":"利用されるこういった方たちは、保健師が窓口になると考えてよろしいんでしょうか。そこのところだけ確認をさせてください。","respondent":"高橋障害者福祉課長","answer":"難病ですので、基本的には、保健所、保健センターの保健師のほうにご相談し、具体的な内容を、サービスの提供等も含めまして、継続的な相談になるかと思います。","voiceIndex":203,"id":"exchange-086"},{"speaker":"若林委員","kind":"質問・要望","question":"広域観光まちづくりのほうでは、先ほどお話が出ましたので、昨年の夏でしょうか、お話のあった羽田空港跡地について、大田区、品川区とともに国と都の４者で、羽田空港移転問題協議会がつくられて、これから進んでいくという。ここら辺についても、支援事業が、お金がついてくるんでしょうか、含まれてくるのか、そこら辺を教えていただきたいと思います。","respondent":"志村生活福祉課長","answer":"私どもで生活相談等を実施していますけれども、平成２０年７月から、相談件数等が増えてまいりました。","voiceIndex":206,"id":"exchange-087"},{"speaker":"若林委員","kind":"質問・要望","question":"わかりました。そこで、これまで、国の事業としての自立支援事業も含めまして、区としても、さまざま独自に工夫されたところがあると思いますけれども、そこら辺の概要と、またどういうふうに自立支援に向けた成果といいますか、そこら辺の様子を、エピソードなんかも含めてお聞かせいただきたいと思います。","respondent":"志村生活福祉課長","answer":"ケースワーカーと、こうした就労支援員が共同して取り組んでまいりますので、この辺の進行管理につきましても、毎四半期ごとにチェックを入れて、的確に、早くこうした方々が就労に基づいて自立ができるようにというような取り組みを続けているところです。","voiceIndex":211,"id":"exchange-088"},{"speaker":"若林委員","kind":"質問","question":"わかりました。もう１点、他の所管との連携という意味では、先ほどからお話が出ています生活安定応援事業、相談者の方に対してですけれども、生活安定応援事業でありますとか、または、生活相談でありますとか、または、民間の方との連携も、これからあるのかどうかということを、一つお聞きしたいと思います。","respondent":"志村生活福祉課長","answer":"ですので、この辺につきましても、引き続きいろいろな角度から模索しながらやっていきたいと考えているところです。","voiceIndex":213,"id":"exchange-089"},{"speaker":"若林委員","kind":"意見","question":"相談に来られた方等に、先ほどお話の出た、生活安定応援事業等の窓口がどこにあるのかわからないんですが、同じ生活福祉課長の答弁だったので、こちらに、生活保護の相談に来たんだけれども、そこには至らなかった。でも生活応援としてご案内をしていく、そういう自分の部署内でのつなぎとか、また他の所管との連携を、もう一つお聞かせください。それから、民間についても、お聞かせ願います。","respondent":"志村生活福祉課長","answer":"ですので、この辺につきましては、同じフロアで、同じセクションで机を並べてということにしています。この辺につきましても、連携をとりながら、社会福祉協議会も含めてですけれども、民間との連携も不可欠だと考えています。","voiceIndex":215,"id":"exchange-090"},{"speaker":"高橋委員","kind":"質問","question":"５１ページの特別区民税、１２８ページの減債基金繰入金、それから、１４２ページの特別区債、１３７ページ諸収入。数々の方策をとられて、そういった努力をされていると思いますが、そこでお尋ねします。平成２０年度の滞納率というんでしょうか、収納未済額というんでしょうか、どのぐらいの数字になりそうなんでしょうか。そこから見える特徴は、どのようなものでしょうか。","respondent":"武内税務課長","answer":"平成２０年度の見込みですけれども、予算には２０％と出していますけれども、委員言われるとおり、職員は、滞納者に対して一生懸命対応させていただいているということで、３０％程度の徴収率を見込んでおります。","voiceIndex":218,"id":"exchange-091"},{"speaker":"高橋委員","kind":"質問","question":"２００万円以下の層の滞納が増えてきているということですね。今、滞納者の収納率のお話があったんですが、見込みが２０％ということなのですが、徴税努力をかなりされて、ここ数年２４％、２７％、そして平成１９年度は３５％と上がってきているんですが、２０％という見込みよりも、もうちょっと上に目標を上げてもよろしいのではないでしょうか。","respondent":"武内税務課長","answer":"滞納者の交渉というのは非常に難しいところがありまして、担税力という部分で交渉しますので、どうしても結果がこういう数字になったということで、努力目標ということで数字を上げることは簡単なんですけれども、やはり景気の状況と失業率の状況等を考えますと。","voiceIndex":220,"id":"exchange-092"},{"speaker":"高橋委員","kind":"意見","question":"今、担税力というお話でしたが、ところで地方税法の改正があって、区民税と年金を受けている方との年金と区民税との関係が変わるのではないかということなんですが、そのあたりのことをご説明いただけますか。","respondent":"武内税務課長","answer":"年金所得の６５歳以上の方につきまして、従来は納付方法が、普通徴収という形で年４回、６月の時点で納付書をお送りして、個人でお支払いただくような形だったんですけれども、今年の１０月からは、特別徴収の方法で、年金の支給に合わせて、そこから差し引きするということです。","voiceIndex":222,"id":"exchange-093"},{"speaker":"高橋委員","kind":"質問","question":"今、お話があったんですが、制度が変わるということですので、変わる対象になられる区民にはご説明をお願いしたいと思います。平成１９、２０、２１年度、すべてそうなっているんですが、全然使われていない減債基金はどこに行ってしまうのでしょうか。どのような仕組みになっているのか、教えてください。","respondent":"日下部企画財政課長","answer":"例えば学校用地でありますとか、減税補てん債というものがありますので、これについては、財調算定されたものについて、一般財源のほうから、一種の振り替えをしていくという形で対応をしているというものです。","voiceIndex":224,"id":"exchange-094"},{"speaker":"高橋委員","kind":"質問","question":"いろいろな使い道があるというか、こういう言い方をしたらあれかもしれませんが、かなり自由に使える基金ということで、いろいろな歳出の調整をしているという認識ではいけないんでしょうか。","respondent":"日下部企画財政課長","answer":"例えば自治体によっては、あえて減債基金を設けないで、財政調整基金一本で減債にも活用しているという自治体もあります。","voiceIndex":226,"id":"exchange-095"},{"speaker":"高橋委員","kind":"意見","question":"そうなると、この減債基金等を含めた基金なんですが、平成２０年度も１５億円マイナス、今年の積み上げは１億円マイナス、いろいろな事情があると思うんですが、今後、１０年間に基金全般の繰入の状況、今年度は３８億円マイナスですが、積立による残高の見通し、それから、財政見通し、大きな話になってしまいますが、品川区においては、今後の長期基本計画等も含めて。","respondent":"日下部企画財政課長","answer":"ただ、年間３０億円に相当する返済が必要ということで、まだ今後は、もう少ししっかりとした返済についての計画性を持って対応していく必要があるだろうと考えています。","voiceIndex":228,"id":"exchange-096"},{"speaker":"高橋委員","kind":"質問","question":"今、起債のお話が出たんですが、１４２ページの特別区債なんですが、一般財源等が余裕というわけではありませんが、一般財源等があるのに、わざわざ起債をするというのは、７億円なんですが、平成１９、２０年度は０円で、今年度は７億円起債したのは、どのような事情なんでしょうか。","respondent":"日下部企画財政課長","answer":"起債にもよるんですが、実は、こちらの城南小学校の用地の購入につきましては、財調の中で、起債償還分については基本的に全額面倒を見ると、つまり区の持ち出しはございませんので、こういう形で活用を図っていくというものです。","voiceIndex":230,"id":"exchange-097"},{"speaker":"高橋委員","kind":"質問","question":"最後、品川歴史館に行ったときに、領収書をもらったんですが、Ａ４版の半分ぐらいのすごく大きいものだったのですが、それをその大きさでやらなければいけないという、何か条例とか、法律の決まりがあるのでしょうか。","respondent":"堀越生涯学習課長","answer":"領収書なんですが、すみません、ちょっと調べて、後ほどご答弁します。","voiceIndex":232,"id":"exchange-098"},{"speaker":"本多委員","kind":"質問・要望","question":"もう１点の、１２６ページの財産売払収入なんですけれども、先ほども出ておりまして、科目存置で、平成２１年度は、今現在、確定がないということなんですけれども、先日の補正予算でも出ておりまして、おそらく水路などの売払とか、そういういろいろな話をしている中で、年度途中で確定をしていくというようなことだと思うんですけれども、今後の可能性と、そういったこれまでの補正での実態を含めて。","respondent":"堀越生涯学習課長、阿部経理課長","answer":"そういった法の趣旨を受けまして、文化財については、引き続き教育委員会事務局で、その事務を執り行うという形になっているところです。お尋ねの普通財産の件ですけれども、委員ご指摘のとおり、平成２０年度の補正で増額いたしましたものは、旧水路敷き等の売却です。","voiceIndex":235,"id":"exchange-099"},{"speaker":"本多委員","kind":"質問・要望","question":"財産売払のほうなんですけれども、水路を隣地の方対象に売るということなんですけれども、区内でどのぐらいの可能性というか、規模があるのか、もしわかれば教えていただきたい。それから、財産のほうなんですけれども、不動産のほうは１目なんですけれども、２目の物品売払収入のことも、内容について教えていただきたいと思います。","respondent":"堀越生涯学習課長、松代管理工事課長、島袋品川区清掃事務所長","answer":"特に平成２０年度予算と平成２１年度予算というところで、大きく変わったところはございませんが、埋蔵文化財の包蔵地の周辺の開発状況に合わせて。今後は、適正化とあわせまして、この払下げ等々に取り組んでまいりたいと考えているところです。私のほうから、物品売払収入のことですけれども、不用品売払代金としまして。","voiceIndex":238,"id":"exchange-100"},{"speaker":"本多委員","kind":"質問・要望","question":"そういう点から見て、予算の数字から見ると、この事業のあり方があまり変わっていない点がどうなってくるのかなということを教えていただきたい。クレーンの解体工事は、歳出の衛生費で計上していて明確になっているんですけれども、コンテナ処分とか、その辺が売払に入ってこないのか、ちょっと素朴に思ったので、教えてください。","respondent":"堀越生涯学習課長、島袋品川区清掃事務所長","answer":"新たな掘り起こし周知、それから保護をあわせて、総合的にこれからもやっていきたいと考えているところです。残りがあと７９台なんですけれども、今、鉄の市況が大分下がっていますので、多分、来年度売るとしたら、売った代金よりも処分代金のほうが高いはずなので、この歳入に載せなかったです。","voiceIndex":242,"id":"exchange-101"},{"speaker":"阿部委員","kind":"質問","question":"私からは、６４ページの教育費負担金、それから、８２ページの戸籍証明手数料と、犬の登録料について、それから、１３１ページ、資源持ち去り防止過料、それから、１４７ページ、議会費になりますけれども、本会議録・委員会記録作成経費についてお伺いしたいと考えています。犬の登録料は、これを見ると１件３,０００円計算になっていると思うんですけれども、これは鑑札料実費と考えていいんでしょうか。","respondent":"河野指導課長、上川内戸籍住民課長、荒井品川区保健所衛生課長、島袋品川区清掃事務所長、桑村区議会事務局長、伊勢総務課長","answer":"その校舎設備に関する保守・点検費用を、明晴学園と教育委員会使用分で按分し、保守点検費用の５５.０７％を明晴学園。告知をするという事例がまだございませんので、シミュレーションをしたところ、戸籍というのは、家族関係もありますし、除籍。私のほうからは、犬の登録、鑑札の交付の手数料について、お答えいたします。したがって、過料を科していないです。この当初予算の５万円ということですけれども、１件５万円ということで予想をしています。","voiceIndex":249,"id":"exchange-102"},{"speaker":"阿部委員","kind":"質問・要望","question":"もちろん私立学校でもありますし、管轄は都ですから、品川区がやらない理由は十分にあると思うんです。それから、持ち去り防止過料についてなんですけれども、これは今のところ、指導に従っているということで、多分ないだろうけれども、とりあえず予算書に上げるために１件書いたと考えてよろしいでしょうか。当分は、その方向で運用していくのかということを確認させてください。ご答弁をお願いします。","respondent":"市川教育次長、上川内戸籍住民課長、島袋品川区清掃事務所長","answer":"ご案内のとおり、浅間台小学校での教育活動に引き続きまして、旧八潮北小学校で教育活動を展開するに当たりまして、区のほうでは。もともと８士業の方たちというのは、国家試験を受けて高い職業倫理を持っておられると思われる方たちですが、品川区のほうの基本方針の中にも。ただ、他区のように、トラブルになり、悪質な場合には、当然、こちらも過料をかける予定ですけれども、今のところ、本区の場合は。","voiceIndex":256,"id":"exchange-103"},{"speaker":"阿部委員","kind":"質問・要望","question":"明晴学園の件、原則論として非常に理解はできます。原則がそうであることを踏まえた上で、あえて品川区として何かできないかということをお尋ねいたしました。それが、今、具体的に出てこなくても、やはり区の中で問題意識として何かしなければいけないということで、問題意識を持って内部で検討していただきたいと思うんですけれども、その点について、ご答弁を一言お願いします。","respondent":"市川教育次長、上川内戸籍住民課長","answer":"先ほど申し上げました繰り返しになりますけれども、私立の学校の運営については、やはり公と私の区別をつけた上、区としては対応すべきものと考えております。私どもも考えてまいりますが、国のほうとも相談しながら考えていきたいと思っています。","voiceIndex":260,"id":"exchange-104"},{"speaker":"安藤委員","kind":"質問","question":"５０ページの特別区民税について、伺います。ところで、生活保護制度では、憲法２５条に基づいて、国が保証すべき文化的で健康的な最低限度の生活の水準を定めておりまして、６５歳で単身の方だと、生活保護では月額１３万３,２３０円。それから、天引きの対象者数と、うち２００万円以下の人数、うち、先ほど紹介いたしました、生活保護基準１６０万円以下の方は何人おられるでしょうか。","respondent":"武内税務課長","answer":"ご夫婦２人ですと、２１１万円という金額になります。対象ですけれども、今現在、新しい制度ですので、社会保険庁のほうから、そういうデータをもらっているんですけれども、はっきりとした数字はまだ出ておりませんけれども、大体、２万５,０００人ぐらいと予定しております。","voiceIndex":264,"id":"exchange-105"},{"speaker":"安藤委員","kind":"質問・要望","question":"フラット化の前の平成１７年と、平成２１年、来年度の住民税と、負担は住民税だけではありません、それに連動して国民健康保険、介護保険料もありますので、平成１７年度、２１年度のそれぞれの住民税の額、これは年金２００万円の単身者の方の例でお聞きします。住民税、国保料、介護保険料、それから所得税、それぞれの額と、合計金額、平成１７年度と平成２１年度を比較して教えていただきたいと思います。","respondent":"武内税務課長","answer":"２００６年については、住民税は１万円弱、所得税については３万円弱というような金額だと思います。住民税はフラット化がありましたので、平成２０年度と２１年度は、税源移譲が行われておりますので、住民税と所得税の関係は変わっておりません。","voiceIndex":266,"id":"exchange-106"},{"speaker":"安藤委員","kind":"質問","question":"平成１７年度から平成２１年度を比較しますと、実際に２００万円以下の方が、どういう負担増になっているかといいますと、住民税、国保料、介護保険料、所得税全部合わせて、平成１７年度は６万１,８００円だったものが、１７万９,５６５円、ほぼ１８万円なので、何と約１カ月分の年金が消え、しかも、４年間で１２万円上がっております。これは憲法違反なのではないでしょうか、いかがでしょうか。","respondent":"武内税務課長","answer":"もののとらえ方は、さまざまな視点からとらえて、そういうご意見もあるとは、私も一部理解するところもありますけれども、決してこれは憲法違反だということではなくて、そういう制度の切りかわりは、世代間の負担の公平さ、あるいはまた少子高齢化のため。","voiceIndex":268,"id":"exchange-107"},{"speaker":"安藤委員","kind":"質問","question":"今後、品川区独自の方法などで検討できる部分は検討していきたいとお答えされておりますけれども、具体的に、１週間前に相談したらどうなるんでしょうか。税務署等との連携などはあるんでしょうか。相談するためには、１週間前に相談できますということを区民が知っていないと、相談しようがないと思うので、そういった相談体制の周知、通知というのは具体的にどのようにするのでしょうか。","respondent":"武内税務課長","answer":"そういった中で、委員、言われるとおり、生活の激変がありましたら、どうぞ事前にご相談くださいということは説明しています。","voiceIndex":270,"id":"exchange-108"},{"speaker":"安藤委員","kind":"質問・要望","question":"確実に、その方の生活を脅かすことになるわけですよね。相談を受けた場合、いろいろ説明しますというお話ですけれども、具体的に相談が来ました場合は、１週間前に、どのような態勢をとってくれて、どのように相談に乗ってもらえるんですか。税務課の方と相談して、では、天引きは待ってあげようとか、そういうこともあるんですか。そこら辺、具体的なところを詳しく教えていただきたいと思います。","respondent":"武内税務課長","answer":"委員言われるとおり、納付日というのがありますので、それ以前に相談にきていただければ、ストップするということも、当然できますので、それは私どものほうの徴税の担当の職員のところにお出でいただければと考えております。","voiceIndex":272,"id":"exchange-109"},{"speaker":"安藤委員","kind":"質問","question":"相談するためにも、相談も可能ですよという通知を、どのように徹底するのかということを、もう一度答弁。それで、今、区民税、特別区税条例の第３６条で、区民税が減免できるという規定がありますけれども、今こそ、そういう税制度の改正と、相談の案内とあわせて、第３６条の減免の周知徹底、活用をすべきだと思うんですけれども、あわせて伺いたいと思います。","respondent":"武内税務課長","answer":"ホームページもごらんいただいておわかりのとおり、もし納付期日までにお支払いできない場合については、必ず連絡をしていただきたいということをお願いしております。これは何も、年金の特別徴収の方に限って言うことではなくて、品川区民皆さんに周知を図っているところです。","voiceIndex":274,"id":"exchange-110"},{"speaker":"安藤委員","kind":"質問・要望","question":"年金天引きの方に限ってではないということですけれども、年金天引きの人は、今までとは違って年金から否応なしに天引きされてしまうわけですから、特別に天引きの前に通知を行うぐらいのことを、ぜひやっていただきたいと、私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":276,"id":"exchange-111"},{"speaker":"山路委員","kind":"質問・要望","question":"午前中の質問で、今後、支援に対しては検討していくということでしたが、もう少し突っこんで、技術提携まで踏み切って、今後の教育、ものづくり支援とか、あるいは技術開発とか、産業振興に生かされるところまで突っこんでもいいのではないかと思いますが、確認の意味でお伺いいたします。４点目は、１３９ページ、雑入のところで、水と緑の市町村との交流事業参加費について、お伺いいたします。","respondent":"金子産業振興課長、冨岡高齢福祉課長、河野指導課長、小野区民課長","answer":"ベンチャー創業支援センターのお尋ねですけれども、これは、先ほども、若干ご説明申し上げましたが、ブースのところは３年。ただ、原小学校跡の施設につきましては、ケアが一緒についている特定の施設ですが、これにつきましては、住宅ということで。平成１９年度につきましては、１２校、８１８時間、平成２０年度については、現在進行中ですが、１９校、１,２５２時間。新就農、就林の事業ということで、これを交流事業の中で何とか活用ができないのかというご指摘ですけれども、早川町。","voiceIndex":278,"id":"exchange-112"},{"speaker":"山路委員","kind":"質問","question":"林町の基本設計ですが、これから基本設計で、来年から建築に入っていくと思いますので、コーディネーターという非常に大事な役割が必要になってくると思うんです。その辺については検討されているのか、お伺いいたします。","respondent":"冨岡高齢福祉課長","answer":"ただ、中心になりますのは、小規模多機能居宅介護の事業所が中心になっていくのかなという形で、これからの課題ですけれども、大体、そんなような図かなと考えています。","voiceIndex":283,"id":"exchange-113"},{"speaker":"山路委員","kind":"質問・要望","question":"もう少しあるみたいのですので、この国庫補助金は、説明のときに、林町という説明がありましたので、それについてお伺いしたんですが、今度、住情報センターも、平成２１年度からやるということですが、その中でコーディネーター機能を強くしていただきたいことを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":285,"id":"exchange-114"},{"speaker":"大沢委員","kind":"質問","question":"６６ページ、総務使用料の中の６９ページの設備使用料、それからもう一つが、やっぱり使用料なんですけれども、７７ページ設備使用料等、移りまして、今度は８５ページの土木手数料、広告板・塔について、表記の仕方を伺いたい。それから後半、１３９ページのリサイクル資源売払収入、資源回収事業、それから、時間があれば９９ページの目黒線の緑道を伺いたいと思います。","respondent":"堀越生涯学習課長、松代管理工事課長","answer":"６９ページ、設備使用料、それから、設備使用料等ですが、設備使用料につきましては、文化センターでお使いいただくマイクですとか、そのような設備機器のことです。平成２０年度、表記３,９００件という表示、今年度は３,２００m2という表記の違いです。大変申しわけございません、これまで件という形で誤記の表記をしてございました。それに気づきまして、m2に改めて訂正したものです。","voiceIndex":287,"id":"exchange-115"},{"speaker":"大沢委員","kind":"質問・要望","question":"ただいまの件については、わかりました。今ちょっと、今まではということで、気をつけていただきたいんです。これはほんとうはこの場で聞く部分ではなくて、直に課長のところに行って、ご指摘するべきだったとは思いますけれども、あえて、今気がつきましたので、私、指摘をさせていただきました。１３９ページになります。そこの部分について、品川区の現状をお聞かせ願いたいと思います。","respondent":"秋山資源循環推進課長","answer":"資源回収ステーションで、区民の皆様から出していただいた資源を、資源化センターのほうで集めておりますけれども、私どもの資源化センターから回収業者のほうに送っておりますけれども、現在のところ、行き場がない、まだ引き取りを拒否されたということはございませんで。","voiceIndex":290,"id":"exchange-116"},{"speaker":"大沢委員","kind":"質問","question":"順調ということです。ただ古紙の単価と、今払っております集団回収に対して、回収実績において、１kg６円を支給するということで、もろもろのバランスを考えた場合、これは財政的に大変にならないのか、そこら辺の見通しを、ちょっと伺いたいと思います。","respondent":"秋山資源循環推進課長","answer":"古紙の単価でありますけれども、売払の収入につきましては、市況によって左右されますので、平成１９年度は１億６,０００万円程度、平成２０年度も、見通しですけれども、１億９,０００万円程度入る予定ではあります。","voiceIndex":292,"id":"exchange-117"},{"speaker":"大沢委員","kind":"質問","question":"平成１７年度、４３８団体、平成１８年度、４７１団体、平成１９年度、４８４団体。報奨金および協力金、平成１７年度については６,０００万円余、平成１８年度については６,３００万円余、平成１９年度は６,８００万円余ということで、年々増えております。そういう危機感を持たれたほうがいいと思うんですけれども、そこのところは、いかがお考えになりますでしょうか。","respondent":"秋山資源循環推進課長","answer":"集団回収をしている団体につきまして、すべての資源ですけれども、１kg当たり６円をお払いしているという状況ですので、特にこの金額が市況とリンクしているということではございません。","voiceIndex":294,"id":"exchange-118"},{"speaker":"大沢委員","kind":"質問・要望","question":"ようやく今度、完成を見るわけですけれども、そこの中で、協力をしていただいた方たちに対する対応の仕方を、私は今回、お伺いをしたいと思います。沿道に関して、今、いろいろな東急との事後交渉、工事のあとと先、補償というか、もとに戻していただきたいというような件数がどのぐらいあるのか、教えていただきたいと思います。長くなっちゃうので、第１緑道と第２緑道の沿線で結構です。","respondent":"浜脇街路事業担当課長","answer":"そういった中で、まだそのうちの１,２００件ぐらいが、ご迷惑がかかったと伺っていますので、それについて、ご了承いただいている部分と、今後もまだ補償交渉をやっていきますけれども、若干、残っているというのが現状です。","voiceIndex":296,"id":"exchange-119"},{"speaker":"大沢委員","kind":"質問・要望","question":"補償交渉をやっていただいている。あくまでも区ではなくて、東急なわけですけれども、東急が補償交渉の窓口になっているのは東急本体なんでしょうか、それともしかるべき別の会社に任せて交渉をやってもらっているのか、どちらか教えていただきたいと思います。","respondent":"浜脇街路事業担当課長","answer":"あるいは、東急から発注しております建築会社、工事会社がありますが、そういった方々の状況も踏まえてやっていますので、一時的には、東急、あるいは土木会社といったものが組んでご説明をしているです。最終的な責任を負うのは、事業団である４社です。","voiceIndex":298,"id":"exchange-120"},{"speaker":"大沢委員","kind":"質問・要望","question":"最終的な責任を負うのは４社ということですけれども、交渉に当たっているのはどのような会社なのか、教えていただきたいと思います。","respondent":"浜脇街路事業担当課長","answer":"私どもから、東急を通して委託をしている補償会社です。この会社は、申しましたように、工事前、工事後の状況等を把握いたしまして、それらについて、私どもが判断をいたしまして、最終的にはその会社に任せてやってあります。","voiceIndex":300,"id":"exchange-121"},{"speaker":"大沢委員","kind":"質問","question":"補償会社が窓口で補償交渉を行っているということなんですけれども、やはり、周りのお話を聞きますと、やはり工事の前と後で家屋が変わっていたりするわけです。あまりに事情を知らなすぎて、一律の基準で交渉を決めて、交渉を運んでいるきらいがあるということで、そのような話を聞くんですけれども、そこのところはどのようにご認識をされておりますでしょうか。","respondent":"浜脇街路事業担当課長","answer":"そういったことについて、いろいろなご意見があれば、もう１回フィードバックして、我々の中で検討した結果を持って、東急も含めて行かせているところです。","voiceIndex":302,"id":"exchange-122"},{"speaker":"大沢委員","kind":"質問・要望","question":"いずれにいたしましても、もう完成します。非常に皆に祝福されながら事業を完成するのが私の望みであると同時に、地域の望みであると思いますので、なにとぞ、東急のほうに、算定に当たっては、そこのところを斟酌されながら交渉に当たっていただきたいということで、区のほうからご助言をしていただきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":304,"id":"exchange-123"},{"speaker":"西本委員","kind":"質問","question":"私からは、１０６ページ教育費負担金、補正のときにもお話ししましたけれども、水道管直結化事業、それから、１２０ページのオリンピックムーブメント委託金、同ページ、統合型地域スポーツクラブ設置委託金、これは先ほども質問がありましたけれども、非常に納得いかないところがあるので、お話ししたいと思っています。それの進捗状況がどうなっているのかというところを、お聞きします。","respondent":"田村庶務課長、久保田行財政改革担当課長、堀越生涯学習課長","answer":"区といたしましては、直結管に場所的に近い構造の部分と、学校が老朽化しているところについて優先的にやろうということで、お尋ねの改築等につきましては。オリンピックムーブメント事業の運営主体ですけれども、この事業につきましては、東京都と区市町村によります共同推進事業と位置づけられておりますので。平成１９年度、２０年度、そして平成２１年度の３カ年の事業で、平成２２年４月のスポーツクラブの設立に向けまして、現在。","voiceIndex":306,"id":"exchange-124"},{"speaker":"西本委員","kind":"質問","question":"オリンピックムーブメントについてですが、区が直接いろいろやるという理解でよろしいのでしょうか。ですから、運営主体も、区が直接ということよりは、例えばＮＰＯであるとか、地域の方たちであるとか、スポーツ協会等々ありますので、その方たちと一緒に気運を高めていくということが仕掛け的には必要なのではないかと思いますので、それに関してのお考えをお聞きします。","respondent":"田村庶務課長、久保田行財政改革担当課長、堀越生涯学習課長","answer":"水道管直結化の内容ですけれども、平成２２年度まで東京都のほうが実施するということで、以前にもお話ししましたように。ただ、実際の事業を進めていく中で、当然、スポーツとか、そういった事業を進めてまいりますので、スポーツ協会との協力、連携は必要だと考えています。スポーツクラブのお尋ねですが、現在の進捗状況ですが、規約の整備、それから組織のあり方等について検討を進めております。","voiceIndex":310,"id":"exchange-125"},{"speaker":"西本委員","kind":"質問・要望","question":"水道管については、効果を見ていただいて、区としてどういう方向でやっていくのかというのは、その間に見極めていただきたい、推進をしていただきたいと思っています。それこそ、子どもたちも含めて一緒に取り組むことによって、自分たちの夢というか、希望が出てくると思いますので、ぜひお願いしたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":314,"id":"exchange-126"},{"speaker":"須貝委員","kind":"質問","question":"私は、４９ページ、歳入、１２８ページ、基金繰入金、９０ページの学校施設整備費を絡めて質問します。特別区民税や各種交付金などが、平成２０年度の歳入と比較して、平成２１年度は約５０億円減っています。年間３００万円以下の所得者は、区民の中に大体どれぐらいいらっしゃるのか、そして、今後も区民税や各種交付金はさらに減少するのですか、その辺について、ちょっとお聞かせください。","respondent":"日下部企画財政課長","answer":"区民生活の実態ということでありますけれども、この間、私どもも議会、本会議等でご答弁申し上げてまいりましたように、やはりこのところの景気の急速な悪化を受けまして、それが地域経済、それから区民生活にもかなり影響が出ているということで認識しています。","voiceIndex":316,"id":"exchange-127"},{"speaker":"須貝委員","kind":"質問","question":"さて、繰入金を見てみますと、昨年度より約４０億円増えております。このような大口予算、ざっと見ますと、歳入約１,４００億円に対して、２０％の約２８０億円が、今回、教育委員会の予算となって出ているんですが、このような状況は、予算のバランスから見て、いいんでしょうか。今、このような日本経済の状況から見て、いいんでしょうか。その辺、ご見解をお聞かせください。","respondent":"日下部企画財政課長","answer":"どうしてもこれは、そのときどきの一つの政策展開なり、あるいは、そういう投資的な経費、これがどういう形で組み立てをしていくのかによってかなり増減をしてまいりますので、一概に教育費だけに多額の経費が投入されているとは、私どもは認識しておりません。","voiceIndex":318,"id":"exchange-128"},{"speaker":"須貝委員","kind":"質問","question":"今、１０％の補助、約９０％が純粋、一般財源、区民税のほうから補われるわけですが、確かに品川区は耐震問題がありまして、区内の学校の改築を急速に進めざるを得ないという状況はわかります。物を大事にしろという中で、物の大切さを子どもたちに教えているのに、子どもたちの教育にとって果たしてこれはよいことなんでしょうか。その辺をちょっと、ご見解をお聞かせください。","respondent":"日下部企画財政課長","answer":"それが、そういう老朽更新の時期を迎えている。これは品川区だけではなくて、ほかの２３区におきましても同様でありますし、そういった意味では、いろいろ厳しい状況はありますが、最善の努力を尽くすのが行政の責務ではないかと考えております。","voiceIndex":320,"id":"exchange-129"},{"speaker":"須貝委員","kind":"質問","question":"よく濱野区長も、今は１００年の一度の大不況、大変な時代を迎えたと。おっしゃるのは、通常の状況だったら、私もわかるんです。ですが、周りの状況で、区民生活がこんなに大変な中で、こういう事業を急速に一気に押し進めるということが果たしていいんでしょうか、予算のバランスから、果たしてこれがいいんでしょうかというふうに、私は思うんですが、その辺ちょっとご見解を、再度お聞かせください。","respondent":"日下部企画財政課長","answer":"平成２１年度は、いろいろな要素が重なりまして、かなり学校関係の経費がかさんだ。","voiceIndex":322,"id":"exchange-130"},{"speaker":"須貝委員","kind":"意見","question":"品川区にとって、何ら問題がないと、それからバランス的にも問題がない。今、こういう状況を見ても、堂々とやれる。それはいいと思うんですが、私は、こういう状況こそ、地域経済が落ち込んでいる、また、国民、区民の所得が落ち込んでいる中で、もう少しそこに予算をシフトするというようなことも大切ではないかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":324,"id":"exchange-131"},{"speaker":"堺委員","kind":"質問・要望","question":"その段階で、その計画が積み上げられてきたわけです。今後１０年の濱野区政の大きな基盤とも言うべき基本計画に基づいた初年度のスタートがいよいよこれから始まるという中での予算案です。そういう中で今後の確認といいましょうか、勉強のために教えていただきたいのは、まず一つは、特別区民税については、対前年０.３％減、金額にして約９,５１０万円減少したものが、今年度、計上されているわけです。","respondent":"武内税務課長、日下部企画財政課長","answer":"それは、平成２０年度の決算の見込みにつきましては、平成１９年度ベースの賦課ということで計算しますと、納税義務者、またそれなりの景気もありまして、１３億円の増をさせていただいたということで、平成２１年度につきましては。財調交付金の算定の基礎ですけれども、実は、市町村民税法人分が、平成２１年度の見込みでまいりますと、平成２０年度が約８,０００億円でございました、これが６,４００億円ということで、約２割企業収益の悪化に伴いまして。","voiceIndex":326,"id":"exchange-132"},{"speaker":"堺委員","kind":"質問・要望","question":"そうしますと、大体、平成２１年度のこういう予算案ができてきた背景がわかってきたわけです。そういう面では、やっぱり基金の繰入れ、今年度も１５４億円、１２８ページに基金繰入金ということで計上されております。特に今年度よりも、さらに平成２２年度は経済状況が悪化してくるということが見通しとして立っているわけですね。その辺も含めまして、ちょっとお考えを教えていただければと思います。","respondent":"日下部企画財政課長","answer":"そういった観点に立ちまして、実施計画につきましても、今は新年度予算をお諮りをしているわけでありますけれども、この辺を基軸にして、今、最終的な詰めをしているという状況です。","voiceIndex":329,"id":"exchange-133"},{"speaker":"堺委員","kind":"質問・要望","question":"総合実施計画について、今、詰めをしているですので、ぜひ、そういう中で、基金の効果的な運用といったものを通しまして、区民サービスが低下しないように、ひとつ充実した計画が練られるように期待したいと思います、要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":331,"id":"exchange-134"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もう１点は、各区の動向を踏まえて、何かお考えがあれば聞かせていただきたいということが一つ。だからそれをお聞きしたいのと、歳出をずっと見ていくと、あまりお金をかけないはずだったと思いながら、これがほんとうに活用されればいいんですけれども、活用事業で５３６万５,０００円かけますよということになっているんですけれども、ここら辺のものごとの考え方を教えていただきたい。","respondent":"小野区民課長、工藤環境課長、志村生活福祉課長","answer":"私ども、やはり品川荘にしても、箱根荘にしても、区立の保養所ということで、使っていただいている方に対しては、大変使い勝手がいい。こちらのほうの２５人の内訳ですけれども、再生事業の参加者につきまして、宿泊費の補助を行うということになっておりまして。今回、ここに計上しております里山再生参加費につきましては、環境の視点から事業に取り組むという部分で。ですから、極端な話、港区に住民登録がある方でも、大井町の駅で倒れて窮迫した状態になりますと。","voiceIndex":333,"id":"exchange-135"},{"speaker":"石田（秀）委員","kind":"提案","question":"こういう提案もあれば、例えばしながわ水族館みたいな契約をしている区もある。そういうこととか、みんな考えて、３年前は、そういう規模の問題があったんでしょうけれども、私は、箱根荘も含めて、それはもう１回提案をしてもらうべきだと思うんですよ。それで、今後、どういうふうに動いていくんだということは、やっぱり実施をするべきだろうと思うので、そこら辺の見解をお聞きしたい。","respondent":"小野区民課長","answer":"里山につきましては、森林組合等の協力の中で、木材の伐採、あるいは運搬、道づくり等、この１年間でかなりの部分ができてまいりましたので、議員の皆様につきましても、何かの機会にお出でいただいて、その成果をごらんいただいて、またいろいろとご意見を伺えたらと思います。","voiceIndex":338,"id":"exchange-136"},{"speaker":"石田（秀）委員","kind":"意見","question":"ほんとうに、保養所はぜひ、そういう行動をしてもらいたいと思います。濱野区長が、あそこの上がったという松まではよく知っておりますけれども、ぜひ皆で１回、そういう体験をしてもいいと、私は思っているので、そればぜひ、また考えていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":340,"id":"exchange-137"},{"speaker":"土井委員","kind":"質問・要望","question":"それの関連で、区民住宅に係わることを伺いたい。それからもう一つは、簡単に伺うのは、８５ページ、廃棄物処理のことで伺いたいこと。もう一つは、１３３ページ、りんかい線のことで伺いたいと思います。そこで伺いたいんですけれども、今の事業をやるのに、特に一番最後の部分ですね、これらの考え方はどう考えたらいいんだろうか。ここに書いてあるのは何ですかということになるわけですね。","respondent":"日下部企画財政課長、齋藤住宅課長","answer":"それに対しまして、補助金の見込み、今、いろいろご質問の中にもありましたけれども、まずはやはり補助の割合がどのぐらいか、それから、どうしても大型事業ですと複数年にわたるものがありますが、でき高がどのぐらい見込めるのか。借上型区民住宅、７９ページにあります使用料の見込みですが、９６％を見込んで調定を立てております。","voiceIndex":342,"id":"exchange-138"},{"speaker":"土井委員","kind":"質問","question":"わかりました。そこら辺は、その意味では、初めから予算案のときに、これはそういうものなんだということを、きちっと皆さんに説明をしておかないと、実際上は、予算が膨らんでいるだけというふうになってしまうので、これからだんだん厳しくなってくると、その辺はちゃんとやっておかなきゃいけないと思うんですが、いかがでしょうか。ちょっとそこら辺の説明をお伺いいたします。","respondent":"日下部企画財政課長、齋藤住宅課長","answer":"それはまさしく、ご指摘のとおりであります。ただ、私どもとしましては、最大限当初予算の段階で見通しをしっかり立てて、できる限り精度の高い予算内容にしていきたいと、基本的にはこのように考えているところです。空き室の数ですが、今日現在、３９戸です。うち今、転居の時期ですので、うち１０戸は埋まります。長期の空き室は２９戸ということになっております。","voiceIndex":345,"id":"exchange-139"},{"speaker":"土井委員","kind":"質問","question":"わかりました。３万円でも、５万円でも稼ぐということも必要になってくるかもしれないので、考えておいてください。次に移ります。これについて、どういう状況になっているのか、ちょっとお伺いをしたいと思います。私もこの前、持って行って大歓迎をしていただいたものですから、ちょっと聞かせてください。それから、もう一つは、東京臨海高速鉄道なんですが、今回、貸付金の返還が始まったと伺ったんです。","respondent":"島袋品川区清掃事務所長、梶都市計画課長","answer":"日曜お持ち込みの件ですけれども、去年の７月からやっているんですけれども、当初は１日２０件ぐらいだったんですけれども、だんだん年末まで増えまして、今、大体平均５０件ぐらい。予算書に書いてあります１億６,０００万円ですが、これは臨海高速鉄道のほうの貸付金の返還金でございまして、今、臨海高速鉄道のほうでは、平成２０年度の中間決算の状況を見ますと、前年同期比で見ますと。","voiceIndex":348,"id":"exchange-140"},{"speaker":"土井委員","kind":"質問・要望","question":"確かに、最初の廃棄物の日曜日の集めですが、きちんと宣伝していただくと、意外とあるんじゃないかと思うんですよ。何で捨てるのかということの一環にも、家族の触れ合いにもなる中身じゃなかろうかと、このように思っておりますので、ぜひ、進めていただきたいという意味で、お話をいたしました。それらに期待する向きもあるんですけれども、そんな見通しは、今はまだ立ちませんか。","respondent":"梶都市計画課長","answer":"ただいまの、もっと線がというお話なんですけれども、今現在の状況は、今ある線をもちろん充実していくと同時に、あるいはＪＲとの乗り入れの本数をもう少し増やすとか、そういった形で、今、話が進んでいるということは聞いてあります。","voiceIndex":351,"id":"exchange-141"},{"speaker":"宮崎委員","kind":"質問・要望","question":"大崎駅周辺の再開発、支出のほうを見ますと、５８億４,０００万円余り出ていますけれども、この財源、税負担がどういうふうになっているかということについて、そういう角度から伺いたいと思います。それから、残りが５億６,６００万円ぐらいになるかと思うんですけれども、これが区の負担になるかどうかということ、まず、そこのところを確認させていただきたいと思います。","respondent":"青木都市開発課長","answer":"１４０ページに都市基盤整備費収入というものがありますけれども、こちらは、各事業者が受益者負担に基づいて、品川区に負担金を支払うというものでございまして、これが主に都市再生総合整備事業の品川区負担を、事業者負担の分として。","voiceIndex":354,"id":"exchange-142"},{"speaker":"宮崎委員","kind":"質問","question":"区の負担が、財政調整交付金のほうで算定されているということになると思うんですけれども、本体のほうの２８億円を区が負担するんですけれども、財政調整交付金のほうの算定基準は、この２８億円そのまま１００％みているということになるのか、どうかということを伺いたいと思います。差があるのか、どうか、そこのところを伺いたい。差があるとすると、幾らぐらいなのかということを伺いたいと思います。","respondent":"青木都市開発課長","answer":"再開発補助金に対する財政調整は全額ということでご理解いただきたいと思います。","voiceIndex":356,"id":"exchange-143"},{"speaker":"宮崎委員","kind":"確認","question":"いわゆる本体部分ですよね、そこがそうなんですけれども、都市再生のほうは、都の考え方というのは、今全然ないということなんですけれども、国のほうは、内容によりますけれども、２分の１とか、３分の１とかいろいろあるんですけれども、都市再生総合整備事業のほうは、そうすると、事業者負担はあるけれども、かなり区が持っていくということでいいんでしょうか。そこを確認したいと思います。","respondent":"青木都市開発課長","answer":"補助金以外のもの、一定の事業者からの負担金はいただいていますけれども、原則として補助金以外のものについては、区の一般財源からの支出ということで、ご理解いただければ間違いございません。","voiceIndex":358,"id":"exchange-144"},{"speaker":"宮崎委員","kind":"質問","question":"例えば、今度、着手する北品川五丁目第１地区なんですが、本会議でもちょっと質問しましたけれども、一昨年は、説明では、総事業費９５０億円だったと。それで、補助金が１３０億円の予定だったのが、２６４億円に増えると。２倍以上の１３４億円も増えているんですけれども、ここの変化のところで、国の補助金と都の補助金、区の負担、そこのところはどういうふうに変わっていくのか、伺いたいと思います。","respondent":"青木都市開発課長","answer":"北品川五丁目の事業費につきましては、事業計画をまとめ上げましたのが平成２０年で、ちょうど鋼材価格等が急激に上がっている段階でしたので、当初の予定よりも高くなっております。","voiceIndex":360,"id":"exchange-145"},{"speaker":"宮崎委員","kind":"質問・要望","question":"もう一つは、やっぱり、今、非常に鋼材等が高騰している。この時期に何でやるんだと。これはちょっとストップしておこうということにならないのか、どうなのか。そういうことは、実際に制度上ないのか。あるいは、区のほうとしては、どういうふうに考えているのか、そこのところをお聞かせいただきたい。そこのところは、例えば時期がずれれば、全然変わってくると思うんですけれども、どうなんでしょうか。","respondent":"青木都市開発課長","answer":"現在のところ、おそらく認可はされるであろうという見込みで事業を進めているところでございまして、何よりもやはり、企業権利者が多いとはいえ、権利者の方々の財産を変えていくというプロジェクトですので、これまでに長い間。","voiceIndex":362,"id":"exchange-146"},{"speaker":"宮崎委員","kind":"質問・要望","question":"事業の認可の審査中だということで、要するに、採算がとれるかどうかという判断ということですよね、今の説明ですと。私が言ったのは、あえて何でこんなに補助金が増えるときにやるんだと、この点は、考慮されないのか、どうなのかということなんですよ。あるいは、区としては、そういうことがあっても進めるということなのか、どうなのか、お聞かせいただきたいと思います。","respondent":"青木都市開発課長","answer":"再三申し上げますとおり、いろいろな権利者の方々が長年、再開発をやろうということで検討してきたのが組合施工の再開発ですから、この急激な状況変化によって、たまたま今の段階では、事業計画、資金計画がかなり高いものになっている。","voiceIndex":364,"id":"exchange-147"},{"speaker":"宮崎委員","kind":"確認","question":"朝一番の方の質問とも関連するんですけれども、投資効果というお話がありました。大崎のあたりは１.７から１.８、２を超えるところもあると言っていましたけれども、ここがよくわからないので、教えてほしいんですけれども、投資効果というのは、具体的にどういうものか。何をどういうふうに計算しているのか、ここのところをちょっと伺いたいと思います。","respondent":"青木都市開発課長","answer":"そういう中で、ここの大崎駅周辺の開発が進めば、周りの利便性が高まって、土地の評価も高まるであろうということを試算しまして、それらを評価していって、結果として、１の投資に対して１.７とか、場合によっては２を超えるような経済波及効果があると算定するものです。","voiceIndex":366,"id":"exchange-148"},{"speaker":"宮崎委員","kind":"質問","question":"１３０億円ではなくて１００億円だというお話であれば、何かちょっと先ほどの話と、私はそんなに問題、そこのところは後で。いずれにしても、さっきも言いましたように、特別養護老人ホームができない、補助金がないからだと言いますけれども、こっちのほうには出すわけですよね。これは、ほんとうに税金の使い方としておかしいということを、私は言っておきたいと思います。見直しをお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":368,"id":"exchange-149"},{"speaker":"三上委員","kind":"質問","question":"この件と、それから、１３１ページの歩行喫煙防止過料について、ちょっとお伺いしたいと思います。１人だけまず捕まえようかということで、いただこうかという雰囲気なんですけれども、平成１９年度の実績、それから、平成２０年度は途中ですけれども、過料をお払いいただいた方の実績はどういうふうになっていますか、ちょっとお教えいただけますか。","respondent":"堀越生涯学習課長、高濱生活安全担当課長","answer":"校庭の利用に関してですが、２,３０３回の内訳といたしましては、社会教育登録団体ですと５０％の減額になりますので、校庭が１回８００円単価で、６００回という内訳です。そのほか、一般の利用の方が倍の１,６００円の金額。過料の実績についてですが、本年度は、これまでに１６件の取り締まりをしております。これまで、平成１５年の制定当時から１４７件の取り締まりを行っております。","voiceIndex":370,"id":"exchange-150"},{"speaker":"三上委員","kind":"質問","question":"歩行喫煙防止で１４７件指導したということで、少し悪質だというので過料を科したということで１６件ということなんでしょうか。それとも、まだまだ中途半端なところもあるんだというような考え方でいるのか、そこらあたり、現状をどうお考えになっているのか、お伺いします。","respondent":"堀越生涯学習課長、高濱生活安全担当課長","answer":"夜間照明の設備が設置してある校庭ですが、１７地区のスポレクのエリアに１カ所を基本に設置しておりまして、現在、１８校に設置をしています。ご説明が足りない点がありましたので、再度、説明いたします。１４７件と申しますのは、平成１５年から取り締まりを開始しまして、これまで過料を徴収した累計です。なお、１６件というのは、平成１９年度の取り締まり件数です。","voiceIndex":373,"id":"exchange-151"},{"speaker":"三上委員","kind":"質問","question":"夜間照明の件ですけれども、１８校ということで、これ以上広めようという考え方はないのか、どうかなんです。それとも、新しくつくりかえていくときに、地域の皆さんに、こういった状況も考えられるんだから、新しい学校に建て替えるんだから、夜間の照明をつくってはどうでしょうかと、地域のご理解をいただくような、皆さんに対する取り組み方をしているのか、どうか。","respondent":"堀越生涯学習課長、高濱生活安全担当課長","answer":"しかしながら、防犯灯を備えている学校もございまして、子どもたちのサッカーですとか、比較的照度が低くても対応できるようなスポーツについて、７時ぐらいまででしたら対応しているという実態もあります。一方、たばこ自体は法律で禁止されているものではございませんし、嗜好品ですので、ポイ捨てはしないから吸う場所を設置してくれという声もあります。両者の併存を目指しながら進めております。","voiceIndex":376,"id":"exchange-152"},{"speaker":"三上委員","kind":"質問・要望","question":"たばこのほうですけれども、私は、武蔵小山周辺を歩いていても、めぐり会うのはほんとうにまれですよね。商店街の中で、たまに会ったりはする。だけれども、商店街を外れた２６号線とか、そのほかのところで、そういう人たちに会うということはなかなかない。どこまでそれを実現していこうかということについて、もう少し真剣に取り組んでいっていただきたいと、課題として申し上げておきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":379,"id":"exchange-153"},{"speaker":"鈴木（真）委員","kind":"確認","question":"私のほうは、７９ページ、使用料の中から土地建物使用料、まちづくり事業用地等と書いてあるところを、ちょっと確認です。それから、９９ページ、国庫補助金の中の細街路拡幅整備事業補助基本額ということについてお聞きしたいのと、債務負担行為の考え方と、予算という意味で、ほかの方の質問とちょっと重なるかもしれませんが、ちょっとその辺で教えてください。それが１点。","respondent":"青木都市開発課長、片田建築課長","answer":"私からは、７９ページ、土地建物使用料のまちづくり事業用地等について、お答え申し上げます。それで、当初、試算の中では、工事費前年度は１,２００万円ほど予定しておりましたので、区道の割合に沿った形で、当初１億２,０００万円ほど予定してございましたので、区道の割合を約３分の１と想定して、４,０００万円。","voiceIndex":381,"id":"exchange-154"},{"speaker":"鈴木（真）委員","kind":"質問","question":"行政財産の使用料が、逆に言うと、どういう計算根拠にしているのかなというのが、賃料的にも、その辺、もしあれだったら教えてください。細街路のほうは、わかりました。全体として、たしか先の事業費でいくと、１億６,５００万円という細街路拡幅、これは歳出になりますが、かなり大きな金額なんで、もっとこれからも出てくるのかどうか。大体どのぐらい、これからの見通しだけちょっと教えてください。","respondent":"青木都市開発課長、片田建築課長","answer":"行政財産の使用料の考え方、概略を申し上げます。貸付ではなく使用許可という処分であって、１年ごとの更新ということで、向こうに権利が発生しないというのが行政処分上の使用許可です。そういった点で、まず評価額が安くなっている。ただ、区道沿いのものについては無償使用をして、拡幅したものが区道としての対象になってきていますので、それを実績見合いの中で、今後、増えてくる可能性が十分にあると思いますので。","voiceIndex":384,"id":"exchange-155"},{"speaker":"鈴木（真）委員","kind":"提案","question":"ですから、もうちょっと増えるのかなという感じがした。それと同時に、これが１年とか２年の範囲ですから、これはあまり先々の世代間負担ということにまでいかないと思うんですけれども、今、これから品川区としてずっと経営していく、ある意味で経営ですよね、そういう中で、現役世代の負担と、これからの方が負担をしていく部分、そのバランス的なものを、現状でどうとったらいいのか。","respondent":"日下部企画財政課長","answer":"しかし、全体の事業フレームといいますか、財政上の内容を抜きにはできませんので、また先ほど出てまいりましたが、特定財源の裏付けがあるかどうか、やっぱりそういうことを総合的に勘案いたしまして、場合によっては、せっかくの提案であっても。","voiceIndex":387,"id":"exchange-156"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それこそ基金の運用だと思うんですけれども、せっかく事業部がつくってきた事業計画、また同時に、それは区民サービスに向かう話でしょうから、ただ、今の基金というのは前の方が残してくれた基金だと思うので、そこら辺もうまく運用しなきゃいけないと思うんです。全体として、これからも健全経営をしながら、行政サービスを果たしてもらうように、ぜひ、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":389,"id":"exchange-157"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=912#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":124115,"voices":390}},{"id":"h21-20090310-3","meetingId":"h21-c-budget","date":"2009年3月10日","dateIso":"2009-03-10","committee":"予算特別委員会","time":"午前１０時０２分～午後６時１９分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を149件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２１年度品川区一般会計予算","agenda":"平成２１年度品川区一般会計予算","exchanges":[{"speaker":"井桁委員","kind":"質問","question":"私は総務費の中で、１５５ページ、１目一般管理費の庁舎整備費に関連して、組織改正に伴って今年庁舎の整備を行うと思いますが、その点をお伺いしたいと思います。先ほども課長のほうから説明がありましたけれども、今後具体的にどういった計画になるのかということと、あと今後について簡単にお伺いできればと考えています。","respondent":"小野区民課長","answer":"大体スケジュールといたしましては、４月から策定をいたしまして、９月ごろに中間のまとめを行いまして、そしてパブリックコメントを行いまして、年度内に策定というふうなことを考えております。","voiceIndex":4,"id":"exchange-001"},{"speaker":"井桁委員","kind":"質問・要望","question":"次に移りまして、１５５ページの庁舎整備等に関連して、今年組織改正が行われる中で、庁舎の移動というのも行われると思うんですけれども、それに関しまして、来庁した方がスムーズに運ぶようにしていただきたいと思っておるんですが、その点への改善等々ありましたら、お伺いをしたいと考えています。","respondent":"阿部経理課長","answer":"４月１日の組織改正に向けまして、今レイアウト変更していますけれども、来庁者の方については、従来から３階あるいは２階のエレベーター前で案内を差し上げております。","voiceIndex":6,"id":"exchange-002"},{"speaker":"井桁委員","kind":"質問・要望","question":"次の質問なんですけれども、１５９ページの広報経費の全般についてなんですが、先般もありましたが、ホームページの検索が非常にわかりやすくなっていたりとか、そういった改善等々がかなり見られると思うんですけれども、やはりまだまだ使い勝手と、あとデザインのことについてもいかがかなと思っておるんですが、その辺のホームページの考え方と、やはり今後改善はしていっていると思うんですけれども。","respondent":"中川原広報広聴課長","answer":"ホームページのお尋ねです。この間、平成１９年度までにホームページのリニューアルをしてまいりました。","voiceIndex":11,"id":"exchange-003"},{"speaker":"井桁委員","kind":"意見","question":"どなたにでもというのは、やはり行政にとっては非常に大切なことだと思うんですけれども、やはり検索のことであったりとか、あとはいろんなところに飛んでしまうのもまだまだ見受けられるかなと考えていますので、その点ぜひ改善をお願いしたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-004"},{"speaker":"浅野委員","kind":"質問・要望","question":"最初に、この情報システム運営費ですけれども、情報セキュリティの強化、パソコンリース期間の延長、情報システムの、ＢＣＰですけれども、こちらの事業内容についてお伺いしたいんですが、パソコンリースの期間は５年から７年ということで、延長ということで１台当たりにどのぐらいの削減率になるのかということと、情報システムのＢＣＰについては、こちらのほう。","respondent":"原情報システム課長","answer":"しかしながら、区民の皆様との直接の窓口、そういったときにトラブルがありますと大変なことになりますので、その辺については臨機応変に対応していきたいということで考えているところです。","voiceIndex":15,"id":"exchange-005"},{"speaker":"浅野委員","kind":"提案","question":"パソコンリース期間の延長についてはわかりました。例えば、一般質問でも地域ＳＮＳの提案もさせていただきました。メール配信サービスの質問もさせていただきましたけれども、これらのライブラリーの中に含まれているわけですので、ぜひともこちらのほうも部内、また庁舎内でも共有化をしながら有効なものは使うようにしていっていただきたいと、そのように思います。これは要望です。","respondent":"久保田行財政改革担当課長","answer":"基地局を設置したことによりまして、テストを重ねまして、今後の展開ですけれども、サービスとしては、まずＰＣＭ－ＣＩＡカードを使用したインターネットサービスを開始していきたいというふうに予定しているです。","voiceIndex":17,"id":"exchange-006"},{"speaker":"浅野委員","kind":"質問・要望","question":"この点はここで終わりにしまして、残りの時間で残りの項目をしますけれども、全部やる意気込みです。平成１７年の第１回定例会で、こちらは近隣セキュリティの件ですけれども、区議会公明党といたしまして、情報配信サービスの件について、その中で近隣セキュリティシステムを利用して、犯罪者情報などを協力員に配信をするという質問をしましたところ、検討するという回答をいただいております。","respondent":"高濱生活安全担当課長","answer":"ご指摘の犯罪者情報あるいは防災情報につきまして、近隣セキュリティシステムのメールを使えないかというご提案につきましては、今行っています協力員への協力者情報などの配信についても、そういうふうなものができればすばらしいと思い検討しておりました。","voiceIndex":19,"id":"exchange-007"},{"speaker":"浅野委員","kind":"質問・要望","question":"最近、住民の方からひもを引く機会もないというような話も伺っております。やはり、訓練をしないことには、いざというときに引けないというのも前にも議会の中でもあったかと思いますけれども、例えば新しく１年生になる、この４月の時期とかそういうときに、教育も含めてぜひともそういう機会を定期的に求めていっていただきたいと、そのように思います。","respondent":"中山防災課長","answer":"ですから、実態とそぐわない点が出てこようかと思いますけれども、その辺につきましては、また臨機応変に対応してまいりたいと思ってあります。","voiceIndex":21,"id":"exchange-008"},{"speaker":"浅野委員","kind":"質問","question":"このような中でも、この二つのサービスを継続するための検討は引き続きというか、今年度中ぐらいに実施をされるというふうに伺っておりますけれども、具体的な策というものがあれば、この点をお伺いします。４月１日からスタートされるのか。そして、これは実際に２３０台、防災テルてるで連絡をする場合には、どのぐらいの時間がどのぐらいに短縮されるのかということを、目安で結構ですのでお願いします。","respondent":"中山防災課長","answer":"防災テルてるの関係ですけれども、今般機器を変更する場合は、いわゆるメール機能もついたものというような、そして簡単に取り扱いできるようなものということで機種を選定してまいる予定です。","voiceIndex":23,"id":"exchange-009"},{"speaker":"浅野委員","kind":"質問・要望","question":"防災計画の中に、区役所内に臨時スタジオ機能を設置して、区本部から放送可能にして、区長からも直接区民の方にお知らせができるようなシステムというんでしょうか、スタジオをつくるという計画があると思いますけれども、本当を言いますと、今年度どういう計画なのかということと、ぜひともこういうものをつくるんであれば、区民の方々が、例えば生放送で何らかのアピールができるような。","respondent":"中川原広報広聴課長","answer":"仮設スタジオについては、既にいざというときのためにセットは置いておりますので、ご要望のとおり頼りがいのある災害時の発信に努めていきたいと考えています。","voiceIndex":25,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、１４８ページからの総務費に関連しまして、品川区の職員給与費の考え方と行革との関係について幾つか質問したいと思います。もう一つ、今年は２８人の削減というお話でして、この１０年間で８６９人との説明がありましたけども、一体これで給与費だとお幾らのコストダウンという考えなのか教えていただきたい。","respondent":"榎本人事課長","answer":"非常勤につきましては、それぞれ専門的な部分で入れてきておりますので、最近ですと生活福祉関係の就労支援相談員とか、そういう形でのもの、それから高齢者の部分での認定調査員ですとか、そういう非常勤が増えているというふうに思っております。","voiceIndex":28,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"品川区はみずからワーキングプアをつくっていることをどう考えているのか、その認識と反省があるのか伺いたい。私は日本の輸出外需頼みの脆弱な経済体制とあわせて、国内の問題で言えば、派遣切りに象徴される非正規雇用の急増と一斉首切り、ここが大きいと思っています。伺いたいのは、品川区は区内の雇用悪化と区民生活の深刻な影響との関係、ここをどう考えているのか、ご説明ください。","respondent":"福田企画部長","answer":"この認識は現在の経済情勢が区民の生活それから営業活動、産業、こういうところに相当深刻な打撃を与えていると、こういう認識に基づくものですが、今ご指摘にありましたような経済状況と雇用との関係、これも本会議で申し上げましたけれども、そうした分析につきましては。","voiceIndex":30,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"少し具体的に伺いますけれども、区の正規職員と区の非常勤職員、まず原則論として同一労働、同一賃金、そこをしっかり貫くべきだと思うんですけど、この点はどう考えているのかということ。委託会社が同じでも、落札価格の変更で事実上時給が下がっている、こういった話を伺うんですけれども、ご存じなのか、ちょっと現状を教えていただけますか。","respondent":"榎本人事課長","answer":"それで、非常勤の賃金につきましても、時給換算でそれほど低いという形、全部１,０００円を上回っている非常勤の賃金単価ですので、それほど低いという形という認識はございません。","voiceIndex":32,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"同一労働同一賃金の原則を貫くべきだと指摘しても、それすら貫こうとしない。なぜ正規職員と非常勤職員と交通費の支給が違うのか。皆さん方は原則実費支給だと思いますけど、非常勤の方も同じにすべきだと思うんですね。調べてびっくりしたのは、１日３時間の非常勤は、交通費すら出さない。同じように職場に向かっているのに出さないとはけしからんと思うんですけれども、交通費についてはいかがでしょうか。","respondent":"榎本人事課長","answer":"非常勤につきましては、なるべく地域の方を優先してという形で思っておりますので、金額が低い形で支給している部分、それからあとは、勤務時間が短い場合についてはその部分は報酬単価のほうに含めてという考え方で、一律の部分で思っているところです。","voiceIndex":34,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"区の非常勤職員は生活できない給与、さらに交通費でも上限と言いましたけど、非常勤職員は１日たったの４２０円が上限。皆さんは幾らが上限なんでしょうか。行革の名でコスト削減の名目で地方自治体がワーキングプアをつくることが正しいのかと伺いたい。それで、地方公共団体が雇用に対する責任をどのように考えているのか、果たすべきだと思うんですけれども、いかがでしょうか。","respondent":"榎本人事課長","answer":"非常勤職員につきましては、その４分の３の範囲内という形になっておりますので、当然賃金は下がるという形になっております。その中で、ガバナンスの部分は私も記事を読みましたけれども、地方自治体が生み出しているとか、そういうものではないというふうに認識をしております。","voiceIndex":36,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"効率化の名目で同じように仕事をしておきながら、その生活に責任を負わない、こういうことは間違っていると思います。私もまだ聞いた限りですけれども、例えば児童センター、中小企業センター窓口などの窓口業務の委託、この庁舎の清掃などでも業者が変わって時給が下がったという話を伺いました。こういうことが委託先で起きていることが許されるのか、正しいと思うのか、ぜひ区の見解を教えてください。","respondent":"榎本人事課長","answer":"それで、逆にいけば、区の立場からいけば、同じ仕事を幾らの金額で請け負っていただけるのか、要は貴重な税金をより効率的に使うためにはそういう形での入札という形での仕事を委託しているというものです。","voiceIndex":38,"id":"exchange-016"},{"speaker":"中塚委員","kind":"意見","question":"改めて私は税金でワーキングプアをつくるのは間違っている、品川区は雇用責任を果たすべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-017"},{"speaker":"稲川委員","kind":"質問","question":"私、１６７ページの地域活動基盤整備補助、そして同じページの地域コミュニティ活性化助成金、１８７ページの区民消火隊助成金についてお伺いをいたします。例えば、今度建て替えについて今どんどん老朽化、耐震とかも含めて建て替えなければいけない町会というのは実際あるのかどうか、その辺をお伺いします。","respondent":"中山地域活動課長","answer":"いわゆる地域の町会数という言い方になると大体１６０町会になりますので、大体２分の１が会館をお持ちになっているです。支援ですけれども、建て替えあるいは新築の経費の２分の１助成ということで、最大１,８００万円までの助成を行う補助を行っているです。","voiceIndex":42,"id":"exchange-018"},{"speaker":"稲川委員","kind":"質問","question":"例えば、町会があって、その町会がどうしても町会会館が欲しいと。ただしかし、建てる土地がないとかというさまざまなケースがあると思うんですが、そういう町会も結構あると思うんですが、その辺について、もしそういう相談があったら、例えば区のあいている土地があれば、そこを有償で貸すとか、そういうお考えはありますでしょうか。","respondent":"中山地域活動課長","answer":"ただ、最近では、町会会館という形ではありませんけれども、区の施設を町会の方が主体になる活動に活用いただくような形でその場を活用の場としてお願いするような形はいろんな方法でとっておりますので、地域コミュニティの活性化の核である町会という観点での支援のあり方は。","voiceIndex":44,"id":"exchange-019"},{"speaker":"稲川委員","kind":"質問","question":"これは以上で終わります。例えば、集団回収というコミュニティが確立されていて、その町会のさまざまな行事にプラスになっていくとか、さまざまあると思うんですが、このコミュニティの助成というのはどういった部分に助成されるのか教えてください。","respondent":"中山地域活動課長","answer":"その基本認識は、さまざまこれから地域コミュニティの担い手、主体等は考えられるわけですけれども、やはりその核、基本となるのは町会・自治会であると。","voiceIndex":46,"id":"exchange-020"},{"speaker":"稲川委員","kind":"質問","question":"具体的にお話をしていきたいんですが、具体的に例えばある町会が、何かこれは地域のコミュニティだよと思ってそれの計画を立てて、それに対して申請書、多分審査もあると思うんですが、それについて助成をしていただけるという、例えはバス旅行もあれば、地域親睦を含めた野外でやるお祭りみたいなものもあると思うんですが、そういうのに対して助成をしていただける制度ということでよろしいでしょうか。","respondent":"中山地域活動課長","answer":"現在実際の給付について鋭意検討していますが、基本的には全町会・自治会に幅広く支援ができるような形で考えているところです。","voiceIndex":48,"id":"exchange-021"},{"speaker":"稲川委員","kind":"質問","question":"ぜひ幅広く、しっかりと、多分審査があると思うんですが、審査をスピーディーにしていただいて、この制度を利用しやすい基盤をつくっていただければと思います。１８７ページの区民消火隊に関してなんですが、区民消火隊について、区民消火隊自体は何によって組織されているのか、多分町会関係だと思うんですが、町会以外にもあるのかどうか、まずそれを１点お伺いします。","respondent":"中山防災課長","answer":"防災区民組織ですけれども、これは地元の地域の町会・自治会等で編成されてあります。","voiceIndex":50,"id":"exchange-022"},{"speaker":"稲川委員","kind":"質問","question":"ここにある６８隊というのは、６８町会の部分で組織しているのかという受け取り方でいいのか。多分、荏原、品川、大井、各消防署が、３消防署があるんですが、その比率というのか、荏原消防署の属する町会では何隊あるのか、個々教えていただければと思います。","respondent":"中山防災課長","answer":"したがいまして、１８２隊あるです。","voiceIndex":52,"id":"exchange-023"},{"speaker":"山内委員","kind":"質問・要望","question":"やはり経済がこのように不安定な状態になったとか、そういうことがあるかと思うんですけれども、そうはいっても、２０１１年の７月からですか、今いわゆる地上波も見れなくなるというような、あと２年しかないという中で、品川区は今把握している部分で構わないんですけれども、地デジの普及率と、それからあと２年しかない、その中で。","respondent":"久保田行財政改革担当課長","answer":"品川区の地上デジタル放送への対応の状況ですけれども、私どもでつかんでおりますのは、ケーブルテレビに加入している件数ということなんですけれども、今現在ケーブルテレビに加入、視聴可能というところの数字では８割というところになっております。","voiceIndex":55,"id":"exchange-024"},{"speaker":"山内委員","kind":"質問","question":"今課長のほうから品川区の環境が整っている世帯が８割ですか、その中の１５％は有料チャンネルを見ているから、地デジは２年後になっても大丈夫だというようなお答えをいただきましたけれども、ということは、１５％以外の人というのは、まだどうなるかもわからないということで、調査はしていないということでよろしいんですかね。「何ですか、それ」と言われる人がいまだにいます。","respondent":"久保田行財政改革担当課長","answer":"高齢者等への個別対応ということですけれども、総務省のほうの出先機関ということで、テレビ受信者支援センターというところと私ども、この間話し合う機会がございまして、そうした中で、まずは町会長会議等で広く切り替えを呼びかけながら。","voiceIndex":57,"id":"exchange-025"},{"speaker":"山内委員","kind":"意見","question":"了解しました。続きまして、地域活動費の中から町会加入促進パンフレット作成等委託９８０万円余と出ておりますけれども、非常に町会、いわゆる隣同士のコミュニティというものが希薄している中で、町会に入っていただくということは、本当に大事なのかなと思っておるんですけれども、このパンフレット、これを作成して、どのような形で普及をさせていくのかということをまずお尋ねをさせてください。","respondent":"中山地域活動課長","answer":"町会の加入促進、ＰＲのパンフレットですけれども、現在までに区内１３地区の地域センター管内のうち、５地区で既に作成をしておるところです。これは各地区の町会連合会に委託する形で連合会がつくっていただいたという形をとっております。","voiceIndex":59,"id":"exchange-026"},{"speaker":"山内委員","kind":"質問","question":"競馬場から出ているんですか、それは何でなんですかね。","respondent":"中山地域活動課長","answer":"端的に言うと、競馬場の来客者等の影響、地元に迷惑・負担があるということから、設置以降、地元の町会に助成がされている、こういうことです。","voiceIndex":63,"id":"exchange-027"},{"speaker":"山内委員","kind":"質問","question":"わかりました。先ほどもほかの委員から出ました地域コミュニティ活性化助成金、これはその地域の、各町会だと思うんですけれども、町会で一つ何か盛り上げてくれよというための助成金ではないのかなと思うんですけれども、この２,０００万円というこれ、どういう配り方をするんですかね。","respondent":"中山地域活動課長","answer":"基本的には活性化につながる活動ということで、例えば広報活動であるとか、回覧板も含めたような広報活動あるいは町会の運営のあり方を考える会議等、こういうものを支援対象にしながら、できる限り幅広く行き渡るように考えていきたい、このように考えております。","voiceIndex":65,"id":"exchange-028"},{"speaker":"山内委員","kind":"質問","question":"わかりました。そうすると、例えばうちの町会は盛り上げたい、もっとやりたいんだと言ったときに、ただちょっと予算がといったときに、例えば１回やって１０万円を使い果たしちゃったよ、その後、もっとやりたいんだけどどうなんですかといったときに、それはやっぱりなかなか難しい助成なんですかね。","respondent":"中山地域活動課長","answer":"今ご質問にあったような個別の活動に着目した支援というのは、これは例えば協働の提案制度なども含めて町会の独自の活動の支援というのは別途考えていくもので、今回は基本はベースを上げていくということを考えているものです。","voiceIndex":67,"id":"exchange-029"},{"speaker":"山内委員","kind":"質問","question":"わかりました。では、これはここまでにしておきます。すみません、２００ページの指定統計費の全般についてお尋ねさせてください。これは住宅土地統計調査がこのような形になったという説明を受けましたけれども、何か名称が変わってこれはどう今後変わっていくのかということと、それからその下に農林業センサスとあるんですけど、農林業センサスの中身を教えてください。お願いします。","respondent":"小野区民課長","answer":"農林業も同じように、農林業の全般をとるということですけれども、調査の対象といたしましては、３ha以上の年間１５万円以上の営農をしている方、あるいは林業としては３ha以上の林業ということが対象となっております。","voiceIndex":69,"id":"exchange-030"},{"speaker":"山元委員","kind":"質問・要望","question":"私のほうからは、１５３ページの人権啓発費の中から、また１５７ページの結婚サポート事業経費、そして１８１ページの区民斎場運営費についてお伺いいたします。最初に、１５３ページの人権啓発費の、この男女共同参画センター運営費についてちょっとお伺いいたします。","respondent":"吉岡人権啓発課長","answer":"男女共同参画センターへのご相談というご質問ですけれども、一応弁護士の関係の法律の相談と、それからカウンセラーのカウンセラー相談というのを行っているんですけれども、相談の内容は幅広くいろいろ家庭の問題ですとか、あるいは相続の問題もありますし、あるいは離婚の問題。","voiceIndex":72,"id":"exchange-031"},{"speaker":"山元委員","kind":"質問","question":"特にいろいろ取りざたされているドメスチック・バイオレンスですか、ＤＶはそういうご相談というのは、ここ近年いかがなんでしょう、多いんですか、少ないんですか。","respondent":"吉岡人権啓発課長","answer":"ただ、ＤＶの関係につきましては、人権啓発課、男女共同参画センターだけではなくて、いろいろなところで受けておりますので、区全体としては若干増加傾向かなというふうにとらえております。","voiceIndex":74,"id":"exchange-032"},{"speaker":"山元委員","kind":"質問・要望","question":"次にいきます。その中の２段上に男女共同参画第４次行動計画品川プラン策定というふうに書いてあります。たしか第３次計画は、平成２２年までかなと思います。ここに計上されているということはどういうことなのかなという素朴な質問というか、教えていただきたいと思います。","respondent":"吉岡人権啓発課長","answer":"今委員ご質問ありましたように、現在第３次の行動計画品川プランということで、平成１３年度から平成２２年度までの１０年間の計画で実施をしています。","voiceIndex":76,"id":"exchange-033"},{"speaker":"山元委員","kind":"質問","question":"具体的にまだ内容はこれから詰めるということになりますでしょうか。","respondent":"吉岡人権啓発課長","answer":"男女の共同参画に関する行動計画につきましては、従来から品川区の行動計画推進会議という公募の委員と、それから学識経験の委員をお願いして推進会議体を設置してございまして、そちらのほうで平成１９年９月からいろいろ検討していただいているところでございまして。","voiceIndex":78,"id":"exchange-034"},{"speaker":"山元委員","kind":"質問・要望","question":"次にまいります。１５７ページの結婚サポート事業についてお伺いさせていただきたいと思います。昨年から、この結婚サポート事業をスタートいたしましたが、何か好評だということで、今実際登録というんでしょうか、会員というんでしょうかね、どのぐらいいるのか。年齢の幅、一番お若い方から、また最高年齢と言っていいかどうかわかりませんが、その年齢を教えていただきたいと思います。","respondent":"小野区民課長","answer":"こちらは９月と２月に２回ほど実施をしておりまして、男女２０名ずつの４０名を対象として実施をしております。年代層ですけれども、２５歳、一番若い方が２５歳から２９歳の方、一番上の方が６０歳から６４歳という方が申し込まれております。","voiceIndex":80,"id":"exchange-035"},{"speaker":"山元委員","kind":"質問","question":"このセミナーの会費というんでしょうか、１人当たりの負担額というんですかね、それはどのぐらいの金額になりますか。","respondent":"小野区民課長","answer":"セミナーの参加費は、セミナーの後に続きます飲食を伴いますパーティーの経費ということで、５,０００円をいただいております。","voiceIndex":82,"id":"exchange-036"},{"speaker":"山元委員","kind":"質問","question":"１年たって、まだカップルとかというのはできているかどうかわからないんですが、できているかどうか、ちょっと教えていただけますか。","respondent":"小野区民課長","answer":"９月に実施をいたしました第１回目のセミナー、パーティーの後、こちらではいろいろとお話をしていただきまして、交際申し込みを受けて、それぞれで同意をされた方についてはおつき合いをいただくという形になるんですが。","voiceIndex":84,"id":"exchange-037"},{"speaker":"山元委員","kind":"質問・要望","question":"ぜひカップルができたけれども、他区に行くようなことのないように努力をしていただきたいし、また現実に、今年はぜひカップルになるようにお願いをしたいと思いますが、いかがでしょうか。","respondent":"小野区民課長","answer":"今申し上げましたように、アンケートの中では結婚を前提にして恋人がいるということで、自由意見欄のところにも、こういう紹介の中で将来を一緒にできるような恋人ができて大変喜んでいるというふうなお答えもいただいておりますので、何らかの。","voiceIndex":86,"id":"exchange-038"},{"speaker":"渡部委員","kind":"質問","question":"私は文化スポーツ振興費の中から幾つか質問をします。限られた区有施設を利用して、数多くの団体が活動しているわけですが、今回ここの予算書で出てきているいわゆる地域スポーツというものは、漠然としているんですが、この地域スポーツの定義といいますか、この地域スポーツとはどういった意味で地域スポーツという言葉を使われているのかというようなところをまず初めに教えてください。","respondent":"堀越生涯学習課長","answer":"地域スポーツの定義ですが、感じ方はいろいろおありになるかと思いますが、私どもの考え方といたしましては、まず基本的に、地域で、身近なところでスポーツを楽しむと。","voiceIndex":89,"id":"exchange-039"},{"speaker":"渡部委員","kind":"質問","question":"真ん中辺にあります地域スポーツ推進経費のいわゆる学校施設というものと、下のほうにあります学校開放運営費というものがそれぞれ１億何千万円ずつか計上されているんですが、これのいわゆる違いの考え方、およびやはりこの地域スポーツ推進経費の中にあります民間事業所で８万４,０００円なんですが、民間事業所とあるこの民間事業所というのは何なのかというのを教えてください。","respondent":"堀越生涯学習課長","answer":"名称につきましては、先ほど区民課長から答弁がありました文化芸術・スポーツ振興ビジョン、そのようないろいろな新しい取り組みもありますので、その中で地域の方のご意見を伺いながら、またそれも検討の要素として加えていきたいというふうに考えております。","voiceIndex":91,"id":"exchange-040"},{"speaker":"渡部委員","kind":"質問・要望","question":"このような場合、例えばその活動団体というのが一つの学校の体育館なりグラウンドを借りていると思うんですが、例えば活動拠点が改修で長期間使えなくなってしまうとかといった場合の活動団体に対する事前の告知のタイミングですとか、例えばそれが使えなくなってしまった場合のほかの場所の紹介等、何か手段、方法があるのか、あわせていただきたいのと、あと学校施設のいわゆる考え方、温水プール等とか。","respondent":"堀越生涯学習課長","answer":"プールの部分ですが、学校の温水プールの部分につきましては、ランニングの経費につきましては教育委員会のほうで行いますが、地域の開放にかかわる部分ですね、いろんなプールの監視ですとか、受付の部分ですとか、そのような開放にかかる部分につきましては。","voiceIndex":93,"id":"exchange-041"},{"speaker":"渡部委員","kind":"質問","question":"数多くの方がいろいろ学校等を利用して地域の皆様でスポーツされています。最後に一つだけ教えてください。高齢者スポーツの普及という項目があります。どのような形で、どのような普及をされていくのでしょうか。","respondent":"堀越生涯学習課長","answer":"使えなくなった場合、校舎の利用が改築で利用ができない場合につきましては、スポレクの中、それから隣のスポレクの方のほうとも調整をしていただいて、地域の中で調整をしていただきながら使っていただくという形で今調整を進めていただいているところです。","voiceIndex":95,"id":"exchange-042"},{"speaker":"南委員","kind":"質問","question":"１５５ページの奨学金貸付事務についてと、１７７ページの八潮南小学校の区民活動交流施設整備について、この二つで質問します。奨学金のほうですけども、４０人分の在学資金と入学準備金ということで、そしてまた事務費として計上されていますけれども、貸し付けの状況をまず伺いたいと思います。","respondent":"小野区民課長、日下部企画財政課長","answer":"貸し付けの状況ですけれども、来年度については公立４０人、私立４０人の貸し付けを予算計上しておりますけれども、この５年ぐらいをとってみますと、平成１７年度公立の採用者が３２人、そして私立が３４人の計６６人。先に地域の意向でありますけれども、具体的には今基本設計の作業を進めておりますが、できるだけ早い段階で地元にまた改めて、今の検討状況をご報告して、一定の今の検討している中身につきまして、ご意見等があれば。","voiceIndex":98,"id":"exchange-043"},{"speaker":"南委員","kind":"質問・要望","question":"やっぱり、品川区にも２.７％相当がいるのかどうかということはあれですけども、おそらく全国調査ですから、同じような状況にあるんじゃないかなというふうに思うんですけども、やっぱりそういう子どもさんの実態に、学びたいけども学べない、やめざるを得ない、そういう実態があるのであれば、区がきちんと支える、そういうことを施策として持つべきだというふうに思うんですね。当然だと思うんですけど。","respondent":"小野区民課長、日下部企画財政課長","answer":"今、状況の中で非常に就職が難しいというふうな状況があって、そういう場合につきましては、分納というふうな形も相談の中できめ細かく受けておりますので、そういうところを相談していただいて。ですから、子どもさんからお年寄りまで、そういう幅白い区民の皆様方の幅広い交流の活動拠点ということを基本にして考えてあります。","voiceIndex":101,"id":"exchange-044"},{"speaker":"南委員","kind":"質問","question":"しかし、現実的にはそうじゃない方も、何人も、とりわけ今まで以上に出てきていると、そういう状況で、分納をするというふうな対応はしているということなんですけども、しかし現実的にどの程度そういう方がいらっしゃって、分納するということだっていつ就職できるかどうかわからないところがあって、１年後から返済が開始されるわけですから、その間にちゃんと立て直すことができればいいんですけども。","respondent":"小野区民課長","answer":"これは非常に細かく一人ひとりに対応して、その中でできる可能なところを返還していただくという地道な努力、取り組みの成果というふうに考えておりまして、そういうところも含めて返還についてはきちんと相談に乗ってきめ細かく対応してまいりたいというふうに考えております。","voiceIndex":104,"id":"exchange-045"},{"speaker":"南委員","kind":"質問・要望","question":"貸し付けだということだということでかなり強調されましたけど、確かに貸し付けを受ければ返済するというのは当たり前のことですけども、しかしとりわけ今日の経済状況というのは、１００年に一度の経済状況ということで、親権者も含めて大変な事態になっているわけですね。そして、十分な対策をとるべきだということを強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-046"},{"speaker":"渡辺委員","kind":"提案","question":"私のほうは、１６９ページ、少年少女スポーツ大会、近隣セキュリティシステム運営経費、１７１ページ、文化芸術・スポーツ活動支援事業、懸垂幕作成経費、この点で伺っていきます。当然背景には議会提案でありました条例の制定、そして長期基本計画、区民要望など、大きな流れがあった中での品川区の意欲のあらわれであると解釈しています。","respondent":"堀越生涯学習課長","answer":"そのほか、平塚小学校跡地の整備ですとか、そのようなこと、あわせまして、ソフト面でいきますと、文化芸術・スポーツ振興ビジョン、これらを予定しておりまして、これらのいろいろな施策を取り混ぜながら総合的に進めていくという、そういうような考え方です。","voiceIndex":109,"id":"exchange-047"},{"speaker":"渡辺委員","kind":"提案","question":"いろんな要望が本当に多数あると思いますが、まず施設等の環境の整備というのが条例の中でも区の責務としてうたわれております。そういった中で、中長期的に公有地の取得への決意といいますか、これは本当に今すぐというわけではないんですが、絶えず意識をしていただきたいなという要望も踏まえた形で決意を伺えればと思います。多様をきわめる中、こだわりを何点か現在おありでしたら教えていただきたい。","respondent":"小野区民課長","answer":"こういう方たちとふだん私どもの広い区民の方が行っている活動、こういうものをどういうふうに結びつけて今後事業として展開をしていくのか、こういうことが今後の文化・スポーツの振興ビジョンの中では、一つの検討の課題になっていくだろうというふうに考えているところです。","voiceIndex":111,"id":"exchange-048"},{"speaker":"渡辺委員","kind":"提案","question":"小中学生がよくひざが痛いとかということをよく言います。でも、スポーツドクターやトレーナーの知識・見解からすると、ここまではできるということで、心にもストレスを与えない、こういったことで常時は難しくとも、部分的に活用できる、そんな方策を品川区のほうで把握されている、あるいはこれから部分的にも導入できたらという提案も含めて見解を伺いたいと思います。","respondent":"堀越生涯学習課長","answer":"今委員のほうからご紹介がありましたように、少年少女のスポーツ大会においても、そのような形で体のケアをしてくれる方々がいらっしゃるということですので、スポーツ振興において、いろいろなビジョンの中でも顕彰制度等もこれから検討してまいりますので。","voiceIndex":113,"id":"exchange-049"},{"speaker":"渡辺委員","kind":"質問","question":"導入後、効果検証はさまざまに行われているかと思います。私たちも地域レベルでもさまざまに聞きますし、そういった中で、他区の、２３区をはじめ、他区あるいは各自治体の問い合わせ等が結構あるのかなということと、逆に言えば、紹介や普及を品川区がリードしていってもいいのかなと思いますので、その点をお伺いしたいのが一つと、児童が常に持ち歩く、消耗品であるという点があると思います。","respondent":"高濱生活安全担当課長","answer":"今年度東京都でＩＴＣを使った子どもの見守りサービスというものの調査研究を始めまして、来年度には実証研究に入る予定であるということです。その例としてうちのほうを好事例として挙げていただいたということも聞いております。","voiceIndex":115,"id":"exchange-050"},{"speaker":"武内委員","kind":"質問","question":"私は３点、１４９ページの情報システム運営費、１６１ページの品川区サイン基本計画策定、１６９ページの訪問ボランティア事業経費について伺います。","respondent":"原情報システム課長","answer":"現在のところ、防災課のほうで緊急通報といいますか、緊急時の連絡システム、それから災害の要支援者、そういった形での管理、こういったものを実施しています。お尋ねの被災者の関係のシステムですけれど、現段階のところでは、作成までは至ってございません。","voiceIndex":118,"id":"exchange-051"},{"speaker":"武内委員","kind":"質問","question":"今課長がおっしゃっていただいたのは、私、今これから言おうと思っていたんですが、総務省のほうから１月１７日、阪神・淡路大震災が起きたこの日に、わざわざ合わせてということだと思うんですが、各都道府県、また各区市町村の情報政策担当課の方あてに、西宮市のほうで阪神・淡路大震災で得た経験をもとに被災者支援システムというものを作成して。","respondent":"原情報システム課長、中山防災課長","answer":"先ほど浅野委員からも出ました地域地方自治情報センター、そちらのほうにこのシステムのほうは登録しておりまして、これは全国の自治体に無償で配付するという仕組みになってありますので、私どものほうにつきましても。今のお話、「被災者支援システムVer２.００」ですか、のお話だと思うんですけれども、先ほどお話がありましたように、私どもで避難所に持っているシステムというのは、避難者のリストをただ入力して。","voiceIndex":120,"id":"exchange-052"},{"speaker":"武内委員","kind":"質問・要望","question":"これは要望します。続いて、１６１ページの品川区サイン基本計画策定ですが、これについての策定に当たっての経緯と、また主な内容について教えてください。","respondent":"中川原広報広聴課長","answer":"この間、このサイン計画がつくられましてから２０年近く経過しておりますので、このときには駅前拠点サインから目的の建物までを案内しようという形でやってきたんですけれども、この間、観光、国際化、景観、ユニバーサルというような視点が案内の中に加わってまいりましたので。","voiceIndex":123,"id":"exchange-053"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、この策定に当たっての、どういった方々で、例えば策定委員会等をつくられるかもしれないんですけど、どういった方々でつくられるかということと、あと去年の３月にできましたこのすべての人にやさしいまちづくり推進計画と、こういったものがあるんですけども、こことの整合性、また都や区の考え方との整合性も図りながらと思うんですけど、その辺の。","respondent":"中川原広報広聴課長","answer":"すべてこのサイン基本計画で統合するというわけではなくて、区として統一的に一緒に考えられる部分と、個々の計画が固有で引っ張っていく部分と考え分けをして、品川区としての一定の基本的な考え方をまとめようというふうな形で進めております。","voiceIndex":125,"id":"exchange-054"},{"speaker":"武内委員","kind":"質問","question":"すみません、策定委員会の主な構成メンバーを教えてください。","respondent":"中川原広報広聴課長","answer":"失礼いたしました。まちづくり関係の所管の道路公園課とか、そういったまちづくり関係の所管と、産業振興課、それから高齢福祉課、それから戸籍住民課と広報広聴課が事務局でやっております。","voiceIndex":127,"id":"exchange-055"},{"speaker":"武内委員","kind":"質問・要望","question":"はい、わかりました。最後の質問については、ちょっと時間がなくなりましたので、またどこかでやらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-056"},{"speaker":"本間委員","kind":"質問・要望","question":"私の場合には、１５１ページから１５３ページにかけて国際交流推進事業の件で、それから１６１ページの区民相談経費、１６５ページ、１６７ページ、地域力支援事業に関係して、１６７ページ、１６９ページの青少年教育事業にわたる点で質問していきたいというふうに思います。しかし、ここを取り上げて力を入れていくというようなことですので、具体的な内容があれば教えていただきたい。その割合も出ました。","respondent":"伊勢総務課長、中川原広報広聴課長、中山地域活動課長、堀越生涯学習課長","answer":"基本的には区民の方あるいは区内産業の方々と交流が大変活発になっておりまして、その辺も背景にこれから調査を委託して進めていきたいと。法律相談に限ってお答えをいたしますと、私ども区民相談でも事前に相談をお受けして、課題を整理して法律相談につなげるようにしておりますが。そのほかに掲示板助成であるとか、さまざま助成を行っているところに加えて。その代替地といたしまして、八潮三丁目にあります都立みなとが丘ふ頭公園、こちらのほうのうち一部を管理許可という形で使用の許可を受けまして。","voiceIndex":131,"id":"exchange-057"},{"speaker":"本間委員","kind":"質問・要望","question":"しかし、どうも納得できない、じゃあまた行きなさいとこちらは言うわけです。地域振興の関係はわかりました。それから、青少年対策費の中のキャンプ場整備というふうに書いてあったものですから、ちょっと私どものほうで理事者のほうとのやりとりが少しすれ違いの部分が出てくるかもわかりませんけれども、例えば大井ふ頭のみなとが丘ふ頭公園というふうなことでございましたね。","respondent":"堀越生涯学習課長","answer":"それと、整備の内容ですが、キャンプ、テントを張ってキャンプを行っていただくということを予定しておりまして、それに伴うものといたしましては、炊事場ですとか、そういった倉庫、電気設備等を予定しておりまして、炊事場については１カ所。","voiceIndex":136,"id":"exchange-058"},{"speaker":"本間委員","kind":"意見","question":"雨天の場合のバーベキュー広場みたいなことを考えているかどうかを最後に一言お願いしたいと思います。それからもう一つ、騒音について、城南島の部分では、大変騒音が激しくて大変なことがありますが、その辺、さらっとお願いします。","respondent":"堀越生涯学習課長","answer":"それと、設備についてですが、都立公園の一部を使用するですので、できるだけ最小限の設備でという都のご意向もありますので、そういった点を踏まえて今調整を進めているところです。","voiceIndex":138,"id":"exchange-059"},{"speaker":"本間委員","kind":"意見","question":"羽田空港の沖合移転の関係で、かなり内陸部での騒音が最近はあまり騒がれることがないようでございましたが、特に城南島のあの付近はかなり騒音がありますので、その辺は最近の状況は刻々と変わってきているかと思いますが、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":140,"id":"exchange-060"},{"speaker":"藤原委員","kind":"質問","question":"今年の２月に品川区プレス発表資料というのを出されましたよね。２点お伺いしますが、多分課長も担当課長ですから読んだと思いますが、こういう記事について、どういうふうに思うのかと、書かれているように検証ですね、どういう成果の検証ができるかということなので、私もだれかに聞かれたときにちゃんと反論したいと思っていますので、どういう形で投資対効果というのを検証していくのか教えてください。","respondent":"小野区民課長","answer":"それで、この結婚サポート事業ですけれども、基本的にやはり結婚という問題は個人の問題であるというのは、そのとおりだろうなというふうに思うわけですけれども、しかし、以前の地域社会を考えてみますと、結婚。","voiceIndex":142,"id":"exchange-061"},{"speaker":"藤原委員","kind":"質問","question":"事業目的が少子化対策ですよね。３組が結婚したなら別ですけど、結婚を前提につき合っているというだけですよね。１００年に一度の不景気、こういうときに、やっぱり行政というのはやることというのがあるんじゃないかとすごく私は思うんですけれども、その辺についてはいかがでしょうか。","respondent":"小野区民課長","answer":"そういう点では、やはりこれは行政がそういうものをやるということでできたことであり、民間の中ではなかなかそういう地域につながりのある方たちを会わせるということは難しいことで、これはまた一つ行政がやる意味があるのかなというふうに考えているところです。","voiceIndex":144,"id":"exchange-062"},{"speaker":"藤原委員","kind":"質問","question":"やる意味があるのかなという思いがありつつ、担当していく課長も大変だと思うんですけれども、ちょっとその辺も、私はこの事業をずっと追っていきたいと思いますので、追っていきます。他区に比べて特筆するところがあると思うんですけれども、やはりこの２年間、いろんな不安や成果があったと思うんですが、その辺について１分しか残っていないですが、お二人のご意見を伺いたい。","respondent":"高濱生活安全担当課長、斉藤防災安全担当課長","answer":"どこの行政もまねができないようなシステムを運営しているということ自体がすごくびっくりしました。これは本当に警視庁の中でもみんながうらやましがっています、どこの人たちもですね。今回１期目だということなんで、私が初めてなんで、いろいろ遠慮する部分はあったんですけども、次から続く人に対していろんな形でこうやったらいいと、いろんな形でアドバイスをできたらというふうに考えております。","voiceIndex":146,"id":"exchange-063"},{"speaker":"大沢委員","kind":"質問","question":"私は、１５３ページ、地域と在住外国人との交流促進、そして１６５ページ、区政アドバイザー会議、２０３ページ、国勢調査調査区設定ということです。順を追って質問します。地域と在住外国人との交流促進ということで、長期基本計画にもありますように、外国人が住みやすい環境の整備というふうにうたわれておりますけれども、具体的にはどのようなことをイメージされているのか教えてください。","respondent":"伊勢総務課長","answer":"地域と在住外国人との交流促進ですけども、基本的に先ほどもちょっと申し上げましたけども、区内の大使館の方々との懇談あるいは国際友好協会でもいろんな方々が来ているわけですけれども、その辺のアドバイスもいただきながら、こういう懇談を通じていろんな情報を聞いて。","voiceIndex":150,"id":"exchange-064"},{"speaker":"大沢委員","kind":"質問","question":"大使館の方たちとの会議を通じてこの青写真をつくっていくという今お話を伺いましたけれども、ただ、この話が出る上において、あらかじめ行政のスタンスというものがあるはずだと思うんですが、そこら辺はお聞かせできますでしょうか。","respondent":"伊勢総務課長","answer":"外国人との関係ですけども、基本的には今いらっしゃる外国人の方が日本の社会に溶け込むような、例えばいろんな決まり事、ごみ出しの問題だとかいろいろあると思いますけども、その辺のことのあつれきがあったり、いろいろあると思いますけども。","voiceIndex":152,"id":"exchange-065"},{"speaker":"大沢委員","kind":"質問・要望","question":"地域の参加ということでお話をいただきましたけれども、地域の参加の促進ということで、実際に持続可能な地域参加を実現するためにどのような事業、これも周りの人たちの意見を聞いて、それを集約して、スタンスを、結果、あらかたの流れを出すという以前にやはり区のスタンスというか、区のそれに対する基本的な考え方があると思うんですけれども、そこをお持ちでしたら教えていただきたいと思います。","respondent":"伊勢総務課長","answer":"基本的に日本人と同じようなという形で、例えば地域への参加ということに着目しますと、予算では出てくるかどうかあれですけど、例えば防災訓練で外国人の方への参加の呼びかけだとか、あるいは区民祭りへの働きかけ、それぞれ所管が違いますけども、こういうものを通じて。","voiceIndex":154,"id":"exchange-066"},{"speaker":"大沢委員","kind":"質問・要望","question":"さまざま地域参加ということで今、それに対する環境の整備と、また事業がこれからいろんな会議体を通じて、それを聴取して行われていくということですけれども、地域への参加、またこの区政への参加ということで話も表現が出ておりますけれども、区政への参加、これの意味するところはどのような意味なのか教えていただきたいと思います。","respondent":"伊勢総務課長","answer":"外国人の参政権等々の問題がありますけれども、ここで考えているのは、そういう制度的なものじゃなくて、あくまでも今お住みになっている外国人の方と地域との関係、こういうのをどうしたらいいかです。","voiceIndex":156,"id":"exchange-067"},{"speaker":"大沢委員","kind":"質問・要望","question":"今の区政という部分で、広い意味での地域の行事に参加をするということで、単語が意味する区にまつわる政、政治に関与をするという意味合いではないということは１回確認をさせていただきたいんですけど、いかがでしょうか。","respondent":"伊勢総務課長","answer":"ここで述べるのがどうかわかりませんけど、基本的には外国人との交流に関しては、そういうことじゃない形で身近な地域との交流、こういうことで予算化したものです。","voiceIndex":158,"id":"exchange-068"},{"speaker":"大沢委員","kind":"質問・要望","question":"１６５ページ、区政アドバイザー会議に移ります。この区政アドバイザー会議、この会議体を設立した目的と意義について教えていただきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"区政アドバイザー会議の意義と目的ですけれども、区民の期待にこたえる先駆性のある区政経営を推進するために区長の政策形成を支援するために区政アドバイザー会議を設置いたしまして、さまざまな分野の方から意見を求めるものです。","voiceIndex":160,"id":"exchange-069"},{"speaker":"大沢委員","kind":"質問・要望","question":"さまざまな方からの意見の聴取ということですが、この存在意義は十分にあるということを認識のもとに、例えば区長が例年行っていらっしゃいますタウンミーティング、また区政協力委員という制度もあります。そこらとの兼ね合いといいますか、同じような内容の会議体なのか、それとも位置づけとして違うものなのか、そこがありましたら教えていただきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"具体的には、自治体経営の基本的方向および重要施策に関する事項や各分野の総合的な計画、また民間企業等で培ってまいりました経験やノウハウなどをお聞きしながら、それらを先駆的な区政運営ができますように反映していきたいというふうに考えて設置しているものです。","voiceIndex":162,"id":"exchange-070"},{"speaker":"大沢委員","kind":"質問","question":"幅広く区民の方の意見を聴取し、また区政アドバイザー会議においてそれの集約を絞り込み、論点は何なのか、目的は何なのかということで、わかりますが、さて、専門性を持った方ということでありますけれども、その他もろもろの政策形成の中で、その他もろもろの専門性を持った知識、確かに要ると思いますが、会議の必要性でしょうか、今おっしゃっておりました別次元でということですけれども、この必要性。","respondent":"濱野区長","answer":"今月も予定しております。これは人材育成についてアドバイスを、それぞれの経験をお聞きするわけであります。","voiceIndex":164,"id":"exchange-071"},{"speaker":"大沢委員","kind":"質問・要望","question":"それがまさに国勢調査が今行われている、行う人と行われる側の今の状態だと思うんですけれども、前回そんなような話も予算特別委員会、決算特別委員会の中で出たと思うんですが、その点について、その後区はこれから行うわけですけれども、区はどのような対策が練られているのか、進捗状況といいますか、練られて、具体的なお話がありましたら、ご披露していただきたいと思います。","respondent":"小野区民課長","answer":"もう一つは、郵送の提出という方法です。三つ目がオンラインによる回答ということですけれども、前回の国勢調査のときには、調査員が調査票をもらったときに、内容点検というのをしております。今度の平成２２年度の国勢調査からは、調査員は一切そういう内容の点検は行わない。","voiceIndex":166,"id":"exchange-072"},{"speaker":"大沢委員","kind":"質問・要望","question":"この国勢調査の問題については、今二つ私お話をさせていただきました。調査員の方は非常にご苦労されていると思いますので、そこらの部分の十分また徹底した調査員の方に今３点お話をいただきました、調査票を渡す、郵送で提出、オンラインによる回答ということで、そこのところを調査員の方に十分な周知と指導のほうをお願いしたいと思います。要望して質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":168,"id":"exchange-073"},{"speaker":"市川委員","kind":"質問・要望","question":"結婚サポート事業についてですけれども、これは午前中と先ほどもいろいろご答弁いただきまして、大体事業の内容とか、それから現状とか、それと目的というところもお話をいただいたんですけれども、事業を始める前にリサーチはされたかと思うんですけれども、大体品川区内に民間の結婚サポート事業者というのがどれぐらいあるのかということを教えていただきたいというのと。","respondent":"小野区民課長","answer":"先ほども結婚というのは非常に個人の問題であるということで、そういう点からいくと、何組というふうな目標は当然立てられないわけですけれども、やはり私どものほうとしては、セミナーをやり。","voiceIndex":170,"id":"exchange-074"},{"speaker":"市川委員","kind":"質問・要望","question":"それで、長期的に見て、若者支援をどんなふうに取り組んでいこうとされているのか、今年度の予算全体を見ても、どこがどういうそういう若者支援になっているのかというのがわからないのでお聞きするんですが、どんなことが予算の中に盛り込まれているのか、アバウトで結構ですのでちょっと教えていただきたいと思います。","respondent":"日下部企画財政課長、小野区民課長","answer":"長期的な若者支援ですが、区のほうとしまして、予算的な計上も含めまして取り組みをしておりますのは、基本的に若者支援ということでまいりますと、具体的には青少年教育でありますとか、青少年に対する育成というような。結婚の支援、いろいろな経済的な問題というものはありますでしょうけれども、現実に結婚したいというふうに思っている方がなかなか出会いがなくてできないんだと、そういう調査結果が、非常に大きい数字の割合がありますので。","voiceIndex":172,"id":"exchange-075"},{"speaker":"市川委員","kind":"提案","question":"結果がなかなか若者支援とか、なかなか出ないことかもしれませんけれども、やっぱり若い方をきちんと支えていくという、そういう公のやる事業というところにぜひ立っていただきたいということを要望しておきます。２００５年の予算特別委員会で学校避難所連絡会はすべての学校で開催するように提案をさせていただいたんですけれども、まず開催の現状が今どうなっているのか伺います。","respondent":"中山防災課長","answer":"理想は今全部で５４校ですか、すべての学校で避難所連絡会議が行われればいいんですが、実態といたしましては、平成２０年度におきまして、これは３月１０日現在ですけれども、学校にいたしますと２４校で開催しているのみです。","voiceIndex":175,"id":"exchange-076"},{"speaker":"市川委員","kind":"質問・要望","question":"大崎地区でも、相当な人口増が今後見込まれますので、芳水小学校だけではなかなか対応できないというところも懸念されるんですけれども、抜本的に避難所というものを変えていく必要があるんじゃないかというふうに思っているんですけれども、その辺はどうでしょうか。スケジュールのようなものがもし考えられているんだったら教えていただきたいなと思います。","respondent":"中山防災課長、宮地区民生活事業部長","answer":"今後の学校避難所会議の方向性ですけれども、当然のことながら啓発に努めまして、全校でやらなければ意味のないことですので、全校でできるように努めてまいりたいと思ってあります。今後も積極的に地域のそういった訓練の場所となるように、学校が形を変えたといたしましても、地域単位で実施していくように努めてまいります。","voiceIndex":177,"id":"exchange-077"},{"speaker":"市川委員","kind":"質問・要望","question":"避難所のことをお聞きしたんで、訓練のことではなかったんですけれども、避難所についてはいつ災害が起きるかわかりませんので、とても区民の皆様もここの学校に避難してくださいといわれた学校がなくなれば、当然どうするんだろうという不安もわかりますので、ぜひこの辺のところは至急対応して、スケジュールのようなものを区民の方には早くお出ししていただきたいなというふうに思います。","respondent":"中山防災課長","answer":"今ご指摘のとおり、これから建て替えだとか何だとかというときに、逐次避難所は、皆さんの地域の避難所はこちらだと、この学校だということは周知してまいりたいと思ってあります。","voiceIndex":180,"id":"exchange-078"},{"speaker":"市川委員","kind":"質問","question":"そのように対応をお願いいたします。次ですが、防災センター等運営で、普及啓発に関連しても伺います。防災センターの品川シアターなんですけれども、年間１万５,０００人ぐらいの利用者があるということですけれども、利用目標をどう設定しているのか伺います。この目標に対して、この利用というところではどんなふうに考えていらっしゃるのか伺います。","respondent":"中山防災課長","answer":"今年度も昼間だけではなくて、在住外国人の方、お勤めの方がいらっしゃいますので、５月２６日に予定していますけれども、夜間に起震車訓練等々も行ってまいりたいという状況です。","voiceIndex":182,"id":"exchange-079"},{"speaker":"市川委員","kind":"質問","question":"目標のことを伺ったんですけれども、後でまた目標をどう設定しているのか教えてください。それで、３本の映画がかかっているというふうに調べてみたんですけれども、私もそのうちの１本の「希望（のぞみ）」というものを見せていただいたんですけれども、この映画というのは何年間ぐらいで映画を変えているのか。映画の変更はだれが権限を持っているのか、ちょっとその辺を伺います。","respondent":"中山防災課長","answer":"それから先ほど答弁漏れがございましたけれども、入場者数の目標値ですけれども、定員が４０名ですので、これが２８０日ぐらいあいているはずですから、ぜひ掛けた答えぐらいの数を目標値に置きたいと思ってあります。あくまでも目標値です。","voiceIndex":184,"id":"exchange-080"},{"speaker":"市川委員","kind":"質問","question":"次に世帯ごとに配布されました「わが家の防災ハンドブック」についてなんですけれども、この啓発本をその後どのように啓発に活用していかれようとされているのか伺います。","respondent":"中山防災課長","answer":"ですから、これじゃあいかんということで、私どもワークショップ、それから先ほどもありましたが避難所会議、このような機会をとらえて、簡単に内容をまとめてあるものですし、地区ごとに分けてありますし、大変読みやすいものですので。","voiceIndex":186,"id":"exchange-081"},{"speaker":"市川委員","kind":"質問・要望","question":"外国人の方たちに別紙で冊子がつくられているのかどうかわからないんですけれども、日本語と併記して、英字とか中国語で記載しても日常的にこういう方たちも品川にはいて、震災に遭われたら一緒に助け合いをしなきゃならないというところでは、日常的なコミュニケーションにもなると思いますので、意見ですが、こういった方たちのハンドブックを今後つくられたらいかがかなというところで、これについては。","respondent":"中山防災課長、中川原広報広聴課長","answer":"広報からのフォローもあるかと思いますけども、私どももぜひ最低４カ国語ぐらいのものをつくってまいりたいと思ってあります。予算がつけばの話ですけれども。先ほどのハンドブックも、ＣＡＴＶの２分間番組をつくりまして、随時ＣＡＴＶの番組の中に挟み込んで周知を、リアリティーを持った内容としてお届けしています。","voiceIndex":188,"id":"exchange-082"},{"speaker":"若林委員","kind":"質問・要望","question":"３点まとめて伺います。それとともにプラネタリウム、新しいプラネタリウムができますので、これは文化センターのほうで１４億８,０００万円というふうに計上されておりますが、この中に本体の金額が入っていると思いますけれども、ここら辺の金額をまず教えていただきたいと思います。","respondent":"阿部経理課長、小野区民課長、堀越生涯学習課長","answer":"１点目の庁内サインの件ですけれども、今４月１日に備えまして、当面は今ありますエレベーターの中。芸術祭をどういうふうにやっていくかということにつきましては、今年度、平成２１年度に検討。","voiceIndex":192,"id":"exchange-083"},{"speaker":"若林委員","kind":"質問・要望","question":"ある意味でこだわれば、もっともっと工夫する余地が私はあるんじゃないかというふうに思っていますので、これは要望だけにします。そこの芸術祭という名称のとらえ方だけ一つ確認をさせていただきたいと思います。文化センターのほうは、一つはいわゆる来訪者、区民とともに来訪者、来外者の方へのサービス、ここら辺の一つ考え方をお聞きしておきたいというふうに思います。","respondent":"小野区民課長、堀越生涯学習課長","answer":"その中にも文化人といわれる、芸術家といわれる方は実際に演じたり、作品をつくったりする方ですが、そういうふうな形ではなくてもさまざまな見識をお持ちの方にもご意見をいただきながらつくってまいりたいというふうに考えております。ボランティアの方々にも、今現在改築前の部分でご協力をいただいた部分もありますので、そういった面をあわせて委員のご提案の趣旨も入れた形で検討を進めていきたいというふうに考えております。","voiceIndex":196,"id":"exchange-084"},{"speaker":"阿部委員","kind":"質問","question":"そうすると、中身と金額の適正さというのを、どの段階で見ていけばいいのか、このまま予算を通しちゃって、あと５億円好きに使ってくださいねということなのか、その辺のお考えをお伺いしたいと思います。宿泊の実買価格というのが大幅に下落してきていると感じておりますけれども、この各施設との契約の金額、それから自己負担分の単価、この見直しについては検討されたかどうか教えてください。","respondent":"久保田行財政改革担当課長、小野区民課長、堀越生涯学習課長、日下部企画財政課長","answer":"そうした中で、オリンピックの精神を通してというところでオリンピックムーブメント事業を推進していくといった中では。借り上げの保養所施設の関係ですけれども、こちらのほうの利用単価ということですけれども。したがいまして、社会教育の部分につきましては、教育委員会からの補助執行というような形で整理をされるという形になると思いますが。既存の学校の建物、しかもご案内のように八潮の南小学校、南中学校はともに築２５年なんですね。","voiceIndex":200,"id":"exchange-085"},{"speaker":"阿部委員","kind":"質問・要望","question":"オリンピックムーブメントの件なんですけど、パラリンピックについては含むということだったんですけれども、スペシャルオリンピックスについてはいかがでしょうか、再度ご答弁をお願いいたします。先ほどインターネットを見ましたら、例えば三つの施設のうちのニューアカオなどを見ますと、品川から電車代込み、往復の特急料金込みで１万２,０００円ぐらいで出ているんですね。ご解説をお願いいたします。","respondent":"久保田行財政改革担当課長、小野区民課長、堀越生涯学習課長、日下部企画財政課長","answer":"オリンピックの精神は、「スポーツを通しまして、心身を向上させ、さらには文化、国籍などさまざまな差異を超えまして。この内容ですけれども、一つはコンサートの充実ということで１,４００万円ほど増やしているのと、それから文化振興事業費ということで。今までも進めてきておりましたいろいろな機会提供ですとか、そういった部分をさらに進めて情報提供。具体的なものは今詰めている最中ですが、そういったことでコンセプト、それから中身、セットでこれから進めていくということで十分ではないかと。","voiceIndex":205,"id":"exchange-086"},{"speaker":"本多委員","kind":"質問","question":"１５９ページのＣＡＴＶ事業、１７５ページの大崎第二地域センター移転経費について質問します。区民チャンネルなどで、南東京ケーブルテレビがつくるものと、品川区がつくるものとさまざまあると思いますけれども、平成２１年度の取り組みについて、基本的なところを教えてください。","respondent":"中川原広報広聴課長","answer":"私のほうからＣＡＴＶの区民チャンネルの番組についてお答えいたします。品川区は区広報番組としまして、毎週、１週間に起こった出来事とお知らせを中心としまして、あと特別番組というのをつくっております。特別番組は「こんにちは！","voiceIndex":211,"id":"exchange-087"},{"speaker":"本多委員","kind":"質問","question":"特番の内容によっては保存版でＤＶＤ等をつくられるケースがあると思うんですが、これは当然受益者負担というか、買う方が全額負担でいいと思うんですけれども、そういうＤＶＤを保存して残す定着についてどうなのか、その辺を教えてください。","respondent":"中川原広報広聴課長","answer":"お尋ねのＤＶＤとか残す場合ですけれども、ビデオオンデマンドとして区民の方にいつでも見たいときに見ていただけるために残す場合と、町場の方が自分たちが出た記念にとっておきたいという２種類があります。","voiceIndex":213,"id":"exchange-088"},{"speaker":"本多委員","kind":"質問・要望","question":"ちょっと一つの事例を挙げますが、ほんの例なんですけれども、品川区のねむの木に深くご縁のある皇族の美智子様が、天皇・皇后両陛下が今年ご結婚５０周年を迎えるということで、品川区内からの一部なんですけれども、盛大に品川らしさを盛り込んだイベントでお祝いをしようじゃないかという気運が一部であるんですけれども、そういったものが今後そういうイベントとして実現に向けたときとか。","respondent":"中川原広報広聴課長","answer":"先ほどの美智子皇后の５０周年等々、町場の方にとってもめったにない機会については、早目にご相談いただきまして、どんなお話をお持ちなのか、資料なんかはどういうものをお持ちなのかによりまして、番組の盛り上げ方も違ってきますので。","voiceIndex":215,"id":"exchange-089"},{"speaker":"本多委員","kind":"質問・要望","question":"それで、ちょっと次の１７５ページの大崎第二地域センターのほうを聞いていきますが、まずこの内容について移転ということをどういう引っ越しの仕方とかをされるのかなと素朴な質問なんですけれども、これからいろんな区の施設で移転というケースがたびたびあると思いますが、学校もそうかもしれませんし、そういった部分の移転の仕方という、ケース・バイ・ケースかもしれませんが。","respondent":"中山地域活動課長","answer":"大崎第二地域センターの移転ですけれども、冒頭に説明があったように、大崎中地区の再開発に伴う地域貢献のスペースとして事業者から提供されるスペースに大崎第二地域センターが移転するわけです。本年１０月中の移転を予定しているおるところです。","voiceIndex":217,"id":"exchange-090"},{"speaker":"本多委員","kind":"質問","question":"ケース・バイ・ケースなので、ほかのはちょっとあれでしたらまたいいんで、もしあれば後で。それで、地域センターの跡利用は行財政改革特別委員会でやっていることですので聞きませんが、跡利用が決まるまでの暫定期間があるわけですよね。地域センターが移転後、１０月に移転をして、跡利用が何になるかまでは暫定期間は管理はどこでされるのか、そこだけ教えてください。","respondent":"久保田行財政改革担当課長","answer":"跡利用につきましても、今後引き続き有効な活用を考えていきたいというふうに考えているところです。","voiceIndex":219,"id":"exchange-091"},{"speaker":"高橋委員","kind":"質問・要望","question":"１６０ページの財政管理費、１６１ページの品川区サイン基本計画策定、１６３ページ、区施設中長期改修計画策定、１７１ページの歩行喫煙防止推進経費。ちょっと順番はあれになってしまうんですが、まず１６１ページの品川区サイン基本計画策定で、これは質問を多くの方がされたんですが、一つだけ確認させていただきたい。これは庁舎内のことも入るのでしょうか。","respondent":"中川原広報広聴課長","answer":"今回のサイン基本計画は、ご案内の仕組みづくりということで、お客様が思い立って出かける、インターネットで地図を印刷して、そこからまちへ出て、駅に着いて、駅からその建物まで、庁舎に着きましたら、総合案内から目的のところまでということを想定しまして。","voiceIndex":222,"id":"exchange-092"},{"speaker":"高橋委員","kind":"質問","question":"そういった掲示ができると区民の方が見やすいと思います。駅前ではあまりないんですが、やはりちょっと外れたところだとか、ちょっと駅から離れたところであるんですが、エリアが決まっているんですが、それ以外のところ、あるいは境目のような私道は今後どのような形で進めていっていただけるのでしょうか。","respondent":"高濱生活安全担当課長","answer":"エリア内については、指導員を配置して指導しています。エリア外につきましても、いろんなうちの生活安全パトロール隊のテープを使った広報などで周知させていきたいと考えております。","voiceIndex":224,"id":"exchange-093"},{"speaker":"高橋委員","kind":"質問","question":"その指導員の方はエリアから出てしまうと、なかなかその指導がやはりできないということになるんでしょうか。１本内側に入ったとか、そういうところでやはり喫煙されている方が多いんですが。","respondent":"高濱生活安全担当課長","answer":"エリア外については、歩行喫煙についてしないように努めてくださいといういき方ですので、直接指導するということではなくて、全体的なマナーアップの中で考えていきたいと考えております。","voiceIndex":226,"id":"exchange-094"},{"speaker":"高橋委員","kind":"質問・要望","question":"１６３ページの区施設中長期改修計画策定のところなんですが、公共施設のランニングコストということでお尋ねしたいのですが、ある自治体は庁舎を７８０億円かけて今後１０年で大改修をすると、これは建築費のほぼ２分の１ということで、維持管理の問題は建物については避けて通れないのですが、そこで行革の側面からも建設時に維持管理の問題を考慮すべきではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":228,"id":"exchange-095"},{"speaker":"高橋委員","kind":"質問","question":"そういったことで、施設を用途替えしたり、建て替えたりするときに、維持管理のコストを検討しながら設計をしているんでしょうか。具体的に、しているとすれば、どのような点からされているのか、そして、どうしても費用のかかることですので、１０年から２０年と長いスパンで、この改修計画とは違うのかもしれませんが、どのようなお考えなのでしょうか、お願いします。","respondent":"宍戸施設担当課長","answer":"新築物件につきましては、なるべく維持管理費を考えた上で設計はしております。","voiceIndex":230,"id":"exchange-096"},{"speaker":"高橋委員","kind":"質問・要望","question":"最後に、１６０ページの財政管理費というところですが、議案説明会のほうで配付された資料の性質別の内訳によると、投資的な経費、今年度予算は当初予算ですね、３０％ということになっているんですが、決算ベースになる年もあると思うんですが、平成１８年度から平成１９年度、平成２０年度と投資的経費は何パーセントだったんでしょうか。","respondent":"日下部企画財政課長","answer":"平成１７年度の決算から３カ年で申し上げますと、投資的経費につきましては、平成１７年度が構成比でまいりますと２０％、それから平成１８年度が２２.６％、平成１９年度が１４.７％と、そういう内訳です。","voiceIndex":232,"id":"exchange-097"},{"speaker":"高橋委員","kind":"質問","question":"平成２０年度は当初予算で２８.３％で、今回３０％ということなんですが、そもそも投資的経費というのは、どのような区別をしているのでしょうか、お願いします。","respondent":"日下部企画財政課長","answer":"投資的経費、ちょっととらえ方、幅がありますけれども、基本的には社会資本の整備ということでありまして、施設の建設、それから土地の取得、これが主なものです。","voiceIndex":234,"id":"exchange-098"},{"speaker":"高橋委員","kind":"質問","question":"とすると、数字上は当初予算ではそういった数字になっていますが、今年度といいますか、小中一貫関係あるいは大崎などがある程度進んできて、今後１０年の新しい品川をつくる投資的経費の大きな柱、それはインフラでも非インフラでもいいんですが、産業経済なんでしょうか、それとも教育なんでしょうか、それとも福祉費なんでしょうか、それとも五つの柱で全体的なところなのでしょうか。","respondent":"日下部企画財政課長","answer":"ただ、逆にそれが完了しますと、がくんとこれがまたその反動でマイナスになると、そういう増減を繰り返しているわけですが、例えば今後１０年間ということで見通してまいりますと、学校は以前から申し上げておりますように、耐震化から改築、一貫校、それから福祉の面では。","voiceIndex":236,"id":"exchange-099"},{"speaker":"安藤委員","kind":"質問・要望","question":"１７５ページの大崎第二地域センター移転経費と、何とか時間があれば１６９ページの地域食事サービス事業のほうもお伺いしたいと思います。「あらためて利用者やほかの利用している方々に区が説明するという考えでよろしいですか」と念を押した質問に対して、「はい、おっしゃるとおりです」と答えております。","respondent":"中山地域活動課長","answer":"それで、利用者の中から地域センターの所長に対して、今回の移転計画、議会に説明していこう、そういうお話が伝わる中で、具体的に聞きたいことがあるということで何回か申し出があり、それについて地域センターの所長のほうで地域団体の。","voiceIndex":240,"id":"exchange-100"},{"speaker":"安藤委員","kind":"質問","question":"今からでも１０月に移転ということでしたので、遅くないと思いますので、区の責任で利用者への説明会というのをしっかりと、どの団体が使っているかとかという情報もよくつかんでいると思いますので、そういった説明会、機会を開催すべきだと思うんですが、いかがでしょうか。","respondent":"中山地域活動課長","answer":"いろいろご質問のそういう説明の場面をということが具体的に利用者の中で出てきた場合については、これはまた通常の業務との関係の中で、そういうお声について基本的には聞いていく、あるいはお尋ねについてはきちんと説明していくというスタンスの中で対応していきたい。","voiceIndex":242,"id":"exchange-101"},{"speaker":"安藤委員","kind":"質問","question":"ご了解いただいているという話もありましたけども、やはり狭い範囲でしか、お話を聞いていない範囲ではそういうふうに判断されるかもしれませんが、さまざまな団体がこれまで使っているわけですから、まずきちっと利用者団体の皆さんに情報を提供して、声を聞いた上で了解しているかどうかという判断を初めてできるんじゃないかと思いますので、あらためて説明会を行うべきだと思いますし。","respondent":"中山地域活動課長","answer":"これからまた具体的な部屋の、先ほど申し上げたような料金の設定だとか、具体的な集会室の切り分けのルール等を固めていく中で、これについてはきちんと議会も含め、また利用者の方等々、現場での説明も含めてきちんと説明をしていきたい、このように考えております。","voiceIndex":244,"id":"exchange-102"},{"speaker":"安藤委員","kind":"質問","question":"今回の移転計画を見ますと、従来の５２２平米が６００平米になるというところは、増えるということでいいんですけど、あとエレベーターがつくというのはいいんですけども、部屋数は三つで変わらないんですね。それで初めて地域貢献だと、再開発は地域貢献になるというふうなことを区はよくおっしゃいますけども、最低限それは行うべきなんじゃないかなと思うんですよ。そちらの考えはいかがでしょうか。","respondent":"中山地域活動課長","answer":"この辺を含めてしっかりと細かい部分を決めてから、またこれについてはあらためて当該委員会にご説明申し上げたいと考えています。","voiceIndex":246,"id":"exchange-103"},{"speaker":"安藤委員","kind":"質問・要望","question":"ご質問したいのは、このサービスを受けている方、昼が１１４人、夜が５９人ということでご説明あったんですが、どういった生活実態、経済状況なのかということをつかんでいらっしゃったら教えていただきたいのと、あと大変な負担になると思いますので、値上げはやっぱりやめるべきだと思いますが、いかがでしょうか。","respondent":"中山地域活動課長","answer":"それで、委員会でも申し上げましたけれども、この間いろいろ事業の分析をしていく中で、昼で言うと７００円余、夕食で言うと１,０００円近くの単価になってきているという中で、やはり負担の割合が半分以下になっているというふうな状況を考えると。","voiceIndex":248,"id":"exchange-104"},{"speaker":"安藤委員","kind":"意見","question":"生活実態を把握していなかったということだったんですが、やはり値上げというのは軽々しくするべきことではないと思いますし、実際サービスを受けている方がどのような影響になるのかということを考えて行わないとだめだと思いますので、把握もしていなくて値上げというのはちょっと非常に余りに乱暴なやり方じゃないかと私は思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":250,"id":"exchange-105"},{"speaker":"山路委員","kind":"質問・要望","question":"私のほうからは、３点ほどお伺いします。その１点目が、１４８ページ、総務管理費の日曜開庁について。日曜開庁は、区長の英断で去年の１月からスタートし、マスコミでも取り上げられて大変話題になったわけですが、来庁者の推移はふだんの日に比べてどれぐらいのところまでいっているのかお伺いいたします。","respondent":"上川内戸籍住民課長、榎本人事課長、小野区民課長","answer":"日曜開庁ですが、平成１９年の１月から始まりました。それで、今現在、来客数としては２万４１５人、これが開始以来の来庁された人数です。さらにその病気休暇後の病気休職というさらに長期で休む方が、大体２０人強ということです。ただ、そのうち心の病の方が８割から９割という傾向です。この中で、いろいろ個々についてはご説明すると細かくなるんですが、例えば商業動態統計調査というふうなことになりますと。","voiceIndex":252,"id":"exchange-106"},{"speaker":"山路委員","kind":"質問","question":"日曜開庁につきましては、こういう時代を考えて、総合相談窓口、区長、副区長、教育長、理事者の部長、こういうものをすると、もっと区民の方がいろいろ現場で不安に感じていることが安心して推進できるんじゃないかと思いまして、今後考えてみたらどうかと思いますが、どのようにお考えでしょうか。３点目は、特に若い人の雇用問題において、農業というものに非常に志願者が増えている。","respondent":"久保田行財政改革担当課長、榎本人事課長、小野区民課長","answer":"効率的な区政運営という観点もありますので、現行の体制の中で連携の強化を図りながらよりよいサービスを提供していきたいというふうに考えております。若い方の農業就業の意向について、農林業センサスが役に立つかというご質問かと思いますけれども、農業の実態を調査するですので。","voiceIndex":256,"id":"exchange-107"},{"speaker":"山路委員","kind":"質問","question":"職員の健康について、ワークライフバランスと健康に関する調査、これは当然やっていらっしゃると思うんですが、この辺についてはどのように仕事に生かされているかお伺いいたします。","respondent":"榎本人事課長","answer":"主にワークライフバランスの関係からいきますと、超過勤務のほうの把握をしております。それで、時期的には繁忙期はありますけれども、それが連続して続かないような形での対応を産業医とともにその辺を図っているところです。","voiceIndex":260,"id":"exchange-108"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、これがまとまっているというところがあれば、例えば本庁舎のほうに来て、どこどこの地域センターのところの掲示板を使いたいのでという、もともと全区的にやるときには、本庁舎のほうに来ないといけませんので、そういうものを準備していただきたい。いかがでしょうか。特に机が非常に重いんです。これの内容、それから告知方法をどういうふうにされるのかお聞きしたいと思います。","respondent":"中山地域活動課長、中山防災課長","answer":"ただ、いろいろと動きがございまして、やはり現場のセンターのほうに確認してから掲示等をお願いするというふうな説明があるかもしれませんけども、所定の場所の把握については努めていきたいと考えています。アレルギー児用のミルク、ＭＡ－１ミルクのお話ですが、お褒めをいただきまして、ありがとうございました。来年度も当然ながら購入をしてまいります。","voiceIndex":263,"id":"exchange-109"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、ある程度大もとのところで、そういう資料提供とかをしていただければ、いろいろ計画的に、ここは必要ないかもしれないとかといろいろできると思うんですが、そういう地域活動課のところでどういう地域センターの情報を収集していくのかというところも含めてお答えをお願いしたいと思います。告知の方法です。ですから、その保護者向けに告知をしてあげないと、実際に使えないということになります。","respondent":"中山地域活動課長、中山防災課長","answer":"ただ、今回の一部移転等があったり、そういう特殊事情の中で順番が多少変わることもありますし、また一遍に全部をかえるのか、あるいは優先順位の高いところからやるとか、この辺はなるべくお声を踏まえ、実態を踏まえ。たしかアレルギー児の方がミルクを飲むのは３歳ぐらいまでだですので、小学校まではどうなのかなと思ってもありますけれども、それぞれアレルギー児童を抱えている保育園、幼稚園等には、保健所などとも連携しながら。","voiceIndex":266,"id":"exchange-110"},{"speaker":"西本委員","kind":"質問・要望","question":"アレルギーのほうですけれども、牛乳を飲めない子は小学校に入っても飲みますので、そういういろんな事情がありますので、各関係のところといろいろと機会があったら速やかに使えるような形をとっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":269,"id":"exchange-111"},{"speaker":"石田（秀）委員","kind":"質問","question":"サイン計画ですけれども、研修チームでまとめられた研修の部分が、大分具体化してきてよかったかなとも思っておりますけれども、これをもし先ほど来お話があって、大分わかってきましたけれども、もしやるんであれば、景観、もし観光ということを考えていくということであるならば、これには相当仕掛けをしていかないと、特に観光であるならば、こういうものを観光にしていこう。","respondent":"小野区民課長、宍戸施設担当課長、堀越生涯学習課長、中川原広報広聴課長","answer":"この中長期計画ですけれども、区有施設、築３０年以上の建物が４５％という状況の中で、劣化状況の調査をしながら計画修繕に活用したり。それで、その中でその他の部分についても一定のいろいろなお話というのはもちろんさせていただいているところですが。サイン計画につきましては、研修チームの成果も視野に置きながら検討する予定です。","voiceIndex":271,"id":"exchange-112"},{"speaker":"石田（秀）委員","kind":"提案","question":"だけれども、品川区でどういう提案をしていくんだ。そういうことを踏まえて、今後５年間でどう考えていますか。だけど、しようがない、５年間は続けるんですか。そういう考えをどこに踏まえてやっていらっしゃるんですかということを聞きたかった。だけど、内部的に区長がそこまで指示をして、ちゃんと内部がそういうことを判断して提案できるように内部的にもやっていくんですかということをお聞きしたい。","respondent":"小野区民課長、宍戸施設担当課長","answer":"今後どのような形でいくのかということにつきましては、ふれあい交流そのものがどういうふうになるのかという影響も出てまいりますので、その点につきましては慎重に検討してまいりたいというふうに考えております。次のステップとして、いろいろな組織体についても検討していきたいというふうに考えております。","voiceIndex":276,"id":"exchange-113"},{"speaker":"石田（秀）委員","kind":"意見","question":"山北町については、私は利用者がいらっしゃるから、余計いろいろな形で区の考え方をしていくべきだろうと思っています。じゃあ、事前に例えば畑に戻していきながら５年間を見据えて再契約をしないよというのを打ち出しておく。それで５年間を向かえてからやっていこうよとかしていかないと、なかなか相手があることだし、利用者もいる、それから向こうの自治体もいるわけでしょう、財産もあるわけでしょう。","respondent":"宮地区民生活事業部長","answer":"一つの節目だというふうに考えておりまして、やはり残る期間５年間を見据えて、今まさにその荏胡麻をまいたり、それからビワの種をまいたりとか、あらゆる方向を探りながら、一定のあいているスペースを使って、両方の町、それから区と協議をしているところです。","voiceIndex":279,"id":"exchange-114"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"それと、広報のあり方について区のお考えをお聞きしたいのですが、今さまざま議会から何か質問がある際には、ほとんどの委員から周知の徹底をしていただきたいというような要望を僕も出させていただいているんですが、広報のあり方についてどのような区のお考えがあるのか教えてください。よろしくお願いします。","respondent":"小野区民課長、中川原広報広聴課長、中山防災課長、伊勢危機管理室長","answer":"まだ１年目です。昨年９月に実施をいたしましたときには、定員４０名のところを６７名の希望者がございました。区内４０も駅がある区はありません。そこで、駅に広報スタンドを置きました。この事業所の地域協力といってもちょっと中身がわからないと思いますので目的をお話ししますけれども。３月末を目途に今真っ最中で作業をしているわけなんですけれども、この後、職員も４割程度欠勤するとかということもございましたり。","voiceIndex":282,"id":"exchange-115"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"結婚サポート事業の賛否はありますが、これだけのニーズがあるということで、ぜひ進めていただきたいと思います。広報のほうは、ぜひどこにどういった情報を届けるかをしっかりと見極めて今後も取り組んでいただければと思います。防災のほうはぜひ事業所との関係が必要になってくると思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":287,"id":"exchange-116"},{"speaker":"堺委員","kind":"提案","question":"私のほうから１７１ページの文化芸術・スポーツ振興ビジョン等策定経費、何人かの方からお話が出ておりましたけども、予定しておりましたのでダブる点が出てくるかもしれませんが、確認の意味でお話をさせていただきたいと思います。","respondent":"小野区民課長","answer":"推進会議等につきましてですけれども、これについては文化芸術・スポーツ振興ビジョンのこれを実施していくための一つの推進組織という形になりますので。","voiceIndex":289,"id":"exchange-117"},{"speaker":"堺委員","kind":"確認","question":"先般、プレス発表していただいた際にお配りした資料の中によりますと、事業目的の中の２番目に、顕彰制度の策定というようなことも触れられておりましたが、私は多分そのことがこの「等」かなというのが、ところが、今そういうお答えがなかったので、ちょっと確認させてください。","respondent":"小野区民課長","answer":"申しわけありませんでした。今委員のご指摘のとおり、顕彰制度の基準等を策定するための経費が含まれております。","voiceIndex":291,"id":"exchange-118"},{"speaker":"堺委員","kind":"質問","question":"じゃあ含まれているですので話を進めしますが、先ほど事業内容についてお尋ねをしたんですが、目的についはご説明いただきましたが、ちょっと内容についてご説明がなかったような気がするんですが。要するに、策定委員会を設置して策定されていくんだろうと思うんですね。その策定委員会の中ですよね。どういう方々が携わってくるのかということをお聞きしたかったんですが、ちょっとお知らせいただけますか。","respondent":"小野区民課長","answer":"幅広く区民の意見を取り入れるという意味で公募の区民、こういう形も含まれておりまして、こういう方々から幅広く意見をいただきながら策定してまいりたいと考えているところです。","voiceIndex":293,"id":"exchange-119"},{"speaker":"堺委員","kind":"質問・要望","question":"どうしても表舞台で頑張る人が表彰の対象になってしまうきらいがあるんですが、先ほどもお話が出ていたのかもしれませんが、やっぱりその人たちが表舞台で活躍できるのには、裏で支えてくださっている方々もたくさんいらっしゃるわけですね。そういう面でそういう方々もやっぱり顕彰の対象に僕は含めていただきたいなと、こんな気がするんですが、その２点ちょっと教えていただけますか。","respondent":"小野区民課長","answer":"区内の団体につきましては、文化の分野につきましては品川文化振興事業団が文化の団体にそれぞれいろいろ関係しておりますし、品川区スポーツ協会あるいはまちという関係では町会連合会、青少年対策地区委員会、それから商工会議所の品川支部、観光協会。","voiceIndex":295,"id":"exchange-120"},{"speaker":"堺委員","kind":"提案","question":"わかりました。それで、１点ちょっと私たちのほうから言うのもおかしいのかもしれませんが、冒頭申し上げましたように、これは議員提案でできた関連のものですから、ぜひ議会側のほうからもこの策定委員会のメンバーに加えてもらいたいというか、選出したほうがいいんじゃないか。どういう言い方をしていいのかよくわかりませんが、その辺のお考えをちょっとお知らせいただけますか。","respondent":"小野区民課長","answer":"今の議員提案による条例です。そのことも含めて検討してまいりたいと考えております。","voiceIndex":297,"id":"exchange-121"},{"speaker":"須貝委員","kind":"質問","question":"私は１５１ページの国際交流推進事業、そして総務費の中にある委員報酬について質問したいと思います。品川区では国際友好都市との交流事業を行っております。姉妹友好都市を中心に外国都市との相互交流として派遣や受け入れをしている。交流都市ともお話をして、当面自粛したらどうでしょうか。地方自治体にとって、外国都市との行き来する交流は必要性があるのかどうか、まずご見解をお聞かせください。","respondent":"伊勢総務課長","answer":"それで、自粛云々ですけれども、経済状況は確かにほかの国も厳しいとは思いますけども、やり方はともかくといたしまして、友好協会を通じて２５周年の公式訪問団等の派遣はやるということになっていますので、この方向で行きたいと考えています。","voiceIndex":300,"id":"exchange-122"},{"speaker":"須貝委員","kind":"質問","question":"今お話を聞いたんですが、この事業を実施する、平和事業云々はあるんですが、区民のためになるのか、あと区民にとって何か利便性があるのか、ちょっと今平和云々という話がありましたが、その辺についてどうなんでしょうかと。そうすると、品川区内に現在１万人以上の外国人の方が住まわれていると。そういうことも必要じゃないかと思うんですが、その点についてご見解をお聞かせください。","respondent":"伊勢総務課長","answer":"やはりだれもが言うのは、向こうに行って、向こうの家庭の中で言葉だけじゃなくて文化に接するとか、いろいろ考え方、そういう国際性が非常に身につくというようなこともありますので、そういう面では非常にこれからの社会を担う青少年にとっては大事なことかなと思っていますし。","voiceIndex":302,"id":"exchange-123"},{"speaker":"須貝委員","kind":"質問","question":"でも、総事業費、このほかに補助金として約１００万円ぐらい、これはあくまで割当ですからね、１００万円ぐらいの割当をしているという現状を考えますと、果たして妥当なのかなというちょっと感想だけ述べします。民間会社の短時間労働の時給と比較して、かなり高いと思いますが、どうしてこんなに高いんですか、教えてください。そして、これは妥当なんでしょうか。","respondent":"市岡総務部長","answer":"私どもはそういう各委員の専門的な知見あるいは学識、あるいはその他の知識、経験、知恵をおかりするということでお支払いをしているものであって、単純に時給で比較するような性格のものとは根本的に違うというふうな考え方で条例で定めている、こういうものです。","voiceIndex":304,"id":"exchange-124"},{"speaker":"須貝委員","kind":"意見","question":"今単純に時給ではかれない、確かにそうでしょう。ですが、この委員の方たちには、品川区のため、品川区民のために協力心ということで、心から協力して審議に出席していただいていると思います。でも、やはり心から協力しているということを考えたら、その辺は品川区としても取り組みの一貫性、一つの信念というのを持つということが必要じゃないかと思うんですが、もう一度お聞かせください。","respondent":"市岡総務部長","answer":"附属機関の委員につきましては、委員十分ご案内のことかと思いますが、議員も含めてその専門的な知見を活用するということで、例えば医師ですとか弁護士ですとか、それぞれ相当の礼を持ってお迎えをするということで、言ってみれば。","voiceIndex":306,"id":"exchange-125"},{"speaker":"須藤委員","kind":"質問","question":"１７０ページの文化スポーツ振興費、１８２ページの防災対策費についてお尋ねしますが、その前に今の質問がちょっとあったので。ある企業経営者が話していました。これはなぜかというと、それをそのまま苦しいとき、「いざ苦しいぞ。でも、は、はっと笑って、よいな」というのが１３９０８８７１４というふうな数字になっているわけです。","respondent":"中山防災課長","answer":"緊急地震速報、日本気象協会との契約を進めておったわけでございまして、そのとき３,２３２万円の予算を計上してございましたが、実際にモバイル放送が今年度末をもって終了するということが７月にわかりましたので、その時点で３,２３２万円予算化したものが。","voiceIndex":309,"id":"exchange-126"},{"speaker":"須藤委員","kind":"質問","question":"わかりました。それから続いて、事業部が変更になったときに、防災対策の平成１９年修正版で、本部第１救助、第２救助、いろいろありますけども、そのあたりはどういうふうになるんでしょうか。違いがしっかり書いてあるんでしょうか。防災のほうでどうなっているのか、もし違いがあれば教えてください。","respondent":"中山防災課長","answer":"それにつきましては、これからの作業になろうかと思います。緊急にやらなければならない作業だと思ってあります。","voiceIndex":311,"id":"exchange-127"},{"speaker":"須藤委員","kind":"質問・要望","question":"４月の改定ですから、そこにすぐ、そういったところも変えていただきたい。それはどういう対象になるのかということもきちんとつくっていただきたいというふうに思います。それから、朝ほどから何点かありましたけど、防災区民組織についてお尋ねをいたします。それと今言った消防団とか、そのあたりとの連携はどうなっているのか教えてください。","respondent":"中山防災課長","answer":"最初の質問ですけど、現在の町会・自治会数が２０３です。大井で２地区減ってありますので２０３です。そのうちの八潮の３自治会を除いた２００が今防災区民組織を編成しているです。","voiceIndex":313,"id":"exchange-128"},{"speaker":"須藤委員","kind":"質問","question":"防災のいろんな対処というのは、これだけやっても１００点ですよというのはなかなかないので、先ほども出ていましたいろんな事業所が今度防災組織の外の関係者として入っていますよ。そういうものと区とどう連携をとる、あるいは自衛隊のほうへまた依頼を出す。それと、防災区民組織とどういうふうに連携するんだ、そのあたりがちょっとはっきり僕らは見えないんだけども、どんなになっているんですかね。","respondent":"中山防災課長","answer":"その上に１３地区の地域センターを中心にした防災協議会があるです。災害の際ですけれども、これは私ども区長を災害対策本部長として災害本部を設置いたしまして、そこからいろんな情報だとか、現地調査だとかということに動くようになってあります。","voiceIndex":315,"id":"exchange-129"},{"speaker":"須藤委員","kind":"質問","question":"消防団の皆さんのおうちも被害に遭う。１７０ページの文化スポーツ振興費、今日はいろんなところで出ていますけども、一つお聞きしたいのは、先ほど担当のお話ですと、品川区芸術祭の準備費も、ビジョンの中から意見をいただいてもらってきます、それに対応しますというような話をしているんだけど、品川区では文化振興事業団という外郭団体がありますよね。","respondent":"小野区民課長","answer":"そのときに、振興ビジョンも前半の中で大きな基本的なところ、枠組みを検討してまいりますので、その議論と並行して進めていって、年度の後半に芸術祭のほうの準備の具体的なところに入っていくというふうなことで。","voiceIndex":317,"id":"exchange-130"},{"speaker":"川西委員","kind":"質問","question":"１５１ページの私立幼稚園預かり保育事業、１５３ページの非核平和都市品川宣言制定２５周年記念事業、それから、地域と在住外国人との交流促進、１５３ページ、職員健康管理費、１５７ページ、マウントしながわ活用事業について伺います。それから二つ目の非核平和都市品川宣言２５周年については、内容をどのように計画して予算を組まれたのか、とりあえずこの二つを伺います。","respondent":"小林保育課長、伊勢総務課長","answer":"二つ目に、障害者保育の対応ですけれども、これは別途一定の要件に該当する者に対して、各園児数に応じて年額２０万円の助成金を区として上乗せ助成を予定しております。これはかなりご高齢になられたと思うんですが、戦争体験をされた方の講話、それからパネル展、あと記念のコンサート、コンサートの中身はまだ詰めていないんですけれども、こういうものを予定しています。","voiceIndex":320,"id":"exchange-131"},{"speaker":"川西委員","kind":"質問・要望","question":"そういうのでよろしくお願いいたします。それから、職員健康管理費の産業医のことで一つ伺います。定期的にどういうふうに何人ぐらいの年間を通して産業医の方と接触、相談があるのか伺います。それから、マウントしながわ活用事業については、平成２０年度から始められたとの記憶ですが、この総括に基づいて、平成２１年度のこの予算は、内容はどういうふうに進められるんでしょうか、伺います。","respondent":"榎本人事課長、小野区民課長","answer":"職員の健康管理の産業医ですけれども、全部で４名います。大体月３回ということで勤務して、いろいろな相談に当たっていただいているところです。里山、これは早川町との山村との交流ですので、里山というのが山村の中でどういうふうに使われていたのか、どういう位置であるのか、生活の中でどんなふうに取り込まれているのかということを体験するということで。","voiceIndex":323,"id":"exchange-132"},{"speaker":"川西委員","kind":"質問","question":"産業医の方の、参加職員の方を年間を通して聞かせてください。それから、今のマウントしながわ活用事業なんですけれども、ボランティアで募集されましたよね。この人たちの意見というのを一言二言教えていただければいいと思います。","respondent":"榎本人事課長、小野区民課長","answer":"産業医の相談件数ですけれども、先ほども出ましたメンタル系のほうの相談件数が増えてきておりまして、年間１００件前後の相談件数があります。参加している方の意見ですけれども、本当に地元の林業組合の人だとか、地元の方たちと一緒に作業するというふうなことで、人と人との直接的なつながりができたということで。","voiceIndex":326,"id":"exchange-133"},{"speaker":"宮崎委員","kind":"質問","question":"私は１５８ページの広報広聴費と、あと長期計画についても伺いたいと思います。これを具体的にどういうふうに仕組みを充実していくのか、今区の考え方について伺いたいと思います。それとあわせて、パブリックコメントの仕組みもありますけども、ここでも充実ということを考えているのかどうなのか、まずここら辺を聞きたいと思います。","respondent":"中川原広報広聴課長","answer":"ここでは、長期基本計画におきます広報広聴の充実というのは、大きく分けると三つあります。一つは、意見交換が活発になる仕組みづくりとしまして、タウンミーティングの開催と新たな広聴手法の検討です。","voiceIndex":330,"id":"exchange-134"},{"speaker":"宮崎委員","kind":"質問","question":"パブリックコメントのところは、この間何回かやられてきておりますけれども、区民意見公募の手続の要綱がありますけども、区民の区政参加および開かれた区政運営の実現ということを目的に掲げておりますけれども、私は広報のあり方、区民意見の募集のあり方というところではまだまだ工夫が必要だなというふうに考えておりますけれども。","respondent":"中川原広報広聴課長","answer":"この実施状況については、おおむね私どもが要綱で予定していました運営がなされてきているというふうに感じておりますので、さらにこれにつきましては各所管にこういった品川区のパブリックコメントの制度の適正な運営をしていくように考えているところです。","voiceIndex":332,"id":"exchange-135"},{"speaker":"宮崎委員","kind":"質問","question":"具体的にこの中身がどういうふうにいくのかというのは、ここには全く書かれておりませんでした。ですから、これは項目で終わっていて、中身がないということですね。区長の要綱のところでは、そういうところまで書いていないんですけれども、どういうふうに思いますか、私はそういう背景等もしっかり広報の中に書いていかないと正確な情報が伝わらないというふうに思うんですけども、どうでしょう。","respondent":"中川原広報広聴課長","answer":"それから懸案によっては特集号を組んだり、そういった一つの記事としてお知らせしていくという、そういった広報紙の役割としてとらえております。","voiceIndex":334,"id":"exchange-136"},{"speaker":"宮崎委員","kind":"質問・要望","question":"これからパブリックコメントが始まりますよと、お知らせ程度だと。例えば、長期計画のところでは、項目だけじゃなくて、やっぱり具体的な中身がどういうふうになろうとしているのか、そこらの概要、骨子などで紙面の限界等はあると思うんですけども、そこの工夫というのが何か必要じゃないのかということなんですけども、そこの意見はどうでしょうか。","respondent":"福島長期計画担当課長","answer":"といいますのも、こちらの基本構想そのものが全部で２００ページを超えるような中身ですので、それをすべて広報紙に載せるということは難しい。ただ、中身を工夫することは大切だとは思いますけども、すべてを伝えることはできないのではないかというふうに思います。","voiceIndex":336,"id":"exchange-137"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今工夫が必要だというふうにおっしゃいましたので、その点の問題意識をもうちょっと伺いたい。そうしないと、内容がちゃんといかないというふうに思うんです。それともう一つ、今時点ではこういう広報の内容について、例えば重要なパブリックコメントの意見をいただく、その内容について、どなたがどういう責任で編集されているのか伺いたいと思います。","respondent":"中川原広報広聴課長","answer":"広報紙の内容の決定につきましては、一応区長が発行するということでやっておりますので、最終決定は区長ということで発行させていただいているものです。","voiceIndex":338,"id":"exchange-138"},{"speaker":"宮崎委員","kind":"質問・要望","question":"その後の検討があるかどうか、いただきたいと思います。私も今アンケートをやっておりまして、その中にもやっぱり新聞をとれないと。今まで説明会というのは私の記憶では最近では後期高齢者医療制度、その前は介護保険とあったんですけど、この間どんな感じでやったのか、その考え方はどういうふうに開催しているのか伺いたいと思います。","respondent":"中川原広報広聴課長","answer":"２３区の状況を見ましても、説明会を要綱でやると言っているところは１区もございませんで、パブリックコメントというのは、ある程度補完という意味から考えて、私どものほうでは。","voiceIndex":340,"id":"exchange-139"},{"speaker":"宮崎委員","kind":"意見","question":"一つ、広報は新聞折り込みがスピード、経費等を考えてということだったんですが、また補完でいろいろ考えるというお話だったんですけども、その中に全戸配布というのは補完の中に入ってくるんじゃないかと思うんですけど、ぜひお願いしたいということと、一斉に入るということが大事だというふうなお話だったんですけど、それは余裕を持って配布すればいいだけの話であって。","respondent":"中川原広報広聴課長","answer":"スピードというのは、やっぱり１週間とか８日もかかっていましたら、次の号がまたでき上がってしまいますので、今までどおりの考え方でいきたいと思います。","voiceIndex":342,"id":"exchange-140"},{"speaker":"三上委員","kind":"質問・要望","question":"私は、１６１ページから１６３ページの財政管理費、契約関係事務費として少々お伺いしていきたいと思います。それから、１８５ページの防災活動拠点管理運営費、時間がありましたら、そのときにまたちょっとお願いしたいと、こう思います。随意契約でやらなきゃならなかったのはどういうことだったのかということについて、簡単でいいですから、お伝えいただきたいと思います。","respondent":"阿部経理課長、中山防災課長","answer":"一番契約の予定価格に近かった業者、今出ましたけど、戸田建設ですけれども、そこと再度起工し直しまして、工期の関係等もございまして随意契約としたですけれども、私どもとしては当然のことながら法令を遵守して契約を行いました。その他の備蓄倉庫、井戸、受水槽の遮断装置、これは飲料水をとるためのものです。それから非常発電装置、電話の優先回線等々はすべて設置しています。","voiceIndex":345,"id":"exchange-141"},{"speaker":"三上委員","kind":"確認","question":"私はちょっと確認だけしておきたい。価格だけでなくて、履行能力ということでありますけれども、それについて私は一つ総合評価方式でやった中で、便所の消臭装置ほか賃貸等についての契約ということについての平成１７年度、１８年度、１９年度、２０年度の、この流れというものがどういうことであったのか、簡単でいいですからご説明していただけますか。","respondent":"阿部経理課長、中山防災課長","answer":"１点目のＪＶの件ですけれども、ご承知のように、荏原西地区については３社ＪＶを置きました。再度ＪＶを組み直すといたしますと、最低でもやっぱり１カ月半ぐらいの期間が必要になってまいります。今ご提案になりました井戸水を使ってマンホールトイレというお話ですが、下水道局が下水道のマンホールを耐震化しまして、そこに仮設トイレをつけて、そのまま下水道に流せるような箇所が１９カ所区内に既にできてあります。","voiceIndex":348,"id":"exchange-142"},{"speaker":"三上委員","kind":"質問","question":"くみ取り式であるならば、いずれいっぱいになれば、それをどう処分するかという問題が起きる。しかし、水洗式ということになるならば、井戸水を利用してできるわけですから、そういったことでの検討は今後やっぱり拡大させていくということでいいんじゃないでしょうか。あわせて、障害者の方が利用できるような、大きなテント型の手すりのついたテントも用意してもいいんじゃないかと。","respondent":"阿部経理課長","answer":"平成１７年度が１,３７９万円余です。平成１８年度が１,３４８万円余です。平成１９年度につきましては、４１９万円余です。","voiceIndex":351,"id":"exchange-143"},{"speaker":"三上委員","kind":"意見","question":"平成１９年度でとったときは４００万円で落札しているわけですよね。その翌年に簡易型総合評価方式を品川区で設置して、それでやった結果、参考見積額で品川区としては１,２４７万円で出していますよね。前年度４１９万円、その前の年はダンピングして、そこのところが負けたんでしょう。そこらあたりの、価格というものは３倍に一遍に上がるということについてどう思っているのか。","respondent":"阿部経理課長","answer":"平成１９年度につきましては、４１０万円代ということでございましたので、そういう検討も考慮に入れまして、先ほど申し上げたとおり価格点だけではなくて、履行能力が十分なのかどうか、そういうことも含めて業者を選定するという形で、これを入れたものです。","voiceIndex":353,"id":"exchange-144"},{"speaker":"鈴木（真）委員","kind":"質問","question":"質問としましては、１６１ページ、区民相談経費の中から、犯罪被害者支援の関係、それから１６３ページ、今包括契約が出ていたんですが、その辺の関係と、あと１６７ページの町会・自治会館建設補助関係、１６９ページ、ふれあいサポート推進経費、全体的にまず、職員費の関係等をお聞きしたいところがあります。それから、町会・自治会館建設補助ということでは、先ほど来質問が出ておりました。","respondent":"中川原広報広聴課長、中山地域活動課長","answer":"もう一つの支援協力員というのは、ここから病院とか裁判とか行政手続とかに、その方がお一人で行くのはつらいというときに付き添ってサポートをするという活動なんですが、これにつきましても、支援協力員を６人委嘱しまして。町会・自治会館の建設補助の考え方は、町会会館を新築・改築する場合および既設の建物を購入する場合も対象にしておりまして、２分の１助成、最大限度１,８００万円ということで助成しているわけですが。","voiceIndex":356,"id":"exchange-145"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今いった法テラスとかつなぎの部分になると思うんですけど、その辺の指導体制をよろしくお願いしたいと思います。それともう一つ、ふれあいサポートから、けさ企画財政課長の説明の中で、たしか災害時要援護者支援が防災対策費へ変更になったというふうに私はちょっと聞こえたんですけど、これは今までふれあいサポートでやっていた部分が防災課の担当になるという、そういう意味なんでしょうか。","respondent":"榎本人事課長、中山地域活動課長","answer":"その差なんですけれども、ちょっと職員も定数では減しても、すぐ頭数がいなくなるという形ではないのでなかなか出し方が難しいんですが、大ざっぱにやりますと。ふれあいサポートの配食サービスの中学校から配食されていた夕食につきましては、区民委員会でもご説明申し上げたとおり、商店街からの配食に変わるということで、その結果として。","voiceIndex":359,"id":"exchange-146"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"委託に関しては、これからも行政サービスが低下しないということが大前提だと思うんですが、その辺で区政運営のためにもぜひ詰めていっていただきたい部分だと思っています。その辺で、これからもどういうふうになるのかなという感覚、ちょっとあればと思います。","respondent":"中山地域活動課長","answer":"ふれあいサポートのさまざまな事業の中で、例えばふれあい健康塾のように健康課所管の事業であったり、高年者懇談会のように社会福祉協議会の予算でやっているもの、予算的には地域活動課直轄のものでないものをさまざまやっているわけですが、ただ、そういうことによって。","voiceIndex":362,"id":"exchange-147"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひこれからもふれあいサポートをきちんと進めていっていただきたいということは要望にします。技術職の方の、この前本会議で質問させていただきましたけど、その技術的なものの継承、その辺が非常に重要になってきているような気がするんですけど、設計と現場の関係といった点ではどうなんでしょうか。","respondent":"宍戸施設担当課長","answer":"技術の継承ですが、改修工事につきましては、我々のほうがむしろ委託業者よりも長年やっておりますのでプロというふうに思っております。その点も踏まえまして、技術の継承については心がけていきたいと考えています。","voiceIndex":364,"id":"exchange-148"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最後にします。区の計画がこういうふうになっているよということは１００％伝えていってほしいし、それによってまたきちんとした設計ができて、最終的に安全な改修ができたということにしていただきたいと思いますので、これからも努力のほう、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":366,"id":"exchange-149"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=914#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":127988,"voices":367}}]);
